KB.lade("skandinavien",[{"id":"skandinavien-koettbullar","name":"Köttbullar","originalname":"Svenska köttbullar","kueche":"skandinavien","region":"Schweden","beliebtheit":94,"hauptkategorie":"fleisch","fleischsorte":"hackfleisch","gang":"hauptgericht","kurz":"Zarte, saftige Hackfleischbällchen mit Piment, cremiger Bratensauce, Kartoffeln, Preiselbeeren und Gurkensalat – das Gericht, das Schweden weltberühmt gemacht hat.","hintergrund":"Das Wort köttbulle taucht zum ersten Mal in Cajsa Wargs Kochbuch von 1755 auf; zuvor sprach man eher von Frikadellen. Richtig beliebt wurden die Bällchen in Schweden in der Mitte des 19. Jahrhunderts, als Fleischwölfe in die Haushalte kamen. IKEA nahm sie 1985 in seine Restaurants auf und trug sie in die ganze Welt. Die oft erzählte Geschichte, König Karl XII. habe das Rezept aus dem Osmanischen Reich mitgebracht, hält Nahrungsmittelhistoriker Richard Tellström für nicht belegt. Klassisch kommen die Köttbullar mit brauner Sauce, Kartoffeln, Preiselbeeren und eingelegten Gurken auf den Tisch.","portionen":4,"zeit":{"vorbereitung":30,"garen":35,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Köttbullar","liste":[{"menge":50,"einheit":"g","name":"Semmelbrösel","hinweis":"oder entrindetes, fein zerzupftes Toastbrot"},{"menge":100,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":50,"einheit":"ml","name":"Milch","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel (ca. 80 g)","hinweis":"sehr fein gewürfelt"},{"menge":1,"einheit":"EL","name":"Butter","hinweis":"zum Anschwitzen der Zwiebel"},{"menge":500,"einheit":"g","name":"gemischtes Hackfleisch","hinweis":"halb Rind, halb Schwein; je fettärmer, desto trockener"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"weißer Pfeffer","hinweis":"frisch gemahlen"},{"menge":0.5,"einheit":"TL","name":"gemahlener Piment (Nelkenpfeffer)","hinweis":"gibt es in der Gewürzabteilung; typisch schwedisch"},{"menge":1,"einheit":"EL","name":"Butter und 1 EL neutrales Öl","hinweis":"zum Braten"}]},{"gruppe":"Für die Sauce","liste":[{"menge":30,"einheit":"g","name":"Butter","hinweis":""},{"menge":25,"einheit":"g","name":"Weizenmehl","hinweis":""},{"menge":300,"einheit":"ml","name":"Rinderfond","hinweis":"heiß"},{"menge":100,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"TL","name":"Sojasauce","hinweis":"für Farbe und Würze, ein verbreiteter Küchentrick in Schweden"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":800,"einheit":"g","name":"festkochende Kartoffeln","hinweis":""},{"menge":150,"einheit":"g","name":"Preiselbeeren","hinweis":"aus dem Glas oder selbst eingekocht"},{"menge":1,"einheit":"Stück","name":"Salatgurke für Pressgurka","hinweis":"dünn gehobelt, mit Essig, Zucker und Salz mariniert"}]}],"ausruestung":["große Pfanne","Topf für Kartoffeln","kleine Schüssel für die Panade","Holzlöffel oder Schneebesen"],"schritte":[{"titel":"Zutaten abwiegen und vorbereiten","aktion":"vorbereiten","text":"Wiege Semmelbrösel, Hackfleisch, Mehl und Butter ab und stelle Sahne und Milch bereit. Schäle die Zwiebel und würfele sie so fein wie möglich, die Stückchen sollten höchstens 2 mm groß sein, damit sie in den Bällchen nicht als Bissen auffallen. Schäle die Kartoffeln, halbiere größere Knollen und lege sie in kaltes Wasser. Hebe dir außerdem eine kleine Schüssel mit kaltem Wasser neben die Arbeitsfläche, mit der du später deine Hände befeuchtest. Das Hackfleisch darf bis zum Kneten im Kühlschrank bleiben, kalt lässt es sich später besser binden.","dauer":0,"tipp":""},{"titel":"Panade quellen lassen","aktion":"mischen","text":"Verrühre die Semmelbrösel mit Sahne und Milch in einer kleinen Schüssel und lass die Mischung 10 bis 15 Minuten ruhen. In dieser Zeit saugen die Brösel die Flüssigkeit auf und bilden eine weiche Paste, die ein Schlüssel zu saftigen Bällchen ist. Sie bindet Fleischsaft beim Braten und verhindert, dass die Köttbullar trocken und fest werden. Die Masse soll beim Anheben mit dem Löffel langsam abtropfen und nicht mehr flüssig sein; ist sie noch zu nass, gib einen Esslöffel Brösel dazu.","dauer":15,"tipp":"Wer nicht trocken-festes Hack mag, nimmt eher etwas mehr Panade als zu wenig."},{"titel":"Zwiebel sanft anschwitzen","aktion":"anbraten","text":"Erhitze einen Esslöffel Butter in einer kleinen Pfanne bei niedriger bis mittlerer Hitze und lass die fein gewürfelte Zwiebel darin 4 bis 5 Minuten glasig werden, ohne dass sie Farbe nimmt. Sie soll weich und süßlich duften, aber nicht gebräunt sein, sonst bekommen die Bällchen eine zu kräftige Röstnote. Nimm die Zwiebel vom Herd und lass sie auf einem Teller vollständig abkühlen, bevor sie ins Fleisch kommt; heiße Zwiebeln würden das Fett im Hack anschmelzen und den Teig schmierig machen.","dauer":6,"tipp":""},{"titel":"Fleischteig kneten","aktion":"kneten","text":"Gib Hackfleisch, die gequollene Panade, die abgekühlte Zwiebel, das Ei, Salz, weißen Pfeffer und Piment in eine große Schüssel. Knete alles mit nassen Händen oder in der Küchenmaschine mit Flachrührer etwa 3 bis 4 Minuten kräftig durch, bis die Masse hell, klebrig und gut gebunden ist und sich von der Schüsselwand löst. Dieses längere Kneten gibt den Bällchen ihre typische zarte, fast lockere Textur. Brate dann ein kleines Probebällchen in der Pfanne und probiere: Die Würze sollte deutlich schmecken, denn die Sauce und die Beilagen bringen noch Süße und Säure mit.","dauer":5,"tipp":"Das Probebällchen vermeidet böse Überraschungen: lieber jetzt nachwürzen als am Tisch."},{"titel":"Bällchen formen","aktion":"formen","text":"Befeuchte deine Handflächen mit kaltem Wasser und forme aus der Masse kleine Kugeln mit etwa 3 cm Durchmesser, das sind rund 20 g oder die Größe einer Walnuss. Lege sie nebeneinander auf ein mit Wasser befeuchtetes Brett oder einen Teller. Aus der Menge entstehen etwa 30 Stück. Kleine Bällchen garen schnell durch und bekommen mehr Kruste im Verhältnis zum Inneren, genau wie es für Köttbullar typisch ist. Stelle sie 10 Minuten in den Kühlschrank, damit sie beim Braten besser in Form bleiben.","dauer":10,"tipp":""},{"titel":"Kartoffeln kochen","aktion":"kochen","text":"Setze die geschälten Kartoffeln mit kaltem Wasser und einem gestrichenen Teelöffel Salz auf und bringe sie zum Kochen. Lass sie bei mittlerer Hitze 20 bis 25 Minuten garen, bis ein Messer ohne Widerstand hineingleitet. Gieße sie ab, lasse sie 2 Minuten im offenen Topf ausdampfen und halte sie mit aufgelegtem Deckel warm. Wer mag, schwenkt sie kurz in etwas Butter und streut gehackte Petersilie darüber. Zeitlich kannst du das parallel zum Braten der Bällchen erledigen.","dauer":22,"tipp":""},{"titel":"Köttbullar braten","aktion":"braten","text":"Erhitze Butter und Öl in einer großen Pfanne bei mittlerer Hitze, bis die Butter schäumt und nach Nuss duftet. Setze die Bällchen in einer Lage hinein, ohne die Pfanne zu überfüllen, und brate sie 8 bis 10 Minuten unter häufigem Schwenken, damit sie rundum gleichmäßig braun werden. Sie sind fertig, wenn sie außen goldbraun sind, sich beim Drücken leicht federnd anfühlen und im Inneren mindestens 70 °C haben. Brate in zwei Chargen, hebe die fertigen Bällchen heraus und lasse den Bratfond in der Pfanne, denn der bildet die Basis der Sauce.","dauer":12,"tipp":""},{"titel":"Bratensauce zubereiten","aktion":"binden","text":"Gib 30 g Butter in die Bratpfanne mit dem Fond und lass sie bei mittlerer Hitze schmelzen. Streue das Mehl darüber und rühre 1 bis 2 Minuten, bis eine hellbraune Schwitze entsteht, die nussig riecht. Gieße nach und nach den heißen Rinderfond unter ständigem Rühren mit dem Schneebesen hinzu, damit keine Klümpchen entstehen, und lass die Sauce 5 Minuten leise köcheln. Rühre Sahne und Sojasauce ein, schmecke mit Salz und weißem Pfeffer ab und gib die Bällchen für 2 Minuten zurück in die Sauce. Die Sauce soll samtig sein und den Löffelrücken bedecken.","dauer":8,"tipp":"Ist die Sauce zu dick, mit einem Schuss Fond verdünnen; ist sie zu dünn, noch ein paar Minuten einkochen."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte die Köttbullar mit reichlich Sauce auf vorgewärmten Tellern an und lege die Kartoffeln daneben. Gib einen großen Löffel Preiselbeeren an den Tellerrand; ihre fruchtige Säure schneidet durch Fett und Sahne und gehört unverzichtbar dazu. Dazu passt ein Häufchen Pressgurka, hauchdünn gehobelte Gurke, die mit einer Mischung aus Essig, Zucker und Salz mariniert wurde. Bestreue das Ganze nach Belieben mit gehackter Petersilie und serviere sofort.","dauer":0,"tipp":""}],"profitipps":["Weiche Panade aus Brösel und Sahne macht die Bällchen saftig – nicht weglassen.","Das Fleisch lange und kräftig kneten, bis es klebrig wird: So bekommen die Köttbullar ihre feine, zarte Konsistenz.","Schwenke die Bällchen in der Pfanne ständig, damit sie rund bleiben und nicht an einer Seite abflachen.","Piment (Nelkenpfeffer) und weißer Pfeffer sind die typisch schwedische Würze; Muskat ist eine häufige Ergänzung.","Köttbullar lassen sich hervorragend einfrieren: roh geformt auf einem Blech vorfrieren und später direkt braten."],"varianten":["Finnische Lihapullat mit etwas Rinder- und Schweinefleisch und manchmal Elch oder Rentier","Dänische Frikadeller, flacher gebraten, mit Zwiebel und Milch im Teig","Ohne Sauce als Fingerfood auf dem Julbord mit Senfsauce","Mit Rinder-Wild-Mischung als festliche Variante"],"beilagen":["Kartoffeln oder Kartoffelpüree","Preiselbeeren","Pressgurka (Gurkensalat)","eingelegte Gurken"],"getraenk":"Schwedisches Pilsner oder Lager, alkoholfrei: Lättöl oder Apfelsaftschorle.","koeche":[{"name":"Magnus Nilsson","bezug":"Sein Buch The Nordic Cookbook (Phaidon, 2015) dokumentiert die Alltagsküche aller nordischen Länder und enthält die klassischen Hausmannsgerichte wie Köttbullar.","quelle":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"quellen":[{"titel":"Meatball – Wikipedia (Abschnitt Schweden und Finnland)","url":"https://en.wikipedia.org/wiki/Swedish_meatballs"},{"titel":"Magnus Nilsson – Wikipedia","url":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"bild":"eintopf","farben":["#8a4b2a","#c98a52","#b5262d"],"schlagworte":["Schweden","IKEA","Klassiker","Hausmannskost"],"vegetarisch_moeglich":false},{"id":"skandinavien-kanelbullar","name":"Kanelbullar","originalname":"Kanelbullar","kueche":"skandinavien","region":"Schweden","beliebtheit":88,"hauptkategorie":"suess","fleischsorte":"","gang":"gebaeck","kurz":"Weiche, duftende Hefeschnecken mit Zimt und Kardamom und knusprigem Hagelzucker – das Herzstück jeder schwedischen Fika.","hintergrund":"Kanelbullar sind aus der schwedischen Kaffeepause, der Fika, nicht wegzudenken. Zimtschnecken gehen auf deutsche Rezepte aus dem 16. Jahrhundert zurück, die sich über Hansekaufleute im Norden verbreiteten. In ihrer heutigen schwedischen Form entstanden sie nach dem Ersten Weltkrieg. Typisch ist Kardamom im Teig und Hagelzucker obenauf. Am 4. Oktober feiert man in Schweden seit 1999 den Kanelbullens dag. Auch in Dänemark (kanelsnegl), Norwegen (skillingsboller) und Finnland (korvapuusti) gibt es eigene Varianten.","portionen":14,"zeit":{"vorbereitung":45,"garen":12,"ruhen":100},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig","liste":[{"menge":500,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"plus etwas zum Bestäuben"},{"menge":21,"einheit":"g","name":"frische Hefe","hinweis":"oder 1 Päckchen Trockenhefe (7 g)"},{"menge":250,"einheit":"ml","name":"Milch","hinweis":"lauwarm, ca. 37 °C"},{"menge":75,"einheit":"g","name":"Butter","hinweis":"geschmolzen und abgekühlt"},{"menge":75,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"TL","name":"gemahlener Kardamom","hinweis":"am besten frisch aus ca. 12 Kapseln gemörsert"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M"}]},{"gruppe":"Füllung","liste":[{"menge":100,"einheit":"g","name":"Butter","hinweis":"sehr weich"},{"menge":80,"einheit":"g","name":"brauner Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Zimt","hinweis":"gemahlen, am besten Ceylon"}]},{"gruppe":"Zum Bestreichen und Bestreuen","liste":[{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"verquirlt mit 1 EL Milch"},{"menge":2,"einheit":"EL","name":"Hagelzucker (Perlzucker)","hinweis":"aus der Backabteilung"}]}],"ausruestung":["Küchenmaschine mit Knethaken (oder kräftige Hände)","Nudelholz","Backbleche mit Backpapier","Papierförmchen (optional)","scharfes Messer oder Teigkarte"],"schritte":[{"titel":"Zutaten abwiegen und bereitstellen","aktion":"vorbereiten","text":"Wiege Mehl, Zucker und Salz ab, zerstoße die Kardamomkapseln im Mörser und siebe die schwarzen Samen von den Hülsen, bis du etwa 2 Teelöffel Pulver hast. Er duftet intensiv nach Zitrusfrüchten, Blüten und Würze und ist die Seele schwedischer Zimtschnecken. Schmelze die Butter und lass sie abkühlen, damit sie die Hefe nicht tötet. Nimm die Butter für die Füllung rechtzeitig aus dem Kühlschrank, denn sie muss richtig weich und streichfähig sein, sonst reißt sie später den Teig.","dauer":0,"tipp":""},{"titel":"Hefe aktivieren und Teig kneten","aktion":"kneten","text":"Erwärme die Milch auf etwa 37 °C, sie soll sich lauwarm anfühlen, nicht heiß. Zerbröckele die Hefe hinein und verrühre sie, bis sie sich aufgelöst hat. Gib Mehl, Zucker, Salz, Kardamom, Ei und die abgekühlte Butter dazu und knete den Teig 8 bis 10 Minuten in der Küchenmaschine auf mittlerer Stufe oder 12 bis 15 Minuten von Hand. Er ist fertig, wenn er glatt, geschmeidig und leicht klebrig ist und sich vom Schüsselrand löst. Mit einem Fenstertest prüfst du es: Ziehe ein Stück Teig auseinander, es sollte dünn und fast durchsichtig werden, ohne zu reißen.","dauer":10,"tipp":""},{"titel":"Teig gehen lassen","aktion":"gehen","text":"Forme den Teig zu einer Kugel, lege ihn in eine leicht geölte Schüssel und decke ihn mit einem feuchten Tuch oder Frischhaltefolie ab. Lasse ihn an einem warmen Ort etwa 60 bis 75 Minuten gehen, bis er sein Volumen etwa verdoppelt hat. Prüfe mit dem Fingertest: Drückst du ein Loch in den Teig, soll es sich langsam und nur halb zurückbilden. Ist die Küche kühl, stelle die Schüssel in den ausgeschalteten Ofen mit eingeschaltetem Licht.","dauer":70,"tipp":""},{"titel":"Ausrollen und füllen","aktion":"ausrollen","text":"Bestäube die Arbeitsfläche leicht mit Mehl, drücke die Luft aus dem Teig und rolle ihn zu einem Rechteck von etwa 40 x 50 cm und 4 bis 5 mm Dicke aus. Verrühre die weiche Butter mit braunem Zucker und Zimt zu einer gleichmäßigen Paste und verstreiche sie mit einem Löffelrücken oder einer Palette gleichmäßig bis zum Rand. Lass an der langen Seite, an der du später zumachst, 1 cm frei. Eine dünne, aber vollständige Füllung gibt jedem Biss Aroma, ohne dass beim Backen Zucker verbrennt.","dauer":10,"tipp":""},{"titel":"Aufrollen und schneiden","aktion":"rollen","text":"Rolle den Teig von der langen Seite her fest auf, damit die Schnecken nachher schön aufgehen, und drücke die Naht leicht an. Schneide die Rolle mit einem scharfen Messer oder gespannten Zahnseide in etwa 3 cm breite Scheiben; das ergibt 14 bis 16 Stück. Setze jede Schnecke mit der Schnittfläche nach oben in ein Papierförmchen oder auf das mit Backpapier belegte Blech, mit etwa 3 cm Abstand. Drücke sie leicht flach, damit sie gleichmäßig aufgehen.","dauer":10,"tipp":""},{"titel":"Zweite Gare","aktion":"gehen","text":"Decke die Schnecken mit einem Tuch ab und lasse sie 30 bis 40 Minuten bei Zimmertemperatur gehen, bis sie deutlich aufgegangen sind und sich weich anfühlen. Währenddessen heizt du den Ofen auf 220 °C Ober-/Unterhitze (200 °C Umluft) vor. Wenn du sie über Nacht im Kühlschrank gehen lässt, bekommen sie noch mehr Aroma; dann 30 Minuten vor dem Backen herausnehmen.","dauer":35,"tipp":""},{"titel":"Bestreichen und backen","aktion":"backen","text":"Bestreiche die Schnecken mit verquirltem Ei und Milch und streue Hagelzucker darüber. Backe sie auf der mittleren Schiene 10 bis 12 Minuten, bis sie goldbraun sind und intensiv nach Zimt und Kardamom duften. Das kurze, heiße Backen hält sie weich und saftig. Zu langes Backen macht sie trocken. Prüfe mit einem leichten Klopfen auf die Unterseite: Sie klingt hohl, wenn sie durch ist.","dauer":12,"tipp":""},{"titel":"Abkühlen und genießen","aktion":"kuehlen","text":"Ziehe die Bleche aus dem Ofen und lasse die Schnecken auf einem Gitter 10 bis 15 Minuten abkühlen. Frisch und noch lauwarm schmecken sie am besten, vor allem zu einer Tasse Kaffee oder Tee. Wer sie länger aufbewahren möchte, verpackt sie luftdicht und friert sie ein; zum Aufbacken 5 Minuten bei 180 °C in den Ofen geben. Dazu gehört in Schweden ein schwarzer Kaffee, ein Gespräch und Zeit – eben Fika.","dauer":12,"tipp":""}],"profitipps":["Frisch gemahlener Kardamom macht den Unterschied: Er duftet intensiv und gibt den typischen Geschmack.","Der Teig soll leicht klebrig bleiben, dann werden die Bullar weich; zu viel Mehl macht sie trocken.","Kurz und heiß backen: 10 bis 12 Minuten bei 220 °C halten die Schnecken saftig.","Hagelzucker ist nicht nur Dekoration; er gibt den knusprigen Biss und verbrennt nicht.","Schnecken lassen sich roh einfrieren und später direkt gehen lassen und backen."],"varianten":["Kardemummabullar mit Kardamom statt Zimt in der Füllung","Dänische Kanelsnegle, oft mit Remonce und Zuckerguss","Finnisches Korvapuusti, besonders groß und mit Hagelzucker","Mit Vanillecreme und Rosinen als Variante"],"beilagen":["Kaffee","Tee","Milch"],"getraenk":"Schwarzer Filterkaffee (Fika), Tee oder kalte Milch.","koeche":[{"name":"Magnus Nilsson","bezug":"Sein Buch The Nordic Baking Book (Phaidon, 2018) widmet sich dem Backen im ganzen Norden, wo Zimt- und Kardamomschnecken zum Kern der Backtradition zählen.","quelle":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"quellen":[{"titel":"Cinnamon roll – Wikipedia","url":"https://en.wikipedia.org/wiki/Cinnamon_roll"},{"titel":"Magnus Nilsson – Wikipedia","url":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"bild":"gebaeck","farben":["#b8743a","#e0b077","#5a2d12"],"schlagworte":["Fika","Hefegebäck","Zimt","Kardamom"],"vegetarisch_moeglich":true},{"id":"skandinavien-gravlax-mit-hovmaestarsas","name":"Gravlax mit Hovmästarsås","originalname":"Gravlax med hovmästarsås","kueche":"skandinavien","region":"Schweden","beliebtheit":84,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"vorspeise","kurz":"Mit Salz, Zucker und viel Dill gebeizter Lachs, hauchdünn aufgeschnitten und mit süß-würziger Senf-Dill-Sauce serviert.","hintergrund":"Der Name Gravlax setzt sich aus dem nordgermanischen Wort für graben und lax, Lachs, zusammen. Im Mittelalter pökelten Fischer den Lachs und vergruben ihn leicht fermentiert im Sand oberhalb der Flutlinie; die älteste Erwähnung stammt aus dem Jahr 1348. Heute wird er nicht mehr fermentiert, sondern nur noch mit Salz, Zucker und Dill gebeizt. Serviert wird er in dünnen Scheiben als Vorspeise auf dem Julbord und beim Osterbuffet, mit Hovmästarsås, auf Brot oder zu gekochten Kartoffeln. Die Sauce heißt in Schweden gravlaxsås, in Dänemark rævesovs und in Norwegen sennepssaus.","portionen":6,"zeit":{"vorbereitung":30,"garen":0,"ruhen":2880},"schwierigkeit":2,"zutaten":[{"gruppe":"Gravlax","liste":[{"menge":600,"einheit":"g","name":"Lachsfilet mit Haut, Mittelstück","hinweis":"frisch in Sushi-Qualität oder tiefgekühlt gewesen; Gräten ziehen lassen"},{"menge":40,"einheit":"g","name":"grobes Meersalz","hinweis":"kein Jodsalz mit Rieselhilfe"},{"menge":40,"einheit":"g","name":"Zucker","hinweis":"weiß oder hellbraun"},{"menge":1,"einheit":"EL","name":"weiße Pfefferkörner","hinweis":"grob zerstoßen"},{"menge":1,"einheit":"Bund","name":"frischer Dill","hinweis":"groß, ca. 60 g, grob gehackt samt Stielen"}]},{"gruppe":"Hovmästarsås","liste":[{"menge":3,"einheit":"EL","name":"süßer Senf","hinweis":"oder mittelscharfer Senf mit 1 TL Honig"},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"EL","name":"weißer Weinessig","hinweis":""},{"menge":80,"einheit":"ml","name":"Rapsöl","hinweis":""},{"menge":2,"einheit":"EL","name":"Dill","hinweis":"fein gehackt"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":500,"einheit":"g","name":"kleine Kartoffeln","hinweis":"neue Kartoffeln, gekocht"},{"menge":6,"einheit":"Scheibe","name":"Roggenbrot","hinweis":"dünn geschnitten"}]}],"ausruestung":["Backblech oder flache Form","Frischhaltefolie","Brett und 1 kg Gewicht (z. B. Konservendosen)","langes, sehr scharfes Messer","Pinzette für Gräten"],"schritte":[{"titel":"Lachs prüfen und vorbereiten","aktion":"vorbereiten","text":"Kaufe den Lachs möglichst frisch oder verwende tiefgefrorene Ware, die mindestens 24 Stunden bei minus 20 °C lag; dieses Einfrieren tötet Parasiten ab, denn beim Beizen wird der Fisch nicht erhitzt. Taue ihn im Kühlschrank vollständig auf, tupfe ihn trocken und fahre mit dem Finger gegen die Faserrichtung über das Filet, um Gräten zu ertasten. Ziehe sie mit der Pinzette heraus. Schneide den Lachs in zwei gleich große Stücke, die später aufeinandergelegt werden.","dauer":0,"tipp":""},{"titel":"Beize anrühren","aktion":"mischen","text":"Vermische Salz, Zucker und die zerstoßenen Pfefferkörner in einer kleinen Schüssel. Das Verhältnis von Salz zu Zucker ist etwa 1 zu 1, es entzieht dem Fisch Wasser, würzt ihn gleichmäßig und festigt das Fleisch. Hacke den Dill grob samt Stielen, denn sie enthalten besonders viel Aroma. Das Gemisch sollte knirschend trocken sein und angenehm nach Pfeffer und Dill riechen.","dauer":0,"tipp":""},{"titel":"Fisch einreiben und mit Dill belegen","aktion":"marinieren","text":"Lege ein Stück Frischhaltefolie großzügig auf ein Blech und streue ein Drittel der Beize darauf. Setze das erste Lachsstück mit der Hautseite nach unten darauf, bestreue die Fleischseite mit der Hälfte der restlichen Beize und gib die Hälfte des Dills darauf. Lege das zweite Stück mit der Fleischseite nach unten auf das erste, sodass die Hautseiten außen liegen, und verteile den Rest von Beize und Dill. Wickle alles fest in die Folie ein.","dauer":10,"tipp":""},{"titel":"Beschweren und im Kühlschrank beizen","aktion":"einlegen","text":"Lege den Fisch in eine Form oder auf ein Blech mit Rand, denn es tritt Flüssigkeit aus. Lege ein Brett darauf und beschwere es mit etwa 1 kg, zum Beispiel Konservendosen. Stelle alles in den Kühlschrank. Wende den Fisch alle 12 Stunden und gieße die ausgetretene Flüssigkeit weg oder löffele sie über den Fisch. Nach 36 bis 48 Stunden ist der Lachs fest, die Oberfläche glasig und die Beize hat sich in eine Lake verwandelt.","dauer":2850,"tipp":"Für milderen Gravlax 36 Stunden beizen, für kräftigeren 48 Stunden."},{"titel":"Hovmästarsås rühren","aktion":"mischen","text":"Verrühre Senf, Zucker und Essig in einer Schüssel. Gieße das Öl in dünnem Strahl unter ständigem Rühren mit dem Schneebesen dazu, bis eine glänzende, cremige Sauce entsteht, die an eine lockere Mayonnaise erinnert. Rühre den fein gehackten Dill unter, schmecke mit Salz und weißem Pfeffer ab. Sie soll süßlich, würzig und leicht säuerlich sein, dazu passt sie perfekt zum salzigen Fisch. Lasse sie 30 Minuten im Kühlschrank durchziehen.","dauer":30,"tipp":""},{"titel":"Lachs abtupfen","aktion":"abseihen","text":"Wickle den Lachs aus der Folie aus, streife Dill und Gewürzreste mit dem Rücken eines Messers ab und tupfe ihn mit Küchenpapier gründlich trocken. Wasche ihn nicht ab, damit er sein Aroma behält; ist er zu salzig, tupfe ihn kurz mit einem feuchten Tuch ab. Lege ihn mit der Hautseite nach unten auf ein Schneidebrett. Er sollte fest, aber nachgiebig sein und nach Dill duften.","dauer":0,"tipp":""},{"titel":"In dünne Scheiben schneiden","aktion":"schneiden","text":"Schneide den Gravlax mit einem langen, sehr scharfen Messer in dünne Scheiben, indem du das Messer flach ansetzt und in einem Winkel von etwa 30 Grad von der Schwanzseite schräg zur Haut hin durch das Fleisch ziehst. Die Scheiben sollen etwa 2 bis 3 mm dick sein. Lass die Haut zurück, sie braucht nicht mitgegessen zu werden. Lege die Scheiben leicht überlappend auf einer Platte aus.","dauer":10,"tipp":"Ein Messer, das richtig scharf ist, ist wichtiger als jede Technik."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte den Gravlax auf Tellern an, gib einen Löffel Hovmästarsås daneben und garniere mit Dillspitzen und einer Zitronenspalte. Reiche dazu lauwarme, neue Kartoffeln mit Dill oder dünn geschnittenes Roggenbrot mit Butter. Wer mag, serviert gekochte Eier und etwas Gurkensalat. Gravlax hält sich, gut verpackt, im Kühlschrank etwa 5 Tage.","dauer":0,"tipp":""}],"profitipps":["Nur sehr frischen oder vorher eingefrorenen Lachs verwenden; ungekochter Fisch muss einwandfrei sein.","Grobes Salz ohne Zusätze ist ideal; es zieht gleichmäßig Wasser.","Beschweren sorgt für festes, gleichmäßig gebeiztes Fleisch.","Mit einem sehr scharfen langen Messer schräg schneiden, dann werden die Scheiben hauchdünn.","Zusätzliche Aromen wie Wacholder, Dill-Samen, Rote Bete oder Gin sind beliebt, aber Dill, Salz und Zucker sind der Kern."],"varianten":["Mit Rote-Bete-Beize für leuchtend rotes Fleisch","Mit Wodka, Aquavit oder Gin in der Beize","Mit Wacholder und Zitronenschale","Als Gravad Laks auf Smørrebrød in Dänemark"],"beilagen":["Hovmästarsås","neue Kartoffeln","Roggenbrot","gekochte Eier","Gurkensalat"],"getraenk":"Eiskalter Aquavit, trockener Riesling oder ein helles Pils.","koeche":[{"name":"Magnus Nilsson","bezug":"The Nordic Cookbook (Phaidon, 2015) sammelt die traditionelle Küche aller nordischen Länder, zu der der gebeizte Lachs als fester Bestandteil gehört.","quelle":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"quellen":[{"titel":"Gravlax – Wikipedia","url":"https://en.wikipedia.org/wiki/Gravlax"},{"titel":"Magnus Nilsson – Wikipedia","url":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"bild":"fisch","farben":["#e08a5b","#f5c9a3","#5b8a4a"],"schlagworte":["Julbord","Lachs","Dill","Vorspeise"],"vegetarisch_moeglich":false},{"id":"skandinavien-sill-drei-sorten","name":"Sill – eingelegter Hering in drei Sorten","originalname":"Inlagd sill, senapssill, currysill","kueche":"skandinavien","region":"Schweden (Midsommar- und Julbord-Tradition)","beliebtheit":80,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"vorspeise","kurz":"Die drei Klassiker des schwedischen Buffets: süß-säuerlicher Inlagd sill, cremiger Senapssill und Currysill mit Apfel – ohne sie gibt es weder Midsommar noch Julbord.","hintergrund":"Eingelegter Hering war im Mittelalter ein Konservierungsmittel für den langen Winter und wurde im 19. Jahrhundert zur Delikatesse der Oberschicht; erst im 20. Jahrhundert wurde er zum festen Bestandteil des Alltags. Bei Midsommar und am Julbord eröffnet der Hering traditionell das Buffet, oft mit mindestens drei verschiedenen Sorten, die jeweils separat gegessen werden. Serviert wird er mit neuen Kartoffeln, saurer Sahne, Schnittlauch, Knäckebrot und gern einem kleinen Schnaps. Die Rezepte unterscheiden sich von Familie zu Familie; hier findest du die drei Sorten, die jeder schwedische Tisch kennt.","portionen":8,"zeit":{"vorbereitung":50,"garen":10,"ruhen":2880},"schwierigkeit":1,"zutaten":[{"gruppe":"Hering","liste":[{"menge":8,"einheit":"Stück","name":"Salzheringsfilets (ca. 500 g)","hinweis":"aus dem Fass oder aus der Kühltheke; alternativ ungesalzene Heringsfilets frisch oder TK, dann 4–6 Stunden in leichter Salzlake marinieren"},{"menge":1,"einheit":"l","name":"kaltes Wasser","hinweis":"zum Wässern"}]},{"gruppe":"Inlagd sill (süß-sauer)","liste":[{"menge":200,"einheit":"ml","name":"Branntweinessig (5 %)","hinweis":"in Schweden nimmt man 12-prozentige Ättika, in Deutschland funktioniert klarer Essig"},{"menge":300,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":150,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Zwiebel, in dünne Ringe geschnitten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Karotte, in dünne Scheiben","hinweis":""},{"menge":10,"einheit":"Stück","name":"Pimentkörner","hinweis":""},{"menge":10,"einheit":"Stück","name":"weiße Pfefferkörner","hinweis":""},{"menge":3,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":1,"einheit":"Bund","name":"Dill","hinweis":""}]},{"gruppe":"Senapssill (Senfhering)","liste":[{"menge":3,"einheit":"EL","name":"süßer Senf","hinweis":"z. B. Händlmaier oder Löwensenf mittelscharf mit etwas Honig"},{"menge":1,"einheit":"EL","name":"Dijon-Senf","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Essig","hinweis":""},{"menge":100,"einheit":"ml","name":"neutrales Öl","hinweis":""},{"menge":2,"einheit":"EL","name":"gehackter Dill","hinweis":""}]},{"gruppe":"Currysill","liste":[{"menge":150,"einheit":"g","name":"Crème fraîche oder saure Sahne","hinweis":""},{"menge":2,"einheit":"EL","name":"Mayonnaise","hinweis":""},{"menge":1,"einheit":"EL","name":"Currypulver","hinweis":""},{"menge":1,"einheit":"Stück","name":"säuerlicher Apfel (z. B. Granny Smith)","hinweis":"fein gewürfelt"},{"menge":2,"einheit":"EL","name":"Schnittlauch, fein geschnitten","hinweis":""}]}],"ausruestung":["3 saubere Einmachgläser mit Deckel","kleiner Topf","Schneidebrett und scharfes Messer","Schüsseln zum Wässern und Mischen"],"schritte":[{"titel":"Salzhering wässern","aktion":"einlegen","text":"Gib die Salzheringsfilets in eine Schüssel, gieße 1 Liter kaltes Wasser darüber und stelle sie für 12 bis 24 Stunden in den Kühlschrank. Wechsele das Wasser nach 6 Stunden einmal aus. Das Wässern zieht überschüssiges Salz heraus; probiere nach 12 Stunden ein kleines Stück vom Rand: Schmeckt es noch deutlich salzig, wässerst du länger. Verwendest du frische Heringe, schneidest du die Filets und legst sie nur 4 Stunden in Salzwasser (50 g Salz pro Liter), um das Fleisch zu festigen.","dauer":5,"tipp":"Matjes ist bereits mild und braucht nur 1–2 Stunden Wässern; Salzhering im Fass dagegen deutlich länger."},{"titel":"Filets abtrocknen und schneiden","aktion":"schneiden","text":"Hebe die gewässerten Filets heraus und tupfe sie auf Küchenpapier trocken. Ziehe Reste der Haut ab, falls vorhanden, und prüfe mit den Fingern auf Gräten, die du mit einer Pinzette entfernst. Schneide die Filets in 2 bis 3 cm breite Stücke quer zur Faser. Teile sie dann in drei gleiche Portionen; jede kommt zu einer der drei Marinaden. Mit einem scharfen Messer arbeiten, denn Hering zerfasert leicht, wenn du ihn drückst.","dauer":15,"tipp":"Ein scharfes Messer ist hier wichtiger als Kraft."},{"titel":"Süß-saure Lake für Inlagd sill kochen","aktion":"kochen","text":"Gib Essig, Wasser, Zucker, Piment, Pfeffer und Lorbeer in einen kleinen Topf und erhitze alles, bis sich der Zucker vollständig aufgelöst hat; er muss nicht lange kochen. Nimm den Topf vom Herd und lasse die Lake vollständig abkühlen, am besten im Kühlschrank. Warme Lake gart den Fisch an und macht ihn weich, kalte Lake hält ihn fest und glasig. Die Gewürze duften dabei nach Piment und Lorbeer, der Essig soll mild, nicht stechend riechen.","dauer":15,"tipp":"Probiere die Lake: Sie soll deutlich süß-sauer schmecken, denn der Hering nimmt Geschmack auf."},{"titel":"Inlagd sill ansetzen","aktion":"einlegen","text":"Schichte Heringsstücke, Zwiebelringe, Karottenscheiben und einige Dillzweige abwechselnd in ein Einmachglas. Gieße die kalte Lake darüber, bis alles bedeckt ist, und drücke die Zutaten leicht herunter. Verschließe das Glas und lasse es mindestens 24 Stunden, besser 2 Tage im Kühlschrank ziehen. Nach dieser Zeit ist die Lake mild-säuerlich, der Fisch glänzt und die Zwiebel ist knackig-süß.","dauer":5,"tipp":"Hält sich im Kühlschrank bis zu einer Woche."},{"titel":"Senfsauce für Senapssill rühren","aktion":"mischen","text":"Verrühre süßen Senf, Dijon, Zucker und Essig in einer Schüssel zu einer glatten Paste. Gieße das Öl in dünnem Strahl ein und rühre dabei kräftig, bis eine sämige, glänzende Emulsion entsteht, wie bei einer Mayonnaise. Rühre Dill unter und schmecke ab: Sie soll süß, scharf und säuerlich zugleich sein. Gib die Heringsstücke zur Sauce, wende alles vorsichtig und fülle es in ein Glas.","dauer":8,"tipp":"Die Sauce schmeckt nach einem Tag noch runder."},{"titel":"Currysauce für Currysill rühren","aktion":"mischen","text":"Rühre Crème fraîche, Mayonnaise und Currypulver in einer Schüssel glatt. Der Curry darf kurz in einer trockenen Pfanne leicht angeröstet werden, dann duftet er intensiver; dann aber abkühlen lassen. Hebe die Apfelwürfel und den Schnittlauch unter. Der Apfel bringt Säure und Knackigkeit, die die Cremigkeit auflockern. Gib die Heringsstücke dazu, wende sie vorsichtig und fülle alles in ein sauberes Glas.","dauer":8,"tipp":"Currypulver mit einer Prise Zucker und Zitronensaft abrunden."},{"titel":"Alle Sorten durchziehen lassen","aktion":"ruhen","text":"Stelle alle drei Gläser abgedeckt in den Kühlschrank und lasse sie mindestens 24 Stunden, am besten 2 Tage ziehen. In dieser Zeit verbinden sich Sauce und Fisch, der Hering wird mürbe und die Aromen runden sich. Probiere vor dem Servieren und schmecke gegebenenfalls nach: ein Spritzer Essig oder Zitronensaft, wenn es zu mild ist, eine Prise Zucker, wenn es zu sauer ist.","dauer":1440,"tipp":"Vor dem Servieren 15 Minuten aus dem Kühlschrank nehmen; zu kalt schmeckt Hering flach."},{"titel":"Anrichten und servieren","aktion":"anrichten","text":"Hole die Gläser etwa 15 Minuten vor dem Essen aus dem Kühlschrank. Richte jede Sorte getrennt in einer kleinen Schale an, damit sich die Aromen nicht vermischen. Serviere dazu frisch gekochte neue Kartoffeln mit Dill, saure Sahne mit Schnittlauch, hart gekochte Eier, Knäckebrot und kräftiges Butterbrot. Traditionell wird dazu ein kleiner Schnaps (Aquavit) getrunken; der Anfang des Midsommar-Essens.","dauer":10,"tipp":"Reihenfolge am Buffet: erst Inlagd sill, dann Senapssill, zum Schluss Currysill, von mild zu kräftig."},{"titel":"Aufbewahren","aktion":"kuehlen","text":"Verschließe angebrochene Gläser luftdicht und bewahre sie im Kühlschrank auf. Der Inlagd sill hält sich bis zu einer Woche, die cremigen Sorten sollten innerhalb von 3 bis 4 Tagen gegessen werden, da die Sahneanteile schneller verderben. Verwende immer einen sauberen Löffel zum Entnehmen, damit nichts verunreinigt wird. Reste eignen sich hervorragend für ein Sillmacka, ein Roggenbrot mit Hering, Ei und Dill.","dauer":5,"tipp":"Nie bei Zimmertemperatur stehen lassen."}],"profitipps":["Salzhering lieber zu lange als zu kurz wässern; zu salzig lässt sich nicht retten.","Lake immer vollständig abkühlen, bevor sie auf den Fisch kommt.","Der Hering schmeckt nach 2 Tagen am besten, nicht am ersten Tag.","Für Senapssill ein bisschen Honig oder Zucker verwenden: Senf braucht Süße als Gegenspieler.","Mit Matjes gelingt es schneller, schmeckt aber weniger würzig als klassischer Salzhering."],"varianten":["Löksill: mit extra viel roter Zwiebel und ohne Karotte.","Brännvinssill: ein Teil des Essigs durch Aquavit ersetzt, oft mit Orangenschale.","Skärgårdssill mit Fischrogen, Dill und Schnittlauch.","Sillsalat mit Roter Bete, Kartoffeln und saurer Sahne."],"beilagen":["neue Kartoffeln mit Dill","saure Sahne mit Schnittlauch","hart gekochte Eier","Knäckebrot und Butter","Västerbottensost"],"getraenk":"Eisgekühlter Aquavit (Skåne- oder Linie-Aquavit) und helles Bier.","koeche":[],"quellen":[{"titel":"All or most of the ways you can eat herring in Sweden (The Local)","url":"https://www.thelocal.se/20251112/all-or-most-of-the-ways-you-can-eat-herring-in-sweden"},{"titel":"LCHF-sill på tre sätt (Diet Doctor)","url":"https://www.dietdoctor.com/se/recept/lchf-sill-pa-tre-satt"},{"titel":"Five odd Swedish things to taste at midsummer (The Local)","url":"https://www.thelocal.se/20150618/five-odd-swedish-things-to-taste-at-midsummer"}],"bild":"fisch","farben":["#e8d9b8","#7a5c3a","#c8a24a"],"schlagworte":["Midsommar","Julbord","Hering","eingelegt","Smörgåsbord"],"vegetarisch_moeglich":false},{"originalname":"Prinsesstårta","hauptkategorie":"suess","gang":"kuchen","koeche":[{"name":"Jenny Åkerström","bezug":"Lehrerin der Töchter von Prinz Carl; gilt als Schöpferin der Torte, deren Rezept sie in den 1930er-Jahren im Buch „Prinsessornas Kokbok“ veröffentlichte.","quelle":"https://en.wikipedia.org/wiki/Prinsesst%C3%A5rta"}],"vegetarisch_moeglich":true,"id":"skandinavien-prinsesstaarta","name":"Prinsesstårta (Schwedische Prinzessinnentorte)","region":"Schweden","kueche":"skandinavien","beliebtheit":79,"kurz":"Hoch gewölbte Schichttorte aus Biskuit, Vanillecreme, Himbeermarmelade und Sahne, in grüne Marzipandecke gehüllt und mit einer rosa Rose gekrönt.","hintergrund":"Die Prinsesstårta wurde von Jenny Åkerström erfunden, der Lehrerin der drei Töchter von Prinz Carl, Herzog von Västergötland. Sie veröffentlichte das Rezept in den 1930er-Jahren im Buch „Prinsessornas Kokbok“ zunächst als „Grön tårta“ (grüne Torte), später wurde sie nach den Prinzessinnen Margaretha, Märtha und Astrid benannt, die sie angeblich besonders liebten. In Schweden gehört sie zu Geburtstagen, Taufen und Familienfeiern und ist in nahezu jeder Konditorei zu finden. Gelbe Marzipandecken heißen „Prinstårta“, rosa nennt man sie „Operatårta“.","portionen":12,"zeit":{"vorbereitung":90,"garen":35,"ruhen":360},"schwierigkeit":3,"zutaten":[{"gruppe":"Für den Biskuit (Springform 24 cm)","liste":[{"menge":4,"einheit":"Stück","name":"Eier (Größe M)","hinweis":"Zimmertemperatur"},{"menge":125,"einheit":"g","name":"Zucker","hinweis":""},{"menge":60,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":60,"einheit":"g","name":"Kartoffelstärke","hinweis":"alternativ Speisestärke"},{"menge":1,"einheit":"TL","name":"Backpulver","hinweis":"gestrichen"},{"menge":1,"einheit":"EL","name":"Butter","hinweis":"für die Form"}]},{"gruppe":"Für die Vanillecreme","liste":[{"menge":500,"einheit":"ml","name":"Milch","hinweis":"Vollmilch"},{"menge":1,"einheit":"Stück","name":"Vanilleschote","hinweis":"oder 2 TL Vanilleextrakt"},{"menge":5,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":100,"einheit":"g","name":"Zucker","hinweis":""},{"menge":45,"einheit":"g","name":"Speisestärke","hinweis":""},{"menge":30,"einheit":"g","name":"Butter","hinweis":"kalt, in Würfeln"}]},{"gruppe":"Für Füllung und Decke","liste":[{"menge":200,"einheit":"g","name":"Himbeermarmelade","hinweis":"mit Fruchtstückchen, ggf. glatt gerührt"},{"menge":600,"einheit":"g","name":"Schlagsahne","hinweis":"mind. 35 % Fett, gut gekühlt"},{"menge":2,"einheit":"EL","name":"Puderzucker","hinweis":"für die Sahne"},{"menge":500,"einheit":"g","name":"Marzipanrohmasse","hinweis":"gut ausgeknetet, nicht zu trocken"},{"menge":100,"einheit":"g","name":"Puderzucker","hinweis":"zum Ausrollen und Kneten"},{"menge":null,"einheit":"","name":"grüne Lebensmittelfarbe (Gel)","hinweis":"nach Bedarf, ca. 1/2 TL"},{"menge":30,"einheit":"g","name":"Marzipanrohmasse","hinweis":"für die rosa Rose, mit rosa Gel eingefärbt"},{"menge":2,"einheit":"EL","name":"Puderzucker","hinweis":"zum Bestäuben"}]}],"ausruestung":["Springform 24 cm","Backpapier","Handrührgerät","Schneebesen","Topf","Tortenplatte oder Backblech","Teigrolle","Brotmesser","Teigschaber","Gummischaber"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle die Sahne kalt. Heize den Ofen auf 175 °C Ober-/Unterhitze (155 °C Umluft) vor und fette den Boden der Springform leicht ein, ohne den Rand zu fetten – der Biskuit klebt sonst nicht und kann besser aufsteigen. Lege das Backpapier ein. Siebe Mehl, Stärke und Backpulver zusammen auf einen Teller. Lege außerdem Marzipanrohmasse und Puderzucker bereit und knete das Marzipan gleich weich, damit es später nicht reißt.","dauer":20,"tipp":""},{"titel":"Biskuit backen","aktion":"backen","text":"Schlage Eier mit Zucker in einer Schüssel mit dem Handrührgerät sechs bis acht Minuten auf hoher Stufe, bis die Masse hell, dick und cremig ist und beim Anheben des Quirls eine Spur auf der Oberfläche stehen bleibt. Siebe die Mehlmischung in zwei Portionen darüber und hebe sie mit dem Teigschaber vorsichtig unter, ohne die Luft herauszudrücken. Fülle den Teig in die Form und backe ihn 30 bis 35 Minuten, bis er goldbraun ist, bei Fingerdruck zurückfedert und ein Stäbchen sauber herauskommt. Nicht vorher die Ofentür öffnen.","dauer":35,"tipp":"Der Biskuit gelingt nur, wenn die Eiermasse wirklich dick und hell ist – lieber eine Minute länger schlagen."},{"titel":"Biskuit auskühlen und teilen","aktion":"kuehlen","text":"Lass den Biskuit zehn Minuten in der Form ruhen, löse den Rand und stürze ihn auf ein Kuchengitter. Ziehe das Backpapier ab und lasse ihn völlig auskühlen, am besten über Nacht abgedeckt, denn ein vollständig kalter Biskuit lässt sich sauber schneiden und bleibt stabil. Teile ihn danach mit einem langen Sägemesser waagerecht in drei gleich dicke Böden; lege dazu Lineale als Führung an. Stelle zwei Böden beiseite und lege den dritten auf die Tortenplatte.","dauer":120,"tipp":""},{"titel":"Vanillecreme kochen","aktion":"kochen","text":"Erhitze 400 ml Milch mit dem ausgekratzten Vanillemark und der Schote auf mittlerer Stufe, bis sie dampft. Verrühre die restlichen 100 ml Milch mit Eigelben, Zucker und Speisestärke glatt. Gieße die heiße Milch langsam unter Rühren in die Eiermischung, gib alles zurück in den Topf und koche unter ständigem Rühren mit dem Schneebesen auf, bis die Creme dick wird und große Blasen platzen – das dauert etwa eine Minute. Nimm den Topf vom Herd, entferne die Schote und rühre die kalte Butter unter. Decke die Creme direkt mit Folie ab und lass sie vollständig auskühlen.","dauer":25,"tipp":"Folie direkt auf die Oberfläche legen, sonst bildet sich eine Haut."},{"titel":"Sahne aufschlagen und Torte schichten","aktion":"schichten","text":"Schlage die kalte Sahne mit dem Puderzucker auf mittlerer Stufe steif, aber nicht körnig. Streiche Marmelade dünn auf den untersten Boden, verteile die Hälfte der Vanillecreme darauf, lege den zweiten Boden auf und wiederhole mit Marmelade und Creme. Setze den obersten Boden auf und drücke ihn leicht an. Türme die Sahne nun in einem hohen Berg auf die Torte und verstreiche sie zu einer gleichmäßigen Kuppel, die bis zum Rand der Torte reicht und rundum etwa vier Zentimeter über die Böden ragt.","dauer":25,"tipp":""},{"titel":"Kuppel kühlen","aktion":"kuehlen","text":"Stelle die Torte mit der Sahnekuppel für mindestens zwei Stunden in den Kühlschrank, damit die Füllung fest wird. In dieser Zeit setzt sich die Creme, und die Kuppel behält ihre Form beim Eindecken mit dem Marzipan. Knete in der Zwischenzeit die Marzipanrohmasse mit etwas Puderzucker und einer kleinen Menge grünem Gel, bis ein gleichmäßig hellgrüner, geschmeidiger Teig entsteht.","dauer":120,"tipp":""},{"titel":"Marzipandecke ausrollen","aktion":"ausrollen","text":"Bestäube die Arbeitsfläche dünn mit Puderzucker und rolle das grüne Marzipan in einem Kreis von etwa 40 cm Durchmesser und 3 mm Stärke aus. Hebe es mit der Teigrolle an und lege es sanft über die Torte, ohne zu ziehen. Streiche das Marzipan von oben nach unten glatt und drücke es am Rand an, sodass keine Falten entstehen. Schneide überschüssiges Marzipan unten mit einem Messer ab. Wenn es reißt, drücke die Risse mit dem Daumen glatt oder flicke sie mit Marzipanresten.","dauer":15,"tipp":"Das Marzipan wird weicher, wenn du es kurz in den Händen knetest – kalt reißt es leicht."},{"titel":"Rose formen und Torte dekorieren","aktion":"garnieren","text":"Knete die restlichen 30 g Marzipan mit rosa Gel, forme daraus eine kleine Rose, indem du ein paar flache Blättchen formst und sie spiralförmig um einen Kegel legst. Setze die Rose mittig auf die Torte. Bestäube die Kuppel mit Puderzucker durch ein feines Sieb, sodass ein samtiger Schleier entsteht. Stelle die Torte bis zum Servieren kühl.","dauer":15,"tipp":""},{"titel":"Anschneiden und servieren","aktion":"anrichten","text":"Nimm die Torte etwa zehn Minuten vor dem Servieren aus dem Kühlschrank. Tauche ein langes, scharfes Messer in heißes Wasser, trockne es ab und schneide die Torte mit einem entschiedenen Zug in Stücke; das Marzipan lässt sich so sauber durchtrennen. Die Schnittfläche zeigt dann die Schichten aus Biskuit, Marmelade und Creme unter der hohen Sahnekuppel. Serviere sie am besten am Tag der Fertigstellung oder am folgenden Tag.","dauer":0,"tipp":""}],"profitipps":["Marzipan muss geschmeidig sein, sonst bricht es beim Eindecken.","Biskuit gut auskühlen lassen und am besten über Nacht ruhen lassen.","Sahne mindestens 35 % Fett für stabile Kuppel.","Marzipandecke auf der kalten Torte ausbreiten, damit sie nicht schwitzt.","Die Torte ist schwer und hoch: Wähle eine stabile Platte und transportiere sie gekühlt und waagerecht."],"varianten":["Mit Erdbeermarmelade statt Himbeere.","Gelbe „Prinstårta“ mit gelbem Marzipan.","Rosa „Operatårta“ mit rosa Marzipan.","Als Prinsesstårta in Rechteckform („Prinsessbakelse“ als Einzelstücke)."],"beilagen":["Kaffee","Frische Beeren"],"getraenk":"Kaffee (Fika-Tradition), Tee oder Sekt","quellen":[{"titel":"Prinsesstårta – Wikipedia","url":"https://en.wikipedia.org/wiki/Prinsesst%C3%A5rta"}],"bild":"torte","farben":["#9ccf8e","#f3b6c6","#fff4d6"],"schlagworte":["Geburtstag","Fika","Marzipan"]},{"id":"skandinavien-smoerrebroed","name":"Smørrebrød – drei dänische Klassiker","originalname":"Smørrebrød","kueche":"skandinavien","region":"Dänemark","beliebtheit":79,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"snack","kurz":"Dunkles Roggenbrot, dick mit Butter bestrichen und kunstvoll belegt: Leberpastete mit Speck und Pilzen, Ei mit Krabben und Kartoffel mit Radieschen.","hintergrund":"Smørrebrød heißt wörtlich Butter und Brot und ist das dänische Nationalgericht zum Mittag. Das Fundament ist meist Rugbrød, ein dichtes, dunkles Roggensauerteigbrot, das mit Butter oder Schmalz bestrichen wird. Beliebte Beläge sind Leverpostej mit Speck und Pilzen, Stjerneskud mit Fisch und Krabben, Dyrlægens natmad mit Leberpastete, Salzfleisch und Aspik oder Matjes. Man isst Smørrebrød üblicherweise mit Messer und Gabel. Bei festlichen Essen kommen erst Fischbrote, dann Fleisch, danach Käse. Die Beläge folgen den Jahreszeiten, im Sommer gibt es leichtere Varianten wie geräucherte Makrele mit neuen Kartoffeln.","portionen":4,"zeit":{"vorbereitung":30,"garen":20,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Brot und Butter","liste":[{"menge":12,"einheit":"Scheibe","name":"dunkles Roggenvollkornbrot (Rugbrød)","hinweis":"ca. 1 cm dick; Ersatz: Schwarzbrot ohne Körner"},{"menge":80,"einheit":"g","name":"weiche Butter","hinweis":""}]},{"gruppe":"Leverpostej mit Speck und Pilzen","liste":[{"menge":200,"einheit":"g","name":"feine Leberpastete oder Leberwurst","hinweis":"vom Metzger; am besten streichfähig und fein"},{"menge":4,"einheit":"Scheibe","name":"Frühstücksspeck","hinweis":""},{"menge":100,"einheit":"g","name":"Champignons","hinweis":"in Scheiben geschnitten"},{"menge":4,"einheit":"Scheibe","name":"Essiggurke","hinweis":"zum Garnieren"}]},{"gruppe":"Ei mit Krabben","liste":[{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"hart gekocht"},{"menge":200,"einheit":"g","name":"gekochte Nordseekrabben oder Garnelen","hinweis":"geschält"},{"menge":4,"einheit":"EL","name":"Mayonnaise","hinweis":""},{"menge":1,"einheit":"Bund","name":"Dill","hinweis":""},{"menge":4,"einheit":"Scheibe","name":"Zitrone","hinweis":""}]},{"gruppe":"Kartoffel mit Radieschen","liste":[{"menge":4,"einheit":"Stück","name":"mittelgroße, festkochende Kartoffeln","hinweis":"gekocht und abgekühlt"},{"menge":4,"einheit":"Stück","name":"Radieschen","hinweis":"in feine Scheiben geschnitten"},{"menge":3,"einheit":"EL","name":"Mayonnaise","hinweis":""},{"menge":2,"einheit":"EL","name":"Crème fraîche","hinweis":""},{"menge":1,"einheit":"EL","name":"Schnittlauch","hinweis":"in Röllchen"},{"menge":2,"einheit":"EL","name":"Röstzwiebeln","hinweis":""}]}],"ausruestung":["scharfes Brotmesser","kleine Pfanne","Topf","Messer zum Streichen"],"schritte":[{"titel":"Zutaten bereitstellen","aktion":"vorbereiten","text":"Nimm die Butter 30 Minuten vor der Zubereitung aus dem Kühlschrank, damit sie streichweich ist. Wasche und schneide Radieschen, Dill und Schnittlauch, schneide die Champignons in Scheiben und lege alle Belege auf einzelne Teller oder Brettchen. Das Auge isst mit, deshalb hilft eine geordnete Arbeitsfläche, mit der du jedes Brot gleichmäßig und ansprechend belegen kannst. Stelle die Teller zum Servieren bereit.","dauer":0,"tipp":""},{"titel":"Eier und Kartoffeln kochen","aktion":"kochen","text":"Koche die Eier in sprudelndem Wasser 9 Minuten, damit das Eigelb fest, aber cremig ist, und schrecke sie sofort in Eiswasser ab, damit sie sich leicht schälen lassen. Koche die Kartoffeln in Salzwasser 20 bis 25 Minuten bis sie gar sind, gieße sie ab und lasse sie vollständig auskühlen. Schäle sie erst, wenn sie kalt sind, und schneide sie später in dünne Scheiben. Kalte Kartoffeln sind fester und lassen sich sauberer schneiden.","dauer":25,"tipp":""},{"titel":"Speck und Pilze braten","aktion":"braten","text":"Brate den Speck in einer Pfanne ohne zusätzliches Fett bei mittlerer Hitze 4 bis 5 Minuten, bis er goldbraun und knusprig ist. Hebe ihn auf Küchenpapier. Brate die Champignons im Speckfett 4 bis 5 Minuten bei hoher Hitze, bis sie gebräunt sind und kein Wasser mehr austritt; salze erst am Ende. Beides soll warm auf das Brot kommen, damit die Leberpastete leicht schmilzt.","dauer":10,"tipp":""},{"titel":"Brot buttern","aktion":"mischen","text":"Bestreiche jede Brotscheibe mit weicher Butter bis zu den Rändern, auch in die Ecken. Die Butter sorgt dafür, dass das Brot nicht durchweicht, und gibt dem Belag Halt und Geschmack. Verwende reichlich, Smørrebrød heißt nicht umsonst Butter und Brot. Lege die Scheiben nebeneinander auf ein Brett. Die Butter sollte weich sein, nicht flüssig, damit sie sich ohne Risse verstreichen lässt.","dauer":5,"tipp":""},{"titel":"Leverpostej-Brote belegen","aktion":"schichten","text":"Verstreiche die Leberpastete dick und gleichmäßig auf vier Brotscheiben. Lege die noch warmen Speckscheiben schräg darauf und verteile die Champignons darüber. Dekoriere jedes Brot mit einer Gurkenscheibe. Die Wärme von Speck und Pilzen lässt die Pastete leicht anschmelzen, und es entsteht ein köstlicher Kontrast zwischen cremig, knusprig und würzig.","dauer":5,"tipp":""},{"titel":"Ei-und-Krabben-Brote belegen","aktion":"schichten","text":"Schäle die Eier und schneide sie in Scheiben. Belege vier gebutterte Brote mit den Eierscheiben, setze je einen Klecks Mayonnaise darauf und häufe die Krabben darüber. Garniere mit Dill und einer Zitronenscheibe. Die Krabben sollen frisch und süß schmecken. Zitrone und Dill geben Frische, die gegen die Cremigkeit von Ei und Mayonnaise wirkt.","dauer":5,"tipp":""},{"titel":"Kartoffel-Radieschen-Brote belegen","aktion":"schichten","text":"Schäle die abgekühlten Kartoffeln und schneide sie in dünne Scheiben. Lege sie überlappend auf die vier restlichen Brote. Verrühre Mayonnaise und Crème fraîche, gib einen Klecks auf jede Kartoffelschicht und belege mit Radieschenscheiben. Bestreue mit Schnittlauch und Röstzwiebeln. Die knackigen Radieschen und die knusprigen Zwiebeln geben dem sonst weichen Brot Biss.","dauer":5,"tipp":""},{"titel":"Anrichten und Tischsitten","aktion":"anrichten","text":"Serviere jedes Smørrebrød auf einem Brettchen oder Teller, gefolgt von einem kalten Bier oder Aquavit. Esse es mit Messer und Gabel, denn die Beläge sind üppig. Bei einem festlichen Mittagessen werden die Beläge in Gängen serviert: zuerst Fisch, dann Fleisch und Salate, danach Käse. Arrangiere sie so, dass Farben und Texturen sich abwechseln.","dauer":0,"tipp":""}],"profitipps":["Das Brot immer bis zum Rand buttern; das schützt vor Durchweichen.","Roggenbrot dünn schneiden, nicht über 1 cm, damit der Belag zur Geltung kommt.","Warm und kalt kombinieren: warmer Speck und Pilze auf kalter Pastete schmecken besonders gut.","Mit Dill, Kresse, Schnittlauch und Zitrone garnieren; das Auge isst mit.","Smørrebrød am besten frisch belegen, nicht mehr als 30 Minuten vor dem Servieren."],"varianten":["Stjerneskud: Fisch, Krabben, Kaviar und Zitrone auf Weißbrot","Dyrlægens natmad: Leberpastete, Salzfleisch und Aspik","Mit Matjes, roten Zwiebeln und Kresse","Mit geräucherter Makrele im Sommer"],"beilagen":["Aquavit","kaltes Bier","Gurkensalat","Remoulade"],"getraenk":"Eiskaltes dänisches Lager oder ein Schnaps (Aquavit) zum Anstoßen.","koeche":[],"quellen":[{"titel":"Smørrebrød – Wikipedia","url":"https://en.wikipedia.org/wiki/Sm%C3%B8rrebr%C3%B8d"}],"bild":"sandwich","farben":["#4a2e1a","#d9b27a","#b5262d"],"schlagworte":["Dänemark","Mittagessen","Roggenbrot","Fingerfood"],"vegetarisch_moeglich":true},{"id":"skandinavien-julskinka-weihnachtsschinken","name":"Julskinka – schwedischer Weihnachtsschinken mit Senfkruste","originalname":"Julskinka","kueche":"skandinavien","region":"Schweden","beliebtheit":76,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","themen":["fest"],"kurz":"Zart gegarter Schinken mit knuspriger Kruste aus Senf, Ei, Zucker und Paniermehl: der Mittelpunkt des schwedischen Julbord.","hintergrund":"Beim Julbord, dem schwedischen Weihnachtsbuffet, steht der Julskinka stets in der Mitte: ein großer, im Sud gegarter Schinken, der mit einer Kruste aus Senf, Ei und Paniermehl überbacken wird. Das „Julbord“ ist keine einzelne Mahlzeit, sondern ein ritualisierter Ablauf in mehreren Gängen, beginnend mit kaltem Fisch (Hering, Gravlax), dann kalte Fleischgerichte (Schinken, Leberpastete), danach warme Gerichte (Köttbullar, Prinskorv, Jansson-Kartoffelgratin) und schließlich Süßes wie Reisbrei mit Zimt. Der Julskinka wird am 24. Dezember gegessen, oft auch an den Weihnachtsfeiertagen und noch in den Tagen danach als Aufschnitt. Dazu gehören Senf, Rotkohl, Grünkohl (Grönkål) und das hausgebraute Julmust oder Glögg.","portionen":10,"zeit":{"vorbereitung":30,"garen":190,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Schinken","liste":[{"menge":2.5,"einheit":"kg","name":"milder Schinken am Stück, gepökelt und ungeräuchert (Schweinenuss oder Hinterschinken)","hinweis":"vom Metzger bestellen; ersatzweise leicht gepökelte Schweinekeule oder Kassler"},{"menge":3,"einheit":"l","name":"Wasser","hinweis":"so viel, dass der Schinken ganz bedeckt ist"},{"menge":1,"einheit":"Stück","name":"Zwiebel, halbiert","hinweis":""},{"menge":2,"einheit":"Stück","name":"Karotten, grob geschnitten","hinweis":""},{"menge":3,"einheit":"Blatt","name":"Lorbeerblätter","hinweis":""},{"menge":1,"einheit":"EL","name":"schwarze Pfefferkörner","hinweis":""},{"menge":6,"einheit":"Stück","name":"Pimentkörner","hinweis":""},{"menge":4,"einheit":"Stück","name":"Nelken","hinweis":""}]},{"gruppe":"Für die Kruste (Griljering)","liste":[{"menge":1,"einheit":"Stück","name":"Ei, Größe M","hinweis":""},{"menge":3,"einheit":"EL","name":"mittelscharfer Senf","hinweis":"Dijon oder süßer schwedischer Senf"},{"menge":2,"einheit":"EL","name":"brauner Zucker","hinweis":""},{"menge":5,"einheit":"EL","name":"Semmelbrösel","hinweis":"oder Panko"}]},{"gruppe":"Für die Senfsauce (Julsenap)","liste":[{"menge":100,"einheit":"g","name":"mittelscharfer Senf","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":3,"einheit":"EL","name":"Rapsöl","hinweis":""},{"menge":1,"einheit":"EL","name":"Weißweinessig","hinweis":""},{"menge":1,"einheit":"Bund","name":"Dill, gehackt","hinweis":""}]}],"ausruestung":["Sehr großer Topf","Bratenthermometer","Backblech oder Auflaufform","Backpinsel","Scharfes langes Messer"],"schritte":[{"titel":"Mise en place und Schinken vorbereiten","aktion":"vorbereiten","text":"Nimm den Schinken zwei Stunden vor dem Garen aus dem Kühlschrank. Prüfe, ob er sehr salzig ist: Bei stark gepökeltem Fleisch lohnt es sich, ihn über Nacht in kaltem Wasser zu wässern und das Wasser einmal zu wechseln. Spüle ihn ab, entferne bei Bedarf die Schwarte so, dass etwa 5 mm Fett auf dem Fleisch bleiben; sie dient später als Träger für die Kruste. Schneide Gemüse für den Sud, bereite die Gewürze vor und prüfe, ob dein Topf groß genug ist, damit der Schinken ganz mit Wasser bedeckt ist.","dauer":0,"tipp":""},{"titel":"Sud ansetzen","aktion":"kochen","text":"Gib Zwiebel, Karotten, Lorbeer, Pfeffer, Piment und Nelken in den Topf, lege den Schinken hinein und gieße kaltes Wasser auf, bis er knapp bedeckt ist. Erhitze langsam auf etwa 85 bis 90 °C, bis kleine Bläschen vom Topfboden aufsteigen, aber das Wasser nicht sprudelt. Schäume bei Bedarf Schaum ab. Das Aroma der Gewürze steigt allmählich auf und füllt die Küche mit einem warmen, würzigen Duft. Ein Küchenthermometer im Wasser hilft, die Temperatur konstant zu halten.","dauer":20,"tipp":""},{"titel":"Sanft garziehen","aktion":"koecheln","text":"Halte die Temperatur bei 80 bis 85 °C und lasse den Schinken ziehen, etwa 50 bis 60 Minuten pro Kilogramm, bei 2,5 kg also 2 bis 2,5 Stunden. Er sollte nie richtig kochen, denn sprudelndes Wasser macht das Fleisch trocken und faserig. Stecke das Bratenthermometer in die dickste Stelle: Bei 68 bis 70 °C Kerntemperatur ist der Schinken gar, das Fleisch ist rosa, saftig und lässt sich mit der Gabel zart teilen. Hebe ihn danach aus dem Sud.","dauer":150,"tipp":"Hebe etwas Sud auf – er ergibt hervorragende Suppen oder Erbsensuppe."},{"titel":"Abkühlen und Schwarte entfernen","aktion":"ruhen","text":"Lasse den Schinken auf einem Brett etwa 20 bis 30 Minuten abdampfen, bis er handwarm ist. Ziehe dann mit einem scharfen Messer vorsichtig die Schwarte ab, die sich in einem Stück lösen lässt, und schneide das Fett so zurecht, dass etwa 3 mm bleiben. Schneide mit der Messerspitze das Fett rautenförmig im Abstand von 2 cm ein, ohne ins Fleisch zu schneiden: So haftet die Kruste besser und sieht später dekorativ aus. Heize den Ofen auf 225 °C Ober-/Unterhitze (205 °C Umluft) vor.","dauer":30,"tipp":""},{"titel":"Kruste vorbereiten","aktion":"mischen","text":"Verrühre Ei, Senf und Zucker in einer Schüssel zu einer glatten, hellgelben Paste. Der Senf gibt Würze und Säure, der Zucker sorgt für die Karamellisierung. Mische die Semmelbrösel in einer zweiten Schüssel und lege beide bereit. Wenn der Schinken noch warm ist, trocknet die Oberfläche etwas ab, was die Haftung der Paste verbessert. Arbeite zügig, denn die Kruste soll noch auf heißem Fleisch gebacken werden.","dauer":5,"tipp":""},{"titel":"Bestreichen und panieren","aktion":"panieren","text":"Lege den Schinken auf ein Backblech oder in eine Form und bestreiche ihn rundum dick mit der Senf-Ei-Paste, bis auch alle Rillen gefüllt sind. Streue die Semmelbrösel gleichmäßig darüber, drücke sie leicht an und lasse überschüssige Brösel auf das Blech fallen. Du erhältst eine hellgelbe, körnige Hülle. Je gleichmäßiger die Schicht, desto schöner wird die Kruste; kahle Stellen bräunen später ungleichmäßig.","dauer":10,"tipp":""},{"titel":"Kruste überbacken","aktion":"ueberbacken","text":"Schiebe den Schinken in den heißen Ofen und backe ihn 10 bis 15 Minuten, bis die Oberfläche goldbraun und knusprig ist und leicht nach Senf und Karamell duftet. Beobachte ihn durch die Ofentür, denn Zucker und Senf verbrennen schnell; bei zu dunkler Farbe deckst du ihn locker mit Alufolie ab. Nimm ihn heraus, wenn die Kruste einen gleichmäßigen Farbton hat, und lasse ihn 15 bis 20 Minuten ruhen, bevor du ihn anschneidest.","dauer":15,"tipp":""},{"titel":"Senfsauce rühren","aktion":"aufschlagen","text":"Verrühre Senf, Zucker und Essig in einer Schüssel, bis sich der Zucker aufgelöst hat. Gieße unter ständigem Rühren mit dem Schneebesen das Öl in dünnem Strahl ein, sodass die Sauce cremig bindet wie eine Mayonnaise. Rühre den gehackten Dill ein und schmecke mit Salz und etwas Pfeffer ab. Die süß-scharfe Sauce passt hervorragend zum milden Schinken, zum Hering und zu Gravlax und gehört zum Julbord unbedingt dazu. Stelle sie kalt, damit sich die Aromen verbinden.","dauer":10,"tipp":""},{"titel":"Aufschneiden und servieren","aktion":"anrichten","text":"Schneide den Schinken mit einem langen, sehr scharfen Messer quer zur Faser in dünne Scheiben von etwa 3 mm und achte darauf, dass jede Scheibe ein Stück Kruste behält. Lege ihn auf eine Platte und garniere mit Petersilie. Auf dem Julbord stehen daneben Senfsauce, Rotkohl, Janssons frestelse, Köttbullar, eingelegte rote Bete und Brot. Der Schinken schmeckt warm und kalt, und die Reste gibt es in den Tagen danach auf Butterbrot mit Senf.","dauer":0,"tipp":"Der Schinken lässt sich schon am Vortag garen, panieren und kalt aufbewahren; vor dem Überbacken kurz auf Zimmertemperatur kommen lassen."}],"profitipps":["Nie sprudelnd kochen – 80 bis 85 °C im Sud halten, dann bleibt das Fleisch saftig.","Kerntemperatur messen: 68–70 °C reichen für einen rosa, zarten Schinken.","Fett rautenförmig einschneiden, damit die Kruste besser haftet.","Kruste im sehr heißen Ofen nur kurz überbacken, sonst trocknet der Schinken aus.","Sud aufheben: Er ist eine Basis für Erbsen- oder Linsensuppe."],"varianten":["Mit Honig- oder Sirupglasur statt Senfkruste (dänische Version)","Mit Dörrpflaumen und Äpfeln gefüllt","Auf dem Grill oder im Bräter geräuchert","Kalt aufgeschnitten als Teil des Smörgåsbords"],"beilagen":["Janssons frestelse","Rotkohl","Grönkål (Grünkohl)","Köttbullar","Senfsauce","Rote-Bete-Salat"],"getraenk":"Julmust (schwedische Weihnachtsbrause), Glögg oder ein kühles Pils; Aquavit zum Hering","koeche":[],"quellen":[{"titel":"Scandi Kitchen – Swedish Christmas ham topping (Julskinka griljering)","url":"https://www.scandikitchen.co.uk/recipe-swedish-christmas-ham-topping/"},{"titel":"Nordstjernan – Homage to the Swedish Christmas ham","url":"https://nordstjernan.com/news/food/7724"},{"titel":"Saveur – A Swedish Winter Smorgasbord","url":"https://www.saveur.com/article/Menu/A-Swedish-Winter-Smorgasbord"}],"bild":"braten-scheiben","farben":["#b8662f","#e7a9a0","#e8c46a"],"schlagworte":["Julbord","Weihnachten","Schweden","Schinken","Senf"],"vegetarisch_moeglich":false},{"originalname":"Kladdkaka","region":"Schweden","hauptkategorie":"suess","fleischsorte":"","gang":"kuchen","koeche":[{"name":"Magnus Nilsson","bezug":"Der schwedische Koch (Fäviken) hat in seinem „Nordic Baking Book“ ein Kladdkaka-Rezept, auf das Food52 in einem Beitrag verweist.","quelle":"https://vercel.food52.com/story/23429-easy-fast-chocolate-cake-recipe-kladdkaka-magnus-nilsson"}],"vegetarisch_moeglich":true,"id":"skandinavien-kladdkaka","name":"Kladdkaka (schwedischer klebriger Schokoladenkuchen)","kueche":"skandinavien","beliebtheit":74,"kurz":"Der klebrige Schokoladenkuchen mit knuspriger Kruste und fast flüssigem Kern, der in Schweden zu jedem Fika passt.","hintergrund":"Kladdkaka bedeutet wörtlich „klebriger Kuchen“ und ist in Schweden ein beliebtes Alltagsgebäck, das in wenigen Minuten angerührt ist. Er wird bewusst nicht ganz durchgebacken: außen entsteht eine dünne, knusprige Kruste, innen bleibt er feucht und fast brownieartig. Traditionell gehört er zur schwedischen Kaffeepause (Fika) und wird mit Schlagsahne oder Vanilleeis und frischen Beeren serviert. Die Zutatenliste ist kurz, Mehl, Zucker, Butter, Eier und Kakao reichen, doch das Backen erfordert Feingefühl.","portionen":8,"zeit":{"vorbereitung":15,"garen":18,"ruhen":120},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Kuchen","liste":[{"menge":100,"einheit":"g","name":"Butter","hinweis":"plus etwas zum Einfetten"},{"menge":200,"einheit":"g","name":"Zucker","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eier","hinweis":"Größe M"},{"menge":75,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":25,"einheit":"g","name":"Kakaopulver","hinweis":"ungesüßt, stark entölt"},{"menge":1,"einheit":"TL","name":"Vanillezucker","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Semmelbrösel oder Kakao","hinweis":"zum Ausstreuen der Form"}]},{"gruppe":"Zum Servieren","liste":[{"menge":200,"einheit":"ml","name":"Schlagsahne","hinweis":""},{"menge":150,"einheit":"g","name":"Beeren","hinweis":"Himbeeren oder Erdbeeren"},{"menge":1,"einheit":"EL","name":"Puderzucker","hinweis":""}]}],"ausruestung":["Springform 20 cm","Kleiner Topf","Schneebesen","Backpapier"],"schritte":[{"titel":"Form vorbereiten und Ofen heizen","aktion":"vorbereiten","text":"Heize den Ofen auf 175 °C Ober-/Unterhitze (155 °C Umluft) vor. Fette die Springform gründlich mit Butter ein und streue Semmelbrösel oder etwas Kakao hinein, sodass Boden und Rand dünn bedeckt sind. Klopfe überschüssiges Pulver aus. Die Brösel verhindern, dass der klebrige Teig an der Form haftet, und sorgen für eine zarte Kruste.","dauer":5,"tipp":""},{"titel":"Butter schmelzen","aktion":"koecheln","text":"Schmilz die Butter in einem kleinen Topf bei niedriger Hitze und lasse sie leicht abkühlen, bis sie nur noch lauwarm ist. Die Butter soll flüssig sein, aber nicht so heiß, dass sie die Eier später stocken lässt. Sie duftet nach frischer Butter; bräunt sie, wäre das ein nussiger Geschmack, den manche mögen, der aber vom Schokoladenaroma ablenken kann.","dauer":4,"tipp":""},{"titel":"Eier und Zucker verrühren","aktion":"mischen","text":"Gib Zucker, Vanillezucker, Salz und Eier in eine große Schüssel und rühre sie nur kurz mit dem Schneebesen, bis alles gerade vermischt ist – nicht schaumig schlagen, denn zu viel Luft macht den Kuchen luftig statt klebrig. Die Masse soll glatt und zähflüssig sein. Gieße die lauwarme Butter in einem dünnen Strahl dazu und rühre weiter, bis sie vollständig eingearbeitet ist.","dauer":4,"tipp":""},{"titel":"Mehl und Kakao unterheben","aktion":"mischen","text":"Siebe Mehl und Kakao über die Eiermasse und hebe sie mit einem Teigschaber nur so lange unter, bis kein weißes Mehl mehr zu sehen ist. Zu langes Rühren entwickelt Kleber und macht den Kuchen zäh statt weich. Der Teig sollte dunkel, glänzend und dickflüssig sein, vergleichbar mit Brownie-Teig. Wird er sehr fest und trocken, war meist zu viel Mehl im Spiel, deshalb Mehl lieber abwiegen als nach Gefühl zu schütten.","dauer":4,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Streiche den Teig in die vorbereitete Form und backe ihn im Ofen 15 bis 18 Minuten. Der Rand soll fest und knusprig sein und leicht nach Schokolade und Karamell duften, die Mitte aber noch wackeln, wenn du die Form vorsichtig bewegst. Mache die Stäbchenprobe mit einem Holzstäbchen: Es sollte feucht, mit Krümeln, herauskommen, nicht sauber. Backst du länger, wird der Kuchen trocken und verliert seinen Charakter.","dauer":18,"tipp":"Lieber 2 Minuten zu früh herausnehmen – der Kuchen gart im heißen Blech nach."},{"titel":"Abkühlen und servieren","aktion":"kuehlen","text":"Lasse den Kuchen mindestens 20 Minuten in der Form ruhen, bevor du ihn löst; in dieser Zeit setzt sich die Mitte etwas und wird schnittfest. Schwedisch üblich ist es, ihn lauwarm mit Sahne zu essen; wenn du ihn kühlst, wird er fester und fast trüffelartig. Dekoriere mit Puderzucker, geschlagener Sahne und Beeren und schneide ihn mit einem heißen, trockenen Messer in Stücke.","dauer":120,"tipp":""}],"profitipps":["Nicht zu lange backen – die Mitte muss klebrig bleiben.","Eier nur verrühren, nicht aufschlagen.","Kakao mit gutem Aroma verwenden, er gibt den Ton an.","Warm mit Sahne oder kalt als fast trüffelartiger Kuchen – beides ist erlaubt.","Backzeit hängt von der Form ab: In einer kleineren Form brauchst du länger."],"varianten":["Mit Salzkaramell-Swirl","Mit Haselnüssen oder Mandeln","Mit einer Prise Espressopulver","Als Muffins im Silikonförmchen"],"beilagen":["Schlagsahne","Vanilleeis","Frische Himbeeren"],"getraenk":"Starker Kaffee (Fika) oder kalte Milch","quellen":[{"titel":"Swedish Gooey Chocolate Cake – Saveur","url":"https://www.saveur.com/swedish-gooey-chocolate-cake-recipe"},{"titel":"Swedish sticky chocolate cake – Visit Sweden","url":"https://visitsweden.com/what-to-do/food-drink/recipes/swedish-sticky-chocolate-cake-recipe/"},{"titel":"Kladdkaka (Magnus Nilsson) – Food52","url":"https://vercel.food52.com/story/23429-easy-fast-chocolate-cake-recipe-kladdkaka-magnus-nilsson"}],"bild":"kuchen","farben":["#3e2214","#6e3b21","#e8cfa8"],"schlagworte":["Schokolade","Fika","Schnell"]},{"id":"skandinavien-janssons-frestelse","name":"Janssons frestelse","originalname":"Janssons frestelse","kueche":"skandinavien","region":"Schweden","beliebtheit":72,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Cremiger Kartoffelauflauf mit Zwiebeln und würzig-süß eingelegten Sprotten, goldbraun überbacken – das schwedische Weihnachtsgericht, dem man nicht widerstehen kann.","hintergrund":"Janssons frestelse, Janssons Versuchung, ist ein schwedischer Kartoffelauflauf aus Kartoffelstreifen, Zwiebeln, eingelegten Sprotten und Sahne. Woher der Name kommt, ist unklar: Oft wird der Opernsänger Per Adolf Pelle Janzon genannt, doch ein Zusammenhang gilt als unwahrscheinlich. Eine andere Erklärung führt auf den gleichnamigen Film von 1928 mit Edvin Adolphson zurück. Früher gab es das Gericht als spätes Gericht am Ende von Festen, heute gehört es zum Julbord und zum Osterbuffet. Der Fisch ist nicht Anchovis, sondern in Schweden als ansjovis bezeichnete Sprotten, die in Zucker, Salz und Gewürzen eingelegt sind.","portionen":6,"zeit":{"vorbereitung":30,"garen":70,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Auflauf","liste":[{"menge":900,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"in feine Streifen (Julienne) geschnitten, ca. 3 mm dick"},{"menge":2,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in feine Ringe geschnitten"},{"menge":2,"einheit":"Dose","name":"Ansjovis (Sprotten in Würzlake), je ca. 125 g","hinweis":"im IKEA-Lebensmittelmarkt erhältlich; Ersatz: Anchovisfilets, weniger Salz im Auflauf verwenden"},{"menge":400,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":100,"einheit":"ml","name":"Milch","hinweis":""},{"menge":2,"einheit":"EL","name":"Butter","hinweis":"zum Anschwitzen und für die Form"},{"menge":2,"einheit":"EL","name":"Semmelbrösel","hinweis":""},{"menge":null,"einheit":"","name":"weißer Pfeffer","hinweis":"frisch gemahlen"}]}],"ausruestung":["Auflaufform (ca. 2 l)","Reibe oder Messer für Kartoffelstreifen","Pfanne","Backofen"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Schäle die Kartoffeln und die Zwiebeln. Schneide die Kartoffeln mit einem scharfen Messer oder einer Reibe mit Juliennescheibe in dünne Streifen von etwa 3 mm Stärke und lege sie nicht ins Wasser, damit die Stärke erhalten bleibt, die später die Sahne bindet. Schneide die Zwiebeln in feine Halbringe. Öffne die Dosen mit den Sprotten und gieße die Lake in ein Gefäß, du brauchst sie gleich. Heize den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor.","dauer":0,"tipp":""},{"titel":"Zwiebeln weich dünsten","aktion":"anbraten","text":"Erhitze 1 Esslöffel Butter in einer Pfanne bei niedriger bis mittlerer Hitze und dünste die Zwiebeln 8 bis 10 Minuten, bis sie weich und glasig sind und süßlich duften. Sie sollen keine Farbe nehmen, denn der Auflauf soll mild und cremig schmecken. Gib bei Bedarf einen Schuss Wasser dazu. Nimm die Pfanne vom Herd und lass die Zwiebeln kurz abkühlen.","dauer":10,"tipp":""},{"titel":"Form einfetten","aktion":"vorbereiten","text":"Fette die Auflaufform großzügig mit der restlichen Butter ein. Das verhindert, dass die Kartoffeln ansetzen, und gibt dem Boden eine leichte, nussige Note. Lege die Form auf ein Backblech, denn die Sahne kann beim Backen überkochen und im Ofen verbrennen. Stelle die Zutaten in Reichweite bereit, damit du zügig schichten kannst, bevor die Kartoffeln braun werden.","dauer":0,"tipp":""},{"titel":"Schichten","aktion":"schichten","text":"Verteile ein Drittel der Kartoffelstreifen gleichmäßig in der Form, bestreue sie mit etwas weißem Pfeffer, gib die Hälfte der Zwiebeln und der Sprotten darauf. Wiederhole mit einem zweiten Drittel Kartoffeln, dem Rest von Zwiebeln und Fisch. Schließe mit den restlichen Kartoffeln ab. Salze vorsichtig oder gar nicht, denn die Sprotten sind bereits salzig und würzig. Drücke die Schichten leicht an.","dauer":10,"tipp":"Erst probieren, dann salzen: Die Sprotten liefern schon viel Salz."},{"titel":"Sahne und Lake angießen","aktion":"mischen","text":"Vermische Sahne, Milch und zwei bis drei Esslöffel von der Sprottenlake. Gieße die Mischung langsam über den Auflauf, sodass sie bis knapp unter die oberste Kartoffelschicht reicht. Mit der Lake bekommt die Sahne den typischen süß-würzigen Geschmack der Sprotten. Verteile die Semmelbrösel und ein paar Butterflöckchen obenauf; sie bräunen im Ofen zu einer goldenen, knusprigen Kruste.","dauer":0,"tipp":""},{"titel":"Backen","aktion":"ueberbacken","text":"Backe den Auflauf auf der mittleren Schiene etwa 50 bis 60 Minuten, bis die Oberfläche tief goldbraun ist und die Sahne am Rand blubbert. Nach 30 Minuten solltest du ihn kurz prüfen: Wenn die Oberfläche zu dunkel wird, decke ihn locker mit Alufolie ab. Steche mit einem Messer in die Mitte, es sollte ohne Widerstand hineingleiten, ein Zeichen dafür, dass die Kartoffeln gar sind. Der Duft nach gebackener Sahne und Kartoffeln erfüllt die Küche.","dauer":55,"tipp":"Sind die Kartoffeln nach 60 Minuten noch hart, den Auflauf mit Folie abdecken und weitere 10 Minuten backen."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm die Form aus dem Ofen und lasse den Auflauf 10 Minuten ruhen. In dieser Zeit saugen die Kartoffeln die restliche Sahne auf, die Sauce verdickt sich, und der Auflauf lässt sich besser portionieren. Stelle die Form auf ein Holzbrett, sie ist sehr heiß. Er schmeckt warm, aber nicht kochend heiß am besten.","dauer":10,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Steche den Auflauf mit einem großen Löffel in Portionen und serviere ihn direkt aus der Form. In Schweden gehört er zum Julbord, wird aber auch gern zu Ostern und als Beilage zu Schinken und Fisch gegessen. Ein frischer, grüner Salat mit säuerlichem Dressing bildet den perfekten Kontrast zur cremigen Wärme. Dazu passt kaltes Bier oder Aquavit.","dauer":0,"tipp":""}],"profitipps":["Kartoffelstreifen nicht wässern: Die Stärke bindet die Sahne zu einer cremigen Sauce.","Sprotten aus Würzlake sind süßlich-würzig, echte Anchovisfilets schmecken deutlich salziger.","Mit Pfeffer, nicht mit Salz würzen: Der Fisch liefert die Würze.","Die Form auf ein Blech stellen, damit überlaufende Sahne nicht im Ofen verbrennt.","Reste lassen sich am nächsten Tag im Ofen aufwärmen und schmecken oft noch besser."],"varianten":["Mit Räucherfisch oder Hering statt Sprotten","Janssoninkiusaus in Finnland","Mit Käse überbacken","Mit Sauerrahne statt Sahne für eine herbere Note"],"beilagen":["Julbord-Schinken","grüner Salat","Roggenbrot","eingelegte Gurken"],"getraenk":"Kaltes schwedisches Bier, Aquavit oder trockener Weißwein.","koeche":[],"quellen":[{"titel":"Jansson's temptation – Wikipedia","url":"https://en.wikipedia.org/wiki/Janssons_frestelse"}],"bild":"auflauf","farben":["#d9a95a","#f2deaa","#8a5a2a"],"schlagworte":["Julbord","Weihnachten","Auflauf","Schweden"],"vegetarisch_moeglich":false},{"id":"skandinavien-norwegische-fiskesuppe","name":"Norwegische Fiskesuppe","originalname":"Fiskesuppe","kueche":"skandinavien","region":"Norwegen (Küste, Lofoten)","beliebtheit":70,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"suppe","kurz":"Cremige Fischsuppe mit zartem Weißfisch, Lachs, Karotten und Lauch, mit einem Hauch Säure, Dill und Schnittlauch – Norwegens Küstenklassiker.","hintergrund":"Fiskesuppe wird in Norwegen in unzähligen Varianten gekocht und steht in fast jedem Restaurant auf den Lofoten auf der Karte. Die Grundlage ist meist ein heller Fischfond mit Karotte, Lauch und Sellerie, der mit Sahne und manchmal mit Crème fraîche oder etwas Mehl gebunden wird. Dazu kommen Würfel von Weißfisch wie Kabeljau oder Seelachs, oft auch Lachs, und manchmal Garnelen. Typisch ist ein kleiner Schuss Säure, etwa Zitronensaft oder Essig, der die Cremigkeit auflockert, und frischer Dill oder Schnittlauch. Serviert wird die Suppe mit frischem Brot und Butter.","portionen":4,"zeit":{"vorbereitung":20,"garen":30,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Suppe","liste":[{"menge":400,"einheit":"g","name":"Kabeljau- oder Seelachsfilet, ohne Haut","hinweis":"MSC-zertifiziert; Tiefkühlware geht auch"},{"menge":200,"einheit":"g","name":"Lachsfilet, ohne Haut","hinweis":"ASC-zertifizierter Zuchtlachs oder Wildlachs"},{"menge":2,"einheit":"Stück","name":"Karotten (ca. 200 g)","hinweis":"in feine Streifen oder Würfel"},{"menge":1,"einheit":"Stange","name":"Lauch (ca. 150 g)","hinweis":"in dünne Ringe"},{"menge":2,"einheit":"Stange","name":"Staudensellerie","hinweis":"fein gewürfelt"},{"menge":30,"einheit":"g","name":"Butter","hinweis":""},{"menge":25,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":800,"einheit":"ml","name":"Fischfond","hinweis":"Glas oder selbstgekocht"},{"menge":100,"einheit":"ml","name":"trockener Weißwein","hinweis":""},{"menge":250,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":100,"einheit":"g","name":"Crème fraîche","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"Saft und Abrieb"},{"menge":1,"einheit":"Prise","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Bund","name":"Dill","hinweis":""},{"menge":1,"einheit":"Bund","name":"Schnittlauch","hinweis":""},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Topf","Holzlöffel","Schneebesen","scharfes Messer"],"schritte":[{"titel":"Gemüse und Fisch vorbereiten","aktion":"vorbereiten","text":"Schäle die Karotten und schneide sie in feine Stifte von etwa 3 mm Dicke; so garen sie schnell. Wasche den Lauch gründlich, schneide ihn in dünne Ringe und würfele den Sellerie klein. Prüfe Kabeljau und Lachs mit den Fingern auf Gräten und ziehe sie mit der Pinzette heraus. Schneide den Fisch in Würfel von etwa 2,5 cm; sie sollen gleichmäßig sein, damit sie zugleich gar werden. Bis zur Verwendung stelle den Fisch kalt.","dauer":15,"tipp":"Fisch erst im letzten Schritt in die Suppe geben, sonst wird er zäh."},{"titel":"Gemüse andünsten","aktion":"anbraten","text":"Schmilz die Butter in einem großen Topf bei mittlerer Hitze. Gib Lauch, Sellerie und Karotten hinein und dünste sie 5 Minuten, bis sie glänzend und leicht weich sind. Sie sollen kaum Farbe nehmen; die Suppe soll hell und zart werden. Das Gemüse gibt der Suppe eine süßliche Basis und Biss; rühre dabei regelmäßig um, damit nichts am Boden ansetzt und bitter wird.","dauer":6,"tipp":"Das Gemüse nicht braun werden lassen."},{"titel":"Mehl einrühren","aktion":"binden","text":"Streue das Mehl über das Gemüse und rühre 1 bis 2 Minuten, bis es nach Teig duftet und keine Klümpchen mehr sichtbar sind. Das Mehl bindet die Suppe später leicht, ohne sie pappig zu machen. Gieße den Weißwein dazu und lasse ihn 2 Minuten fast vollständig verkochen; der Alkohol verfliegt, die Säure bleibt.","dauer":4,"tipp":"Das Mehl muss kurz durchgaren, damit kein Mehlgeschmack bleibt."},{"titel":"Fond aufgießen","aktion":"kochen","text":"Gieße den Fischfond nach und nach unter ständigem Rühren dazu, damit keine Klumpen entstehen. Bringe alles zum Kochen und lasse die Suppe bei kleiner Hitze 8 bis 10 Minuten leise köcheln, bis das Gemüse weich ist, aber noch Biss hat. Die Suppe soll leicht gebunden sein und einen Löffelrücken dünn überziehen. Schäume Verunreinigungen mit einem Löffel ab.","dauer":10,"tipp":"Ein guter Fond macht die Suppe; ungesalzener Fond lässt dir mehr Kontrolle."},{"titel":"Sahne und Crème fraîche zugeben","aktion":"binden","text":"Rühre Sahne und Crème fraîche ein und bringe die Suppe noch einmal kurz zum Köcheln. Schmecke mit Salz, weißem Pfeffer, einer Prise Zucker und etwas Zitronensaft ab. Die Balance aus Süße, Säure und Salz ist entscheidend: Die Suppe soll cremig, aber nicht schwer schmecken. Taste dich mit dem Zitronensaft vor, denn zu viel lässt sich nicht korrigieren.","dauer":5,"tipp":"Zitrone nach und nach zugeben, bis die Suppe frisch schmeckt."},{"titel":"Fisch einlegen","aktion":"kochen","text":"Reduziere die Hitze, bis die Suppe nur noch leicht zittert. Lege die Fischwürfel hinein und lasse sie 3 bis 4 Minuten ziehen; Lachs braucht etwas weniger als Kabeljau. Der Fisch ist gar, wenn die Würfel überall milchig-weiß beziehungsweise hellrosa und an der Oberfläche leicht flockig sind. Rühre nicht mehr kräftig, damit die Stücke ganz bleiben. Nimm den Topf vom Herd.","dauer":5,"tipp":"Fisch gart in der heißen Suppe nach: lieber früher abziehen."},{"titel":"Kräuter und Abschmecken","aktion":"abschmecken","text":"Hacke den Dill fein und schneide den Schnittlauch in Röllchen. Rühre die Hälfte der Kräuter vorsichtig unter und lasse die Suppe 2 Minuten ziehen. Probiere ein letztes Mal und passe Salz, Pfeffer und Säure an. Die fertige Suppe soll sämig, hell und nach frischem Fisch, Dill und einer feinen Säure duften, ohne dass einzelne Zutaten dominieren.","dauer":3,"tipp":"Frische Kräuter nie lange mitkochen, sonst verlieren sie Aroma und Farbe."},{"titel":"Servieren","aktion":"anrichten","text":"Schöpfe die Suppe in vorgewärmte Teller, achte darauf, dass jeder Teller Fisch und Gemüse bekommt. Bestreue mit den restlichen Kräutern und serviere sofort mit frischem Brot und Butter. Wenn du magst, gibst du einige gekochte Nordseekrabben oder einen Tropfen Dill-Öl obenauf. Die Suppe ist cremig, aber nicht zu schwer.","dauer":5,"tipp":"Am besten am gleichen Tag essen; aufgewärmter Fisch wird trocken."}],"profitipps":["Fisch erst am Ende zugeben und nicht kochen lassen.","Ein Schuss Säure (Zitrone oder Essig) macht die Suppe frisch.","Gemüse fein schneiden, damit es schnell gar wird.","Guten Fischfond verwenden oder selbst kochen.","Suppe nicht mit Mehl überbinden; sie soll leicht sämig bleiben."],"varianten":["Mit Garnelen und Muscheln als Meeresfrüchte-Variante.","Ohne Mehl, nur mit Sahne und Crème fraîche gebunden, wie im Rezept des Restaurants Fiskekrogen.","Mit roter Paprika, Speck oder Schnittlauchöl, wie es auf den Lofoten vorkommt.","Mit Lachs statt Kabeljau."],"beilagen":["frisches Weißbrot mit Butter","Knäckebrot","Zitronenspalten"],"getraenk":"Ein trockener Weißwein (Riesling, Grüner Veltliner) oder ein helles Bier.","koeche":[],"quellen":[{"titel":"Norwegian Fish Soup (Scandification)","url":"https://scandification.com/norwegian-fish-soup-fiskesuppe-recipe/"},{"titel":"Norwegian fiskesuppe (Great British Chefs)","url":"https://www.greatbritishchefs.com/recipes/norwegian-fiskesuppe-recipe"},{"titel":"Norwegian Fish Soup – Fiskekrogen (Saveur)","url":"https://www.saveur.com/fiskekrogens-fish-soup/"},{"titel":"Creamy Norwegian Fiskesuppe (Jennifer Eremeeva)","url":"https://jennifereremeeva.com/norwegian-fiskesuppe/"}],"bild":"suppe","farben":["#f3e3c0","#e8946a","#7aa05a"],"schlagworte":["Norwegen","Lofoten","Fischsuppe","cremig"],"vegetarisch_moeglich":false},{"id":"skandinavien-raeksmoergas","name":"Räksmörgås – das schwedische Krabbenbrot","originalname":"Räksmörgås","kueche":"skandinavien","region":"Schweden (Göteborg, Stockholm, Westküste)","beliebtheit":70,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"meeresfruechte","gang":"abendbrot","kurz":"Buttriges Brot, Salat, Ei, Tomate und ein Berg süßer Krabben unter einem Klecks guter Mayonnaise, mit Dill und Zitrone – das elegante Sandwich der schwedischen Westküste.","hintergrund":"Räksmörgås, wörtlich Krabbenbutterbrot, ist ein klassisches offenes Sandwich, das in Schweden in Cafés, Bars und als leichtes Abendessen gegessen wird. Auf buttrigem Weißbrot liegen Salat, Eischeiben, Tomate und gekochte, geschälte Krabben, darüber kommt eine großzügige Portion Mayonnaise, dazu Dill und Zitrone. Der Stockholmer Küchenchef Erik Lallerstedt vom Restaurant Gondolen empfiehlt eine edlere Version mit einer dicken Scheibe Hefezopfbrot, selbstgemachter Mayonnaise und fein gehackter roter Zwiebel. Wie bei vielen schlichten Gerichten entscheiden Qualität und Frische der Zutaten über das Ergebnis.","portionen":4,"zeit":{"vorbereitung":30,"garen":10,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Belag","liste":[{"menge":4,"einheit":"Scheibe","name":"helles Sauerteig- oder Hefezopfbrot, 1,5 cm dick","hinweis":"Schwedisch würde man Bergis (Hefezopfbrot, Challah) oder Weißbrot nehmen; in Deutschland geht Brioche oder Butterzopf"},{"menge":60,"einheit":"g","name":"weiche Butter","hinweis":"zum Bestreichen"},{"menge":4,"einheit":"Blatt","name":"Kopfsalat oder Lollo Bianco","hinweis":""},{"menge":3,"einheit":"Stück","name":"Eier, hart gekocht","hinweis":""},{"menge":1,"einheit":"Stück","name":"feste Tomate","hinweis":""},{"menge":400,"einheit":"g","name":"gekochte, geschälte Eismeergarnelen (Räkor)","hinweis":"Nordseekrabben oder Eismeergarnelen aus Tiefkühlung; gut abtropfen lassen"},{"menge":0.5,"einheit":"Stück","name":"Salatgurke","hinweis":"optional, dünn gehobelt"},{"menge":1,"einheit":"Bund","name":"Dill","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"in Spalten"},{"menge":1,"einheit":"EL","name":"Forellen- oder Maränenrogen","hinweis":"optional, schwedisch Löjrom"}]},{"gruppe":"Mayonnaise","liste":[{"menge":200,"einheit":"g","name":"gute Mayonnaise","hinweis":"oder selbst gemacht"},{"menge":1,"einheit":"Stück","name":"Eigelb","hinweis":"Raumtemperatur, für die selbstgemachte Mayonnaise"},{"menge":1,"einheit":"TL","name":"Senf","hinweis":"mittelscharf"},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":""},{"menge":150,"einheit":"ml","name":"neutrales Öl","hinweis":"Raps- oder Sonnenblumenöl"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine rote Zwiebel","hinweis":"optional, fein gehackt"}]}],"ausruestung":["Schüssel und Schneebesen für Mayonnaise","Brotmesser","Eierschneider oder scharfes Messer","flache Teller"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Nimm die Butter aus dem Kühlschrank, damit sie streichfähig wird. Taue die Garnelen, falls gefroren, im Kühlschrank auf und lasse sie in einem Sieb gründlich abtropfen; Feuchtigkeit macht das Brot matschig. Wasche den Salat, schüttele ihn trocken und löse ganze Blätter ab. Hacke den Dill und schneide die Zitrone in Spalten. Lege alles bereit, denn ein Räksmörgås wird erst kurz vor dem Servieren belegt.","dauer":10,"tipp":"Je trockener die Garnelen, desto länger bleibt das Brot knusprig."},{"titel":"Eier hart kochen","aktion":"kochen","text":"Lege die Eier in kochendes Wasser und lasse sie 9 Minuten sprudelnd kochen; das Eigelb ist dann fest und hellgelb, ohne grünen Rand. Schrecke sie sofort unter kaltem Wasser ab, damit sie leicht zu pellen sind, und pelle sie unter fließendem Wasser. Schneide sie mit einem Messer oder Eierschneider in saubere, gleichmäßige Scheiben. Lasse sie auskühlen, bis sie benutzt werden.","dauer":12,"tipp":"Mit einem Messer in Scheiben schneiden ergibt sauberere Kanten als mit dem Eierschneider."},{"titel":"Mayonnaise zubereiten","aktion":"aufschlagen","text":"Verrühre Eigelb, Senf, Zitronensaft und Salz in einer Schüssel mit dem Schneebesen. Gieße das Öl zunächst tropfenweise, dann in dünnem Strahl dazu und rühre dabei kräftig, bis eine feste, glänzende, hellgelbe Emulsion entsteht. Wenn sie gerinnt, rühre einen Esslöffel Wasser oder ein neues Eigelb ein. Hebe optional die fein gehackte rote Zwiebel unter, wie es Küchenchef Erik Lallerstedt empfiehlt; sie gibt Biss und gleicht die Fülle aus.","dauer":10,"tipp":"Alle Zutaten sollten Raumtemperatur haben; kaltes Eigelb nimmt Öl schlechter auf."},{"titel":"Brot buttern","aktion":"vorbereiten","text":"Bestreiche die Brotscheiben bis zum Rand dünn mit der weichen Butter. Die Butter dient als Feuchtigkeitssperre und schützt das Brot vor der Mayonnaise und dem Saft der Tomate. Wenn du magst, röstest du das Brot vorher leicht an, dann bleibt es noch stabiler. Streiche die Butter bis in die Ecken, damit keine ungeschützten Stellen bleiben.","dauer":5,"tipp":"Bis zum Rand streichen; sonst wird die Brotkante weich."},{"titel":"Belegen","aktion":"schichten","text":"Lege auf jedes Brot zuerst ein Salatblatt als Unterlage, dann die Eischeiben in einer überlappenden Reihe. Lege Tomatenscheiben und, falls du magst, Gurkenscheiben darauf. Verteile eine großzügige Schicht Mayonnaise. Platziere die Garnelen dicht an dicht, in ordentlichen Reihen oder zu einem Berg gehäuft. Schwedische Köche zählen bei der feinen Variante etwa 16 Garnelen pro Brot.","dauer":10,"tipp":"Nicht zu früh belegen; sonst weicht alles durch."},{"titel":"Garnieren und servieren","aktion":"garnieren","text":"Streue Dill über die Garnelen und setze eine Zitronenspalte und einen Klecks Mayonnaise obenauf; auf Wunsch einen Löffel Rogen. Serviere sofort auf flachen Tellern mit Messer und Gabel; wer es authentisch will, isst es offen. Dazu passen ein kühles Bier oder Weißwein. Das Brot ist dann noch knusprig, die Garnelen kühl und süß, die Mayonnaise cremig.","dauer":5,"tipp":"Zitrone erst am Tisch über die Garnelen träufeln."}],"profitipps":["Gute Mayonnaise ist entscheidend: lieber selbst machen oder eine hochwertige verwenden.","Garnelen gründlich abtropfen lassen.","Brot buttern, damit es nicht durchweicht.","Erst kurz vor dem Servieren belegen.","Für eine edle Version dickes Hefezopfbrot und fein gehackte rote Zwiebel verwenden."],"varianten":["Mit Räucherlachs statt Garnelen.","Mit Löjrom (Maränenrogen) als Garnitur.","Mit Mayonnaise, Dill und Zitronenabrieb vermischt.","Als Mini-Canapés für ein Buffet."],"beilagen":["Kaffee oder Tee","kleiner grüner Salat","Gurkensalat","ein Glas Weißwein"],"getraenk":"Kühles Lagerbier, trockener Weißwein oder ein Glas Sekt.","koeche":[{"name":"Erik Lallerstedt","bezug":"Der Stockholmer Küchenchef vom Restaurant Gondolen beschreibt eine edlere Version des Räksmörgås mit einer dicken Scheibe Hefezopf (Challah), selbstgemachter Mayonnaise und fein gehackter roter Zwiebel; er schneidet die Eier mit dem Messer und legt etwa 16 Garnelen in Reihen darauf.","quelle":"https://nordstjernan.com/news/food/3528"}],"quellen":[{"titel":"The art of the 'Räksmörgås' (Nordstjernan)","url":"https://nordstjernan.com/news/food/3528"},{"titel":"Recipe: How to make a Swedish prawn sandwich (The Local)","url":"https://www.thelocal.se/20170210/recipe-how-to-make-a-swedish-prawn-sandwich"},{"titel":"Räksmörgås: Swedish Prawn Sandwich (The Petite Cook)","url":"https://www.thepetitecook.com/swedish-prawn-sandwich/"}],"bild":"sandwich","farben":["#f2d9a8","#e87a5a","#7aa05a"],"schlagworte":["Sandwich","Garnelen","Schweden","Café-Klassiker"],"vegetarisch_moeglich":false},{"id":"skandinavien-stegt-roedspaette-persillesovs","name":"Stegt rødspætte mit Petersiliensauce","originalname":"Stegt rødspætte med persillesovs og kartofler","kueche":"skandinavien","region":"Dänemark","beliebtheit":70,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Knusprig gebratene Schollenfilets mit Petersiliensauce, neuen Kartoffeln und Zitrone – das dänische Alltagsklassiker-Gericht, das Generationen von Kindern kennen.","hintergrund":"In Dänemark heißt die Scholle „rødspætte“ und gehört zu den am häufigsten gegessenen Fischen. Die gebratenen, panierten Filets werden auf Smørrebrød mit Remoulade und Zitrone gelegt, kalt oder warm, oder als Hauptgericht mit Pommes frites oder Kartoffeln serviert; auch auf Kinderkarten in dänischen Restaurants steht das Gericht oft. Die dänische Familienvariante kommt mit Petersiliensauce, die mit Milch oder Fischfond und Butter gebunden wird, und neuen Kartoffeln im Frühling. Rødspætte gilt als Fisch der Nordsee- und Ostseeküste, den man in Dänemark das ganze Jahr über kaufen kann; im Frühling sind Schollen besonders begehrt.","portionen":4,"zeit":{"vorbereitung":30,"garen":25,"ruhen":10},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Scholle","liste":[{"menge":8,"einheit":"","name":"Schollenfilets (ca. 80–100 g je Filet)","hinweis":"mit Haut oder ohne; alternativ Rotzunge oder Seelachs"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":null,"einheit":"","name":"weißer Pfeffer","hinweis":"nach Geschmack"},{"menge":80,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":2,"einheit":"","name":"Eier","hinweis":""},{"menge":150,"einheit":"g","name":"feines Paniermehl","hinweis":""},{"menge":60,"einheit":"g","name":"Butter","hinweis":"zum Braten"},{"menge":2,"einheit":"EL","name":"Rapsöl","hinweis":"zum Braten"},{"menge":1,"einheit":"","name":"Zitrone","hinweis":"in Spalten"}]},{"gruppe":"Für die Petersiliensauce","liste":[{"menge":30,"einheit":"g","name":"Butter","hinweis":""},{"menge":30,"einheit":"g","name":"Weizenmehl","hinweis":""},{"menge":350,"einheit":"ml","name":"Milch","hinweis":"oder halb Milch, halb Fischfond"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":""},{"menge":null,"einheit":"","name":"Salz, weißer Pfeffer und Muskat","hinweis":"nach Geschmack"}]},{"gruppe":"Beilagen","liste":[{"menge":800,"einheit":"g","name":"neue Kartoffeln","hinweis":"klein, festkochend"},{"menge":2,"einheit":"EL","name":"Remoulade","hinweis":"zum Servieren, optional"}]}],"ausruestung":["Große, beschichtete oder gusseiserne Pfanne","Fischheber oder breiter Wender","Kleiner Topf","3 flache Teller","Gitter und Backblech"],"schritte":[{"titel":"Mise en place und Fisch prüfen","aktion":"vorbereiten","text":"Frische Schollenfilets sind glänzend, durchscheinend und riechen nach Meer, nicht nach Fisch. Tupfe sie mit Küchenpapier trocken und schneide sie bei Bedarf in einheitliche Stücke von etwa 12 cm Länge, damit sie gleichzeitig gar werden. Ziehe vorhandene Gräten mit einer Pinzette. Wasche die Kartoffeln, hacke die Petersilie fein und schneide die Zitrone in Spalten. Stelle drei flache Teller für die Panierstraße bereit.","dauer":10,"tipp":""},{"titel":"Kartoffeln aufsetzen","aktion":"kochen","text":"Lege die Kartoffeln mit Schale in einen Topf mit kaltem Salzwasser und bringe sie zum Kochen. Lasse sie 15–20 Minuten leise sieden, bis ein Messer mühelos eindringt. Gieße sie ab, lass sie ausdampfen und halte sie warm. Neue Kartoffeln haben eine dünne Schale, die du mitessen kannst. Reibe sie nach dem Abgießen kurz im Topf mit dem geschlossenen Deckel ab, damit sie ausdampfen und ihre Schale trocken wird. Wer die Kartoffeln lieber kleiner mag, halbiert größere Stücke, damit sie gleichmäßig gar werden. Ein Löffel Butter und etwas Petersilie darüber runden den Geschmack ab.","dauer":20,"tipp":""},{"titel":"Petersiliensauce anrühren","aktion":"binden","text":"Zerlasse die Butter in einem kleinen Topf, rühre das Mehl ein und schwitze es 1–2 Minuten bei mittlerer Hitze, ohne dass es Farbe nimmt. Gieße die kalte Milch nach und nach unter ständigem Rühren dazu und lasse die Sauce 5 Minuten leise köcheln, bis sie sämig ist. Würze mit Salz, Pfeffer und Muskat, rühre die Petersilie unter und gib einen Spritzer Zitronensaft hinein. Die Sauce soll hellgrün, cremig und frisch sein.","dauer":10,"tipp":"Die Petersilie erst zum Schluss einrühren – sie behält so ihre Farbe und ihren Duft."},{"titel":"Scholle würzen und panieren","aktion":"panieren","text":"Salze die Filets leicht und pfeffere sie. Wende sie im Mehl, klopfe den Überschuss ab, ziehe sie durch das verquirlte Ei und drücke sie fest in das Paniermehl. Die Panade soll geschlossen sein und keine kahlen Stellen haben. Lasse die panierten Filets 10 Minuten auf einem Gitter ruhen, damit die Panade bindet. Rutscht die Panade beim Anfassen ab, waren die Filets zu feucht: Tupfe sie vor dem Mehlieren noch einmal gründlich ab. Nimm die Filets stets mit einer trockenen Hand aus dem Mehl und einer nassen aus dem Ei, damit sich keine Klumpen an den Fingern bilden.","dauer":10,"tipp":""},{"titel":"Butter und Öl erhitzen","aktion":"vorbereiten","text":"Erhitze Butter und Öl in einer großen Pfanne bei mittlerer bis hoher Hitze. Das Öl verhindert, dass die Butter verbrennt. Sobald die Butter aufschäumt und der Schaum sich beruhigt, ist die Pfanne heiß genug (etwa 160–170 °C). Gib ein Krümelchen Panade hinein: Es soll sofort leise brutzeln. Heißes Fett ist wichtig, denn so schließt sich die Panade sofort und saugt kaum Fett auf. Ist die Pfanne zu kalt, wird die Kruste fettig und matt; ist sie zu heiß, verbrennt die Butter und schmeckt bitter. Reduziere die Hitze, sobald die Butter braun wird.","dauer":3,"tipp":""},{"titel":"Filets braten","aktion":"braten","text":"Lege die Filets mit der schönen Seite nach unten in die Pfanne, nicht zu viele auf einmal, und brate sie 2–3 Minuten, bis die Unterseite goldbraun und knusprig ist. Wende sie behutsam mit dem Fischheber und brate sie weitere 1–2 Minuten. Der Fisch ist gar, wenn das Fleisch weiß und blickdicht ist; die Kerntemperatur beträgt 58–60 °C. Hebe die Filets auf Küchenpapier und halte sie warm.","dauer":8,"tipp":"Nur einmal wenden, sonst bricht das zarte Fleisch."},{"titel":"Anrichten","aktion":"anrichten","text":"Lege je zwei Filets auf einen vorgewärmten Teller, gieße die Petersiliensauce daneben (nicht darüber, damit die Kruste knusprig bleibt) und serviere dazu die Kartoffeln und Zitronenspalten. Optional reichst du Remoulade und einen kleinen Gurkensalat dazu. Serviere sofort, solange die Panade noch knackt. Lege die Zitronenspalten und eine Gabel bereit. Der Teller soll goldgelb, grün und weiß aussehen, die Sauce duftet nach Petersilie und Butter. Wer mag, serviert dazu einen Klecks Remoulade und einen kleinen Gurkensalat.","dauer":0,"tipp":""},{"titel":"Abschmecken und Zitrone","aktion":"abschmecken","text":"Beträufle die Filets erst am Tisch mit Zitronensaft, damit die Panade nicht durchweicht. Probiere die Sauce nach: Sie soll milchig-mild, leicht pfeffrig und frisch nach Petersilie schmecken. Wenn etwas fehlt, hilft eine Prise Salz oder ein Spritzer Zitrone. Prüfe, ob das Fleisch an der dicksten Stelle weiß und leicht zerfällt und ob die Kruste hörbar knackt, wenn du mit der Gabel hineinstichst. Der Geschmack soll mild und leicht süßlich sein, die Sauce frisch und leicht pfeffrig. Wenn etwas fehlt, hilft eine Prise Salz.","dauer":0,"tipp":""}],"profitipps":["Scholle ist zart und gart sehr schnell – nicht zu lange braten.","Panade ruhen lassen, dann klebt sie am Fisch.","Butter und Öl mischen: So bräunt die Butter ohne zu verbrennen.","Petersilie erst am Schluss zugeben.","Filets nur einmal wenden."],"varianten":["Kalt auf Smørrebrød mit Remoulade und Zitrone.","Mit Pommes frites statt Kartoffeln.","Mit Dillsauce statt Petersilie.","Mit Rotzunge oder Seelachs statt Scholle."],"beilagen":["Neue Kartoffeln","Remoulade","Gurkensalat","Zitronenspalten"],"getraenk":"Helles Lagerbier oder ein trockener Riesling; für Kinder ein Apfelschorle.","koeche":[],"quellen":[{"titel":"European plaice – Wikipedia","url":"https://en.wikipedia.org/wiki/European_plaice"}],"bild":"fisch","farben":["#d9a24a","#9bbf6a","#f3e2b3"],"schlagworte":["Dänemark","Familienessen","Scholle","paniert"],"vegetarisch_moeglich":false,"hinweis":"Scholle bekommst du beim Fischhändler oder tiefgekühlt; achte auf MSC-Siegel. Alternativ passen Rotzunge, Seelachs oder Kabeljau."},{"id":"skandinavien-skagenroera","name":"Skagenröra (Toast Skagen)","originalname":"Skagenröra","kueche":"skandinavien","region":"Schweden","beliebtheit":68,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Cremiger Garnelensalat mit Dill und Zitrone auf knusprig gebratenem Toast, gekrönt mit Löwenrogen – die schwedische Vorspeise aus den Restaurants von Stockholm.","hintergrund":"Skagenröra ist ein Garnelensalat aus Mayonnaise, saurer Sahne und Dill, serviert auf geröstetem Brot und garniert mit Rogen. Erfunden und in den 1950er-Jahren bekannt gemacht hat ihn der Stockholmer Restaurateur Tore Wretman. Der Name geht auf Skagen in Dänemark zurück, wo es ein ähnliches Gericht namens Skagenssalat gibt. Heute wird er in ganz Skandinavien als Vorspeise serviert, besonders im Frühling, Sommer und Herbst. Statt Garnelen wird auch Krabbenfleisch verwendet, die Krabbenversion ist in der schwedischen und finnischen Krabbensaison von Juli bis Oktober besonders beliebt.","portionen":4,"zeit":{"vorbereitung":25,"garen":8,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Skagenröra","liste":[{"menge":400,"einheit":"g","name":"gekochte, geschälte Garnelen","hinweis":"am besten kleine Eismeergarnelen oder Nordseekrabben; gut abgetropft"},{"menge":100,"einheit":"g","name":"Mayonnaise","hinweis":"gute Qualität, möglichst Eigenmarke ohne Süße"},{"menge":100,"einheit":"g","name":"Crème fraîche","hinweis":"oder saure Sahne"},{"menge":4,"einheit":"EL","name":"Dill","hinweis":"fein gehackt, plus Spitzen zum Garnieren"},{"menge":1,"einheit":"EL","name":"rote Zwiebel","hinweis":"sehr fein gewürfelt"},{"menge":1,"einheit":"TL","name":"Dijonsenf","hinweis":""},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":"plus etwas Abrieb einer Bio-Zitrone"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":""}]},{"gruppe":"Toast","liste":[{"menge":4,"einheit":"Scheibe","name":"Toastbrot oder Brioche","hinweis":"dick geschnitten"},{"menge":30,"einheit":"g","name":"Butter","hinweis":"zum Braten"},{"menge":40,"einheit":"g","name":"Löwenrogen oder Forellenkaviar","hinweis":"zum Garnieren"},{"menge":4,"einheit":"Stück","name":"Zitronenspalten","hinweis":""}]}],"ausruestung":["Schüssel","beschichtete Pfanne","Küchenpapier","scharfes Messer"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Nimm die Garnelen aus dem Kühlschrank und lasse sie tiefgekühlte Ware langsam im Kühlschrank auftauen. Lege sie auf mehrere Lagen Küchenpapier und tupfe sie gründlich trocken, denn Wasser würde die Creme verdünnen und die Würze verwässern. Hacke den Dill fein, würfele die Zwiebel so klein wie möglich und reibe etwas Zitronenschale ab. Stelle Mayonnaise und Crème fraîche bereit.","dauer":0,"tipp":""},{"titel":"Garnelen trocknen und prüfen","aktion":"abseihen","text":"Prüfe die Garnelen auf Reste von Schalen oder dunkle Darmfäden und entferne sie. Wenn sie sehr groß sind, schneide sie in grobe Stücke, damit sich alles gut mit der Creme verbindet. Lasse sie in einem Sieb 10 Minuten abtropfen und tupfe erneut ab. Trockene Garnelen sorgen für eine feste, cremige Konsistenz, die auf dem Brot nicht wegläuft.","dauer":10,"tipp":""},{"titel":"Dressing anrühren","aktion":"mischen","text":"Verrühre Mayonnaise und Crème fraîche in einer Schüssel zu einer glatten Creme. Gib den Senf, den Zitronensaft und etwas Zitronenschale hinzu und rühre alles gut durch. Das Dressing sollte cremig, frisch und leicht säuerlich schmecken; die Säure von Crème fraîche und Zitrone gleicht die Fülle der Mayonnaise aus. Schmecke mit einer Prise Salz und weißem Pfeffer ab.","dauer":3,"tipp":""},{"titel":"Dill und Zwiebel untermischen","aktion":"hacken","text":"Rühre den fein gehackten Dill und die Zwiebelwürfel in das Dressing. Der Dill ist das Herzstück dieser Creme: Er soll reichlich vorhanden sein und frisch und grün duften. Die rote Zwiebel gibt einen knackigen, leicht scharfen Akzent, hat aber auch eine Farbe, die das Gericht schön aussehen lässt. Verwende nur einen Esslöffel, damit sie nicht dominiert.","dauer":2,"tipp":""},{"titel":"Garnelen unterheben","aktion":"mischen","text":"Hebe die trockenen Garnelen vorsichtig mit einem Löffel unter die Dill-Creme, sodass die Stücke ganz bleiben. Schmecke noch einmal mit Salz, Pfeffer und Zitronensaft ab. Die Röra soll cremig, aber nicht flüssig sein und die Garnelen gut umhüllen. Wenn sie zu fest ist, gib einen Teelöffel Crème fraîche hinzu.","dauer":3,"tipp":""},{"titel":"Kalt stellen und durchziehen lassen","aktion":"kuehlen","text":"Decke die Schüssel mit Frischhaltefolie ab und stelle sie mindestens 30 Minuten in den Kühlschrank. Die Aromen von Dill, Zitrone und Garnelen verbinden sich, und die Creme wird fester. Kalt serviert schmeckt die Röra am frischesten. Bereite sie am besten höchstens 4 Stunden vor dem Servieren zu, damit die Garnelen nicht wässrig werden.","dauer":30,"tipp":""},{"titel":"Toast in Butter braten","aktion":"braten","text":"Schmilz die Butter in einer beschichteten Pfanne bei mittlerer Hitze, bis sie schäumt und nach Nuss duftet. Brate die Brotscheiben 2 bis 3 Minuten pro Seite, bis sie goldbraun und knusprig sind, aber innen noch weich. Lege sie auf Küchenpapier, damit überschüssiges Fett abtropft. Der warme, buttrige Toast bildet einen schönen Kontrast zur kalten, cremigen Röra.","dauer":6,"tipp":"Das Brot erst kurz vor dem Servieren braten, damit es knusprig bleibt."},{"titel":"Anrichten","aktion":"anrichten","text":"Lege den Toast auf Teller und häufe die kalte Skagenröra großzügig darauf. Setze einen Löffel Löwenrogen oben auf, er gibt Farbe, Salz und einen feinen Knack. Garniere mit Dillspitzen und einer Zitronenspalte. In Schweden wird er als elegante Vorspeise serviert, oft mit einem Glas Sekt oder Weißwein. Serviere sofort, damit der Toast nicht durchweicht.","dauer":0,"tipp":""}],"profitipps":["Garnelen gründlich trocknen: Feuchtigkeit macht die Creme wässrig.","Viel frischer Dill ist das Markenzeichen; getrockneter Dill ersetzt ihn nicht.","Toast in Butter braten statt toasten, das gibt Aroma und Biss.","Löwenrogen gibt dem Gericht Farbe und Würze; in Deutschland gibt es ihn als Ersatz für echten Stenbitsrom.","Bereite die Röra am besten kurz vor dem Servieren zu und lass sie kalt durchziehen."],"varianten":["Mit Krabbenfleisch in der Saison","Mit geriebenem Meerrettich für Schärfe","Als Canapé auf Blini oder Rye-Cracker","Mit Avocado als frischere Variante"],"beilagen":["Zitronenspalte","Dill","grüner Salat"],"getraenk":"Sekt, trockener Riesling oder eiskaltes Pils.","koeche":[],"quellen":[{"titel":"Toast Skagen – Wikipedia","url":"https://en.wikipedia.org/wiki/Toast_Skagen"}],"bild":"meeresfruechte","farben":["#e8a07a","#f6e2b8","#5b8a4a"],"schlagworte":["Vorspeise","Garnelen","Schweden","Fest"],"vegetarisch_moeglich":false},{"originalname":"Æbleskiver","region":"Dänemark","hauptkategorie":"suess","fleischsorte":"","gang":"gebaeck","koeche":[],"vegetarisch_moeglich":true,"id":"skandinavien-aebleskiver","name":"Æbleskiver","kueche":"skandinavien","beliebtheit":66,"kurz":"Kugelrunde dänische Pfannkuchen aus luftigem Buttermilchteig, gewendet in der Spezialpfanne und mit Puderzucker und Marmelade gegessen.","hintergrund":"Æbleskiver sind in Dänemark vor allem in der Weihnachtszeit ein Muss und werden dort auf Weihnachtsmärkten und zu Hause serviert, oft mit Glögg. Der Name bedeutet wörtlich „Apfelscheiben“, was auf ältere Varianten mit Apfelstückchen im Teig hinweist; heute sind sie meist ohne Apfel. Gebacken werden sie in einer speziellen Pfanne mit halbkugelförmigen Mulden und mit einem Stricknadel- oder Holzspieß gewendet. Außen sind sie zart gebräunt, innen luftig-weich und fast hohl.","portionen":6,"zeit":{"vorbereitung":20,"garen":30,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig","liste":[{"menge":250,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":2,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Natron","hinweis":""},{"menge":0.5,"einheit":"TL","name":"gemahlener Kardamom","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":3,"einheit":"Stück","name":"Eier","hinweis":"Größe M, getrennt"},{"menge":400,"einheit":"ml","name":"Buttermilch","hinweis":""},{"menge":40,"einheit":"g","name":"Butter","hinweis":"geschmolzen, plus Butter oder Öl zum Ausbacken"}]},{"gruppe":"Zum Servieren","liste":[{"menge":4,"einheit":"EL","name":"Puderzucker","hinweis":""},{"menge":150,"einheit":"g","name":"Himbeer- oder Erdbeermarmelade","hinweis":""}]}],"ausruestung":["Æbleskiver-Pfanne mit 7 Mulden","2 Holzspieße oder Stricknadeln","Handrührer","Schüsseln","Pinsel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Trenne die Eier und achte darauf, dass kein Dotter ins Eiweiß gelangt; Fett würde das Aufschlagen verhindern. Schmilz die Butter und lasse sie leicht abkühlen. Verrühre Mehl, Backpulver, Natron, Kardamom, Salz und Zucker in einer großen Schüssel. Stelle Marmelade, Puderzucker und Holzspieße bereit, damit du später ohne Unterbrechung arbeiten kannst.","dauer":8,"tipp":""},{"titel":"Teig anrühren","aktion":"mischen","text":"Verrühre Eigelb und Buttermilch in einer Schüssel und gieße sie zu den trockenen Zutaten. Rühre alles zügig zu einem glatten, noch leicht klumpigen Teig, ohne zu lange zu schlagen. Gib die flüssige Butter dazu. Der Teig soll dickflüssig wie ein dicker Pfannkuchenteig sein und langsam vom Löffel fließen. Zu viel Rühren macht ihn zäh.","dauer":5,"tipp":""},{"titel":"Eischnee unterheben","aktion":"aufschlagen","text":"Schlage das Eiweiß mit einer Prise Salz steif, bis es glänzt und beim Umdrehen der Schüssel nicht herausrutscht. Hebe ein Drittel unter den Teig, um ihn aufzulockern, und ziehe dann den Rest vorsichtig mit einem Teigschaber unter. Arbeite behutsam von unten nach oben, damit die Luft im Teig bleibt. Der Teig soll leicht und mousseartig sein; er ist der Grund für die luftige Innentextur.","dauer":8,"tipp":""},{"titel":"Pfanne vorbereiten","aktion":"vorbereiten","text":"Erhitze die Pfanne bei mittlerer Hitze und streiche jede Mulde großzügig mit Butter oder Öl ein. Die Pfanne ist heiß genug, wenn ein Tropfen Teig sofort zischt, aber nicht schwarz wird. Zu heiße Pfannen verbrennen die Außenseite, bevor der Teig innen gar ist. Stelle die Hitze lieber etwas niedriger.","dauer":5,"tipp":""},{"titel":"Teig einfüllen und backen","aktion":"braten","text":"Fülle jede Mulde zu etwa drei Vierteln mit Teig. Backe die Æbleskiver etwa zwei Minuten, bis der Rand fest wird und sich Bläschen bilden. Drehe jede Kugel mit einem Holzspieß um etwa ein Viertel, sodass der noch flüssige Teig in die Mulde fließt und eine runde Form entsteht. Wiederhole das alle 30 bis 40 Sekunden, bis die Kugeln rundum goldbraun sind und sich beim Anstechen innen luftig anfühlen. Das dauert insgesamt etwa fünf bis sechs Minuten pro Charge.","dauer":25,"tipp":"Stecke ein Holzstäbchen in die Mitte: Kommt es trocken heraus, sind sie gar."},{"titel":"Servieren","aktion":"anrichten","text":"Hebe die Æbleskiver aus den Mulden und lege sie auf einen Teller. Bestäube sie dick mit Puderzucker und serviere sie sofort warm mit Marmelade zum Eintunken. Dazu passt Glögg (dänischer Glühwein) oder heißer Kaffee. Achte darauf, jede Charge sofort zu essen, denn kalt werden sie schnell zäh. Wer möchte, steckt vor dem Backen einen Apfelwürfel oder ein Stück Marzipan in den Teig.","dauer":2,"tipp":""}],"profitipps":["Teig nicht zu lange rühren, sonst werden sie zäh.","Eischnee unbedingt vorsichtig unterheben.","Pfanne nicht zu heiß werden lassen.","Wenden mit Holzspieß oder Stricknadel – Gabel zerstört die Form.","Bei niedriger Hitze backen, damit sie innen durchgaren."],"varianten":["Mit Apfelstückchen im Teig","Mit Marzipan- oder Schokoladenfüllung","Mit Zimtzucker statt Puderzucker","Mit Zitronenabrieb im Teig"],"beilagen":["Himbeermarmelade","Puderzucker","Glögg"],"getraenk":"Glögg oder Kaffee","quellen":[{"titel":"Æbleskiver – denmark.dk","url":"https://denmark.dk/people-and-culture/christmas-recipes/aebleskiver"},{"titel":"Aebleskiver – Danish pancakes – Scandi Kitchen","url":"https://www.scandi.co.uk/recipes/aebleskiver-danish-pancakes/"},{"titel":"Danish Christmas fritter recipe – Great British Chefs","url":"https://greatbritishchefs.com/recipes/danish-christmas-fritter-recipe"}],"bild":"gebaeck","farben":["#d9a158","#f6e5c2","#a34f2a"],"schlagworte":["Weihnachten","Dänemark","Pfanne"]},{"id":"skandinavien-aertsoppa-med-flaesk","name":"Ärtsoppa med fläsk","originalname":"Ärtsoppa med fläsk","kueche":"skandinavien","region":"Schweden","beliebtheit":66,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"eintopf","kurz":"Die schwedische Donnerstagssuppe: gelbe Erbsen mit gepökeltem Schweinefleisch, Majoran und Senf – traditionell gefolgt von Pfannkuchen mit Marmelade.","hintergrund":"Ärtsoppa wird in Schweden und Finnland seit mindestens dem Mittelalter gegessen und ist fest mit dem Donnerstag verbunden: Der Brauch stammt vermutlich aus katholischer Zeit, als man sich vor dem Freitagsfasten stärkte. Noch heute steht die Suppe in Schulen, Kasernen und vielen Restaurants am Donnerstag auf dem Plan. Man kocht ganze gelbe Erbsen mit gepökeltem Schweinefleisch, würzt mit Majoran und Thymian und reicht Senf dazu. Nach der Suppe folgen dünne Pfannkuchen (pannkakor) mit Marmelade und Sahne, und in manchen Gegenden gibt es dazu warmen Punsch. August Strindberg soll die Suppe als „Speise der Götter“ bezeichnet haben.","portionen":6,"zeit":{"vorbereitung":20,"garen":120,"ruhen":720},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Suppe","liste":[{"menge":500,"einheit":"g","name":"gelbe Erbsen, ganz","hinweis":"über Nacht eingeweicht; keine geschälten Spalterbsen verwenden"},{"menge":700,"einheit":"g","name":"gepökeltes Schweinefleisch","hinweis":"Pökelbauch, Pökelschulter oder Kasseler am Stück"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"geschält, eine halbiert"},{"menge":2,"einheit":"l","name":"Wasser","hinweis":"ca."},{"menge":2,"einheit":"TL","name":"getrockneter Majoran"},{"menge":1,"einheit":"TL","name":"getrockneter Thymian"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":null,"einheit":"","name":"kräftiger Senf (z. B. Dijon oder schwedischer Senap)","hinweis":"nach Geschmack"},{"menge":null,"einheit":"","name":"Marmelade (Preiselbeer oder Himbeer) und Schlagsahne","hinweis":"zu den Pfannkuchen"}]},{"gruppe":"Für die Pfannkuchen (Nachspeise)","liste":[{"menge":150,"einheit":"g","name":"Weizenmehl"},{"menge":3,"einheit":"Stück","name":"Eier"},{"menge":500,"einheit":"ml","name":"Milch"},{"menge":1,"einheit":"Prise","name":"Salz"},{"menge":30,"einheit":"g","name":"Butter","hinweis":"zum Ausbacken"}]}],"ausruestung":["großer, schwerer Topf","Schaumkelle","Pürierstab oder Kartoffelstampfer"],"schritte":[{"titel":"Erbsen einweichen","aktion":"einlegen","text":"Gib die Erbsen am Vorabend in eine große Schüssel und bedecke sie reichlich mit kaltem Wasser, da sie auf mehr als das Doppelte aufquellen. Nach 10 bis 12 Stunden sind die Erbsen prall und die Haut glatt. Schöpfe schwimmende Schalen mit dem Sieb ab und gieße das Einweichwasser weg. Spüle die Erbsen noch einmal ab. Das Einweichen verkürzt die Garzeit deutlich und macht die Suppe bekömmlicher.","dauer":0,"tipp":"Auf keinen Fall Natron ins Wasser geben – das zerstört Geschmack und Vitamine."},{"titel":"Fleisch ansetzen","aktion":"kochen","text":"Spüle das Pökelfleisch kurz kalt ab. Wenn es stark gesalzen ist, legst du es 30 Minuten in kaltes Wasser. Lege es in den Topf, füge die Erbsen hinzu und gieße etwa 2 Liter kaltes Wasser an, bis alles knapp bedeckt ist. Bringe es langsam zum Kochen und schöpfe den grauen Schaum ab. Schäumt es nicht mehr, nimm die Hitze sofort zurück. Erst nach dem Garen salzen: Das Pökelfleisch gibt selbst Salz ab.","dauer":10,"tipp":""},{"titel":"Zwiebeln und Kräuter zugeben","aktion":"koecheln","text":"Gib die Zwiebeln, Majoran und Thymian in den Topf, setze den Deckel schräg auf und lass alles bei sehr schwacher Hitze leise sieden. Du erkennst die richtige Hitze daran, dass nur gelegentlich Blasen aufsteigen; wenn die Suppe stark kocht, setzen sich die Erbsen am Boden an und brennen an. Rühre alle 15 Minuten vorsichtig mit dem Holzlöffel auf dem Topfboden, um das zu verhindern.","dauer":15,"tipp":""},{"titel":"Langsam garen","aktion":"koecheln","text":"Lass die Suppe 90 Minuten bei schwacher Hitze kochen. Die Erbsen sind fertig, wenn sie beim Rühren zerfallen und die Suppe sämig wird; probiere eine Erbse, sie soll sich zwischen den Fingern leicht zerdrücken lassen und innen mehlig-weich sein. Wenn die Suppe zu dick wird, gieße etwas heißes Wasser nach, wenn sie zu dünn bleibt, koche sie ohne Deckel noch 10 Minuten ein.","dauer":90,"tipp":""},{"titel":"Fleisch herausnehmen","aktion":"abseihen","text":"Hebe das gepökelte Schweinefleisch aus dem Topf, lege es auf ein Brett und lasse es 5 Minuten ruhen. Schneide es danach in 1 cm dicke Scheiben und entferne dabei Schwarte und Knochen. Halte die Fleischscheiben mit etwas Brühe zugedeckt warm. Fische die Zwiebelstücke und Thymianzweige aus der Suppe und wirf sie weg.","dauer":10,"tipp":""},{"titel":"Suppe sämig rühren und würzen","aktion":"puerieren","text":"Zerdrücke einen Teil der Erbsen mit dem Kartoffelstampfer oder püriere ein Drittel der Suppe kurz mit dem Stab, damit sie eine cremige Konsistenz bekommt, aber noch ganze Erbsen enthält. Schmecke mit Pfeffer, etwas zusätzlichem Majoran und, falls nötig, Salz ab; die Suppe sollte würzig, nicht salzig sein. Erwärme sie unter Rühren noch einmal auf, damit sie dampfend heiß serviert wird.","dauer":5,"tipp":""},{"titel":"Servieren mit Senf","aktion":"anrichten","text":"Schöpfe die Suppe in tiefe Teller, lege zwei oder drei Scheiben Fleisch daneben oder obenauf und reiche kräftigen Senf separat, den jeder in die Suppe rührt. Dazu passt Knäckebrot oder Schwarzbrot. Nach der Suppe folgen traditionell dünne Pfannkuchen mit Preiselbeer- oder Himbeermarmelade und Schlagsahne; in manchen Gegenden trinkt man dazu warmen Punsch.","dauer":0,"tipp":""},{"titel":"Pfannkuchen für die Nachspeise backen","aktion":"braten","text":"Verrühre Mehl, Eier, Milch und eine Prise Salz mit dem Schneebesen zu einem dünnflüssigen, klumpenfreien Teig, den du 15 Minuten quellen lässt. Erhitze eine Pfanne mit etwas Butter bei mittlerer Hitze und gieße eine kleine Kelle Teig hinein; schwenke die Pfanne, damit er hauchdünn verläuft. Backe den Pfannkuchen 1 bis 2 Minuten, bis der Rand goldbraun ist und sich löst, wende ihn und backe die andere Seite kurz. Halte die fertigen Pfannkuchen zugedeckt im 80 °C warmen Ofen warm und serviere sie mit Marmelade und Schlagsahne.","dauer":25,"tipp":"Der erste Pfannkuchen ist meist ein Probestück – er hilft dir, die Hitze richtig einzustellen."}],"profitipps":["Ganze gelbe Erbsen verwenden, keine geschälten – sie geben der Suppe Biss und Charakter.","Nie früh salzen: Pökelfleisch liefert viel Salz, das sich erst im Lauf des Kochens zeigt.","Auf schwacher Hitze kochen, sonst brennen die Erbsen am Boden an.","Majoran und Senf sind die typisch schwedischen Würzmittel; sparsam, aber nicht weglassen.","Am nächsten Tag zieht die Suppe nach und wird sehr dick – mit Wasser verdünnen."],"varianten":["Finnische Hernekeitto mit grünen Erbsen","Dänische Gule ærter mit Medisterpølse und Rote Bete","Niederländische Erwtensoep (Snert) mit Rookworst","Vegetarisch mit geräuchertem Tofu und Lorbeer"],"beilagen":["Senf","Knäckebrot","Pfannkuchen mit Marmelade","Punsch (warm)"],"getraenk":"Ein kräftiges Bier oder warmer Punsch zum Nachtisch","koeche":[],"quellen":[{"titel":"Pea soup – Wikipedia (Abschnitt Schweden/Finnland)","url":"https://en.wikipedia.org/wiki/Pea_soup"}],"bild":"eintopf","farben":["#d6b040","#e9d89a","#8a5a20"],"schlagworte":["Schweden","Erbsen","Donnerstag","Pökelfleisch","Pfannkuchen"],"vegetarisch_moeglich":false,"themen":[]},{"id":"skandinavien-stegt-flaesk-med-persillesovs","name":"Stegt flæsk med persillesovs","originalname":"Stegt flæsk med persillesovs","kueche":"skandinavien","region":"Dänemark","beliebtheit":66,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Knusprig gebratene Schweinebauchscheiben mit neuen Kartoffeln und cremiger Petersiliensauce – Dänemarks Nationalgericht.","hintergrund":"Stegt flæsk med persillesovs ist ein schlichtes, aber geliebtes dänisches Gericht: gebratene Scheiben vom frischen, leicht gesalzenen, nicht geräucherten Schweinebauch mit gekochten Kartoffeln und Petersiliensauce. Der Name bedeutet gebratene Schweinestreifen. Im Jahr 2014 wurde es nach einem Bericht der Zeitung Politiken zum Nationalgericht Dänemarks erklärt. Englische Kochbücher von 1958 und 1964 übersetzten es als Speck mit Petersiliensauce. Seit den 2000er-Jahren isst man es am Wahlabend als Wortspiel mit valgflæsk, wie Dänen Wahlversprechen nennen.","portionen":4,"zeit":{"vorbereitung":20,"garen":45,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Schweinebauch","liste":[{"menge":800,"einheit":"g","name":"frischer Schweinebauch ohne Knochen, mit Schwarte","hinweis":"nicht geräuchert, vom Metzger in 5 mm dicke Scheiben schneiden lassen"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":null,"einheit":"","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"}]},{"gruppe":"Kartoffeln","liste":[{"menge":1.2,"einheit":"kg","name":"kleine, festkochende Kartoffeln","hinweis":"neue Kartoffeln, wenn Saison ist"}]},{"gruppe":"Persillesovs","liste":[{"menge":40,"einheit":"g","name":"Butter","hinweis":""},{"menge":40,"einheit":"g","name":"Weizenmehl","hinweis":""},{"menge":500,"einheit":"ml","name":"Vollmilch","hinweis":"kalt oder zimmerwarm"},{"menge":1,"einheit":"Bund","name":"krause Petersilie","hinweis":"sehr fein gehackt, ca. 40 g"},{"menge":null,"einheit":"","name":"Salz, weißer Pfeffer, Muskat","hinweis":""}]}],"ausruestung":["große Pfanne","Topf für Kartoffeln","Topf für die Sauce","Schneebesen","Küchenpapier"],"schritte":[{"titel":"Schweinebauch vorbereiten und salzen","aktion":"vorbereiten","text":"Tupfe die Schweinebauchscheiben mit Küchenpapier trocken und schneide die Schwarte, falls noch dran, mehrmals ein, damit sie sich beim Braten nicht wölbt. Salze die Scheiben beidseitig mit etwas Salz und lasse sie 30 Minuten bei Zimmertemperatur ruhen; das Salz zieht Oberflächenfeuchtigkeit heraus und sorgt für eine knusprige Kruste. Tupfe die Scheiben danach noch einmal gründlich trocken. Pfeffere sie erst kurz vor dem Braten.","dauer":30,"tipp":""},{"titel":"Kartoffeln kochen","aktion":"kochen","text":"Wasche die Kartoffeln gründlich und koche sie in der Schale in Salzwasser 20 bis 25 Minuten, bis ein Messer ohne Widerstand hineingleitet. Gieße sie ab, lasse sie kurz ausdampfen und schäle sie bei Bedarf. Halte sie zugedeckt warm. Neue Kartoffeln mit dünner Schale kannst du ungeschält servieren, sie schmecken nach Erde und Süße.","dauer":22,"tipp":""},{"titel":"Schweinebauch langsam braten","aktion":"braten","text":"Lege die Scheiben in eine kalte, große Pfanne ohne zusätzliches Fett und erhitze sie langsam auf mittlere Hitze. Das Fett schmilzt allmählich aus und bräunt das Fleisch von selbst. Brate die Scheiben 8 bis 10 Minuten pro Seite, bis sie goldbraun und knusprig sind. Heiße Pfanne von Anfang an würde sie verbrennen, bevor das Fett ausgelaufen ist. Wende sie nur einmal.","dauer":18,"tipp":"Eine kalte Pfanne und mittlere Hitze sind das Geheimnis für knuspriges Fett."},{"titel":"Abtropfen lassen","aktion":"abseihen","text":"Hebe die gebratenen Scheiben auf ein mit Küchenpapier belegtes Blech oder Gitter und lasse überschüssiges Fett abtropfen. Halte sie im 80 °C warmen Ofen warm, bis die Sauce fertig ist. Pfeffere sie jetzt mit frisch gemahlenem schwarzem Pfeffer. Hebe etwas vom Bratfett für später auf, wenn du die Kartoffeln darin schwenken möchtest.","dauer":2,"tipp":""},{"titel":"Weiße Grundsauce kochen","aktion":"binden","text":"Schmilz die Butter in einem Topf bei mittlerer Hitze, streue das Mehl hinein und rühre 1 bis 2 Minuten, bis die Mischung blubbert, aber nicht braun wird. Gieße die Milch nach und nach unter ständigem Rühren mit dem Schneebesen dazu, damit keine Klümpchen entstehen. Lasse die Sauce unter Rühren 8 bis 10 Minuten leise köcheln, bis sie dicklich ist und keinen Mehlgeschmack mehr hat.","dauer":12,"tipp":""},{"titel":"Petersilie unterrühren und würzen","aktion":"abschmecken","text":"Rühre die fein gehackte Petersilie in die Sauce und lasse sie 1 bis 2 Minuten mitziehen, damit sie ihre Farbe behält. Schmecke mit Salz, weißem Pfeffer und einer Prise frisch geriebener Muskatnuss ab. Die Sauce soll sämig sein, hellgrün gesprenkelt und frisch nach Petersilie duften. Wenn sie zu dick wird, verdünne sie mit etwas Milch.","dauer":3,"tipp":"Petersilie erst am Ende zugeben, damit sie grün bleibt."},{"titel":"Kartoffeln fertig machen","aktion":"braten","text":"Schäle die gekochten Kartoffeln, falls gewünscht, und schwenke sie kurz in etwas Bratfett vom Schweinebauch oder in Butter, damit sie glänzen. Dieser Schritt ist traditionell nicht notwendig, gibt den Kartoffeln aber zusätzliches Aroma. Streue etwas Salz darüber. Halte sie warm, bis du anrichtest. Sie sollen nur durchgewärmt werden und leicht glänzen, nicht braun werden.","dauer":3,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile Schweinebauchscheiben und Kartoffeln auf vorgewärmten Tellern und übergieße alles großzügig mit Petersiliensauce. In Dänemark isst man dazu oft eingelegte Rote Bete oder einen Gurkensalat. Serviere sofort, damit das Fett knusprig bleibt. Ein kaltes dänisches Bier und ein Schnaps gehören dazu.","dauer":0,"tipp":""}],"profitipps":["Mit einer kalten Pfanne beginnen: Das Fett schmilzt langsam aus und macht die Scheiben knusprig.","Nicht geräucherten, frischen Schweinebauch verwenden; Räucherspeck schmeckt anders.","Frisch gehackte, krause Petersilie geben der Sauce ihre Farbe und ihr Aroma.","Béchamel gut köcheln, bis der Mehlgeschmack verschwunden ist.","Traditionell gibt es neue Kartoffeln; im Winter kann man mehlige Kartoffeln nehmen."],"varianten":["Mit Röstzwiebeln und Rote Bete als Beilage","Mit Ofen-Schweinebauch für weniger Fett","Äbleflæsk mit Apfel und Zwiebeln zu Weihnachten","Mit Senfsauce statt Petersiliensauce"],"beilagen":["Rote Bete","Gurkensalat","Röstzwiebeln"],"getraenk":"Kaltes dänisches Lager oder ein Aquavit.","koeche":[],"quellen":[{"titel":"Stegt flæsk – Wikipedia","url":"https://en.wikipedia.org/wiki/Stegt_fl%C3%A6sk"}],"bild":"teller","farben":["#c9863f","#f1e1b8","#5b8a3a"],"schlagworte":["Nationalgericht","Dänemark","Schweinebauch","Hausmannskost"],"vegetarisch_moeglich":false},{"id":"skandinavien-lohikeitto","name":"Lohikeitto","originalname":"Lohikeitto","kueche":"skandinavien","region":"Finnland","beliebtheit":65,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"suppe","kurz":"Cremige finnische Lachssuppe mit zarten Lachswürfeln, Kartoffeln, Karotten, Lauch und viel frischem Dill – wärmend und ganz einfach.","hintergrund":"Lohikeitto, auf Schwedisch laxsoppa, ist eine cremige Lachssuppe, die aus Finnland stammt und im gesamten Norden Europas verbreitet ist. Zutaten sind Lachsfilet, Kartoffeln, Karotten und Lauch, gewürzt mit frischem Dill, Piment, Salz und Pfeffer. Die Suppe wird entweder mit Sahne oder mit Vollmilch zubereitet; in beiden Fällen erinnert sie an eine Chowder. Sie wird heiß serviert, meist mit dunklem Roggenbrot, und gehört zu den beliebtesten Gerichten in finnischen Gaststätten und Markthallen.","portionen":4,"zeit":{"vorbereitung":25,"garen":30,"ruhen":5},"schwierigkeit":1,"zutaten":[{"gruppe":"Suppe","liste":[{"menge":500,"einheit":"g","name":"Lachsfilet, ohne Haut und Gräten","hinweis":"in 3 cm große Würfel geschnitten; frisch oder aufgetaut"},{"menge":500,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"in 1,5 cm große Würfel geschnitten"},{"menge":2,"einheit":"Stück","name":"Karotten","hinweis":"in dünne Scheiben geschnitten"},{"menge":1,"einheit":"Stange","name":"Lauch","hinweis":"in feine Ringe geschnitten, nur Weißes und Hellgrünes"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"EL","name":"Butter","hinweis":""},{"menge":800,"einheit":"ml","name":"Fisch- oder Gemüsefond","hinweis":"oder Wasser mit 1 TL Salz"},{"menge":6,"einheit":"Stück","name":"ganze Pimentkörner (Nelkenpfeffer)","hinweis":""},{"menge":200,"einheit":"ml","name":"Sahne","hinweis":"oder 400 ml Vollmilch für leichtere Version"},{"menge":1,"einheit":"Bund","name":"Dill","hinweis":"fein gehackt"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":""}]}],"ausruestung":["großer Topf mit Deckel","Schaumlöffel","scharfes Messer"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Schäle Kartoffeln und Karotten und schneide die Kartoffeln in etwa 1,5 cm große Würfel, die Karotten in dünne Scheiben. Putze den Lauch, halbiere ihn der Länge nach, wasche ihn gründlich unter fließendem Wasser, weil sich zwischen den Schichten Erde versteckt, und schneide ihn in feine Ringe. Würfle die Zwiebel fein. Tupfe den Lachs trocken, prüfe ihn auf Gräten und schneide ihn in 3 cm große Würfel. Hacke den Dill fein.","dauer":0,"tipp":""},{"titel":"Gemüse anschwitzen","aktion":"anbraten","text":"Schmilz die Butter in einem großen Topf bei mittlerer Hitze, gib Zwiebel und Lauch hinein und dünste sie 4 bis 5 Minuten unter Rühren, bis sie weich und glasig sind, ohne Farbe zu nehmen. Das sanfte Anschwitzen gibt der Suppe eine süße Grundlage. Füge die Karottenscheiben hinzu und rühre eine weitere Minute.","dauer":6,"tipp":""},{"titel":"Kartoffeln und Fond zugeben","aktion":"koecheln","text":"Gib die Kartoffelwürfel und die Pimentkörner in den Topf und gieße den Fond dazu, bis alles knapp bedeckt ist. Bringe die Suppe zum Kochen, reduziere die Hitze und lasse sie zugedeckt 12 bis 15 Minuten leise köcheln, bis die Kartoffeln fast gar sind. Sie sollen sich mit einem Messer leicht einstechen lassen, aber noch nicht zerfallen. Schäume bei Bedarf auf.","dauer":14,"tipp":""},{"titel":"Sahne einrühren","aktion":"mischen","text":"Gieße die Sahne in den Topf und rühre sie unter. Erhitze die Suppe vorsichtig bis kurz unter den Siedepunkt, ohne sie aufkochen zu lassen, denn kochende Sahne kann flocken. Zerdrücke einige Kartoffelwürfel an der Topfwand, damit die Suppe leicht sämig wird. Schmecke mit Salz und weißem Pfeffer ab. Die Suppe sollte danach einen zarten, hellorangen Schimmer haben und angenehm nach Fisch und Dill duften.","dauer":3,"tipp":""},{"titel":"Lachs hineingeben und gar ziehen lassen","aktion":"koecheln","text":"Schalte die Hitze auf die niedrigste Stufe und gib die Lachswürfel in die heiße Suppe. Lasse sie 4 bis 5 Minuten zugedeckt ziehen, bis der Lachs gerade eben gar und leicht rosa ist, nicht durchgekocht. Zu langes Garen macht Lachs trocken und bröselig. Bewege die Würfel kaum, damit sie ganz bleiben. Sie sind fertig, wenn sie sich beim Anstechen leicht in Lamellen teilen.","dauer":5,"tipp":"Lachs gart in der heißen Suppe nach: Lieber früher abschalten als zu spät."},{"titel":"Dill unterziehen und abschmecken","aktion":"abschmecken","text":"Nimm den Topf vom Herd und rühre den Großteil des Dills vorsichtig unter. Behalte etwas zum Garnieren zurück. Entferne die Pimentkörner, falls du sie findest. Schmecke mit Salz, weißem Pfeffer und einem Spritzer Zitronensaft ab; die Säure bringt die Aromen von Lachs und Dill zum Leuchten. Die Suppe soll cremig, frisch und würzig duften.","dauer":2,"tipp":""},{"titel":"Kurz ruhen lassen","aktion":"ruhen","text":"Lasse die Suppe mit aufgelegtem Deckel 5 Minuten ruhen, damit sich die Aromen verbinden und der Lachs vollständig durchgart. In Finnland schmeckt Lohikeitto am nächsten Tag oft noch besser, doch der Lachs wird dann fester. Beim Aufwärmen sanft erhitzen und nicht kochen lassen. Der Dill gibt in dieser Zeit sein Aroma an die Sahne ab, und die Kartoffeln saugen etwas Würze auf. Probiere vor dem Servieren noch einmal und würze bei Bedarf nach.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schöpfe die Suppe in vorgewärmte tiefe Teller, verteile Lachswürfel und Kartoffeln gleichmäßig und garniere mit frischem Dill und etwas schwarzem Pfeffer. Serviere dazu dunkles Roggenbrot mit Butter, das ist die klassische Begleitung. Ein Spritzer Zitrone am Tisch bringt Frische. Die Suppe sollte sehr heiß serviert werden.","dauer":0,"tipp":""}],"profitipps":["Lachs erst ganz zum Schluss zugeben und nur ziehen lassen, nicht kochen.","Piment (Nelkenpfeffer) ist das typische Gewürz; es gibt der Suppe eine warme Note.","Viel frischer Dill ist wichtig; getrockneter ersetzt ihn nicht.","Mit Vollmilch statt Sahne wird die Suppe leichter, mit Sahne üppiger.","Beim Aufwärmen nicht aufkochen lassen, damit die Sahne nicht flockt."],"varianten":["Mit Milch statt Sahne als leichte Version","Mit geräuchertem Lachs für kräftigeren Geschmack","Mit Kabeljau oder Seelachs statt Lachs","Mit einem Löffel Meerrettich für Schärfe"],"beilagen":["Roggenbrot","Butter","Zitronenspalten"],"getraenk":"Trockener Weißwein, kaltes Bier oder Wasser mit Zitrone.","koeche":[],"quellen":[{"titel":"Lohikeitto – Wikipedia","url":"https://en.wikipedia.org/wiki/Lohikeitto"}],"bild":"suppe","farben":["#e8a56a","#f6e6c4","#5b8a4a"],"schlagworte":["Finnland","Suppe","Lachs","Dill"],"vegetarisch_moeglich":false},{"id":"skandinavien-skandinavisches-fruehstueck","name":"Skandinavisches Frühstück mit Knäckebrot, Hering und Eiern","originalname":"Morgenmad / Frukost","kueche":"skandinavien","region":"Dänemark, Schweden, Norwegen","beliebtheit":62,"hauptkategorie":"fisch","fischsorte":"fisch","fleischsorte":"","gang":"fruehstueck","kurz":"Knäckebrot und dunkles Roggenbrot mit Butter, eingelegtem Hering, Ei, Käse, Gurke und Dill – ein frisches, herzhaftes Frühstück vom kalten Buffet.","hintergrund":"Das skandinavische Frühstück ist ein kaltes Brotfrühstück, das sich oft am Buffet (Frukostbuffé) orientiert: Es gibt Roggenbrot, Knäckebrot, Butter, mehrere Käsesorten, gekochte Eier, Gurke, Tomate und eingelegten Hering, daneben Joghurt, Müsli und Obst. Hering gehört in Dänemark, Schweden und Norwegen traditionell zum Brotbelag, in Senf-, Curry-, Zwiebel- oder Dillmarinade. Gekochte Eier werden in Scheiben auf das Brot gelegt, Dill und Zwiebeln verfeinern. Das Ganze wird mit starkem Kaffee getrunken. Typisch ist die offene Brotscheibe, bei der Belag sichtbar und sorgfältig geschichtet ist. Die Zutaten sind überwiegend im Supermarkt erhältlich.","portionen":4,"zeit":{"vorbereitung":25,"garen":10,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Brot und Basis","liste":[{"menge":8,"einheit":"Scheibe","name":"Roggenbrot oder Vollkornbrot","hinweis":"dunkles, dicht gebackenes Brot, ersatzweise Pumpernickel"},{"menge":8,"einheit":"Stück","name":"Knäckebrot","hinweis":"Roggenknäcke"},{"menge":100,"einheit":"g","name":"gesalzene Butter","hinweis":"weich"}]},{"gruppe":"Belag","liste":[{"menge":250,"einheit":"g","name":"eingelegter Hering (Matjes oder Senfhering)","hinweis":"aus dem Kühlregal oder Glas"},{"menge":4,"einheit":"Stück","name":"Eier (Größe M)","hinweis":"für hartgekochte Eier"},{"menge":150,"einheit":"g","name":"Käse","hinweis":"z. B. Jarlsberg, Havarti oder Västerbotten; in Scheiben gehobelt"},{"menge":1,"einheit":"Stück","name":"Salatgurke","hinweis":"in dünnen Scheiben"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"in Scheiben"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in dünnen Ringen"},{"menge":1,"einheit":"Bund","name":"Dill","hinweis":"frisch"},{"menge":200,"einheit":"g","name":"Skyr oder Naturjoghurt","hinweis":"optional, mit Beeren"}]}],"ausruestung":["Topf","Käsehobel","Brettchen und scharfes Messer","Servierplatten"],"schritte":[{"titel":"Alles vorbereiten","aktion":"vorbereiten","text":"Nimm Hering, Käse und Butter früh aus dem Kühlschrank, denn leicht temperiert schmecken sie besser. Wasche Gurke, Tomaten und Dill, schneide Gurke und Tomaten in dünne Scheiben und die Zwiebel in feine Ringe. Hacke den Dill grob, ohne die dicken Stiele. Hobele den Käse in dünne Scheiben. Stelle Platten und Schalen bereit, denn das skandinavische Frühstück wirkt als Buffet am besten, wenn alles übersichtlich bereitliegt.","dauer":0,"tipp":"Hering gut abtropfen lassen, damit das Brot nicht durchweicht."},{"titel":"Eier hart kochen","aktion":"kochen","text":"Bringe in einem Topf Wasser zum Kochen, lege die Eier vorsichtig hinein und koche sie 8 bis 9 Minuten, bis das Eigelb fest, aber noch cremig und leuchtend gelb ist. Schrecke sie sofort in Eiswasser ab, damit sie nicht nachgaren und sich leichter pellen lassen. Pelle die Eier und schneide sie mit einem Eierschneider oder Messer in gleichmäßige Scheiben. Ein graugrüner Rand am Eigelb zeigt, dass sie zu lange gekocht wurden.","dauer":10,"tipp":""},{"titel":"Brotscheiben buttern","aktion":"garnieren","text":"Bestreiche die Roggenbrotscheiben dünn bis zum Rand mit weicher Butter. Die Butter verhindert, dass der Belag das Brot durchfeuchtet, und gibt Geschmack. Belege einen Teil des Brotes mit Käse und Gurke, einen Teil mit Ei und Tomate. Das Roggenbrot hat einen kräftigen, leicht säuerlichen Geschmack, der gut zu Hering und Käse passt. Das Knäckebrot bestreichst du erst direkt vor dem Essen, damit es knusprig bleibt.","dauer":0,"tipp":""},{"titel":"Hering anrichten","aktion":"anrichten","text":"Lege Heringsfilets auf gebutterte Roggenbrotscheiben, bestreue sie mit roten Zwiebelringen und frischem Dill. Senfhering schmeckt süß-würzig, Matjes mild-salzig, Curryhering fruchtig-scharf. Verteile den Hering nicht zu dick, damit das Brot noch schmeckbar bleibt. Hering ist ein klassischer Frühstücksbelag in Dänemark und Schweden, oft mit hartem Ei und Zwiebeln kombiniert.","dauer":0,"tipp":"Matjes aus dem Kühlregal ist mild und ideal für den Einstieg."},{"titel":"Eier und Käse belegen","aktion":"schichten","text":"Lege Eierscheiben fächerförmig auf gebutterte Brotscheiben, würze mit etwas Salz, Pfeffer und frischem Dill. Auf anderen Scheiben schichtest du Käse, Gurke und Tomate. Das Ei kann auch mit Kaviar (Kalles Kaviar) oder Räucherlachs kombiniert werden. Jede Scheibe soll ansprechend aussehen, mit sichtbaren Schichten und frischen Kräutern obenauf, wie es der skandinavischen Tradition entspricht.","dauer":0,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Stelle alle Brote, Knäckebrot, Platten mit Hering, Käse, Eiern und Gemüse sowie Butter auf den Tisch. Serviere dazu Skyr oder Joghurt mit Beeren und starken Filterkaffee. Jeder belegt sich sein Brot selbst, genau wie am Hotelbuffet in Skandinavien. Die Kombination aus salzig, säuerlich und frisch macht das Frühstück leicht und trotzdem sättigend.","dauer":0,"tipp":""}],"profitipps":["Dunkles Roggenbrot passt am besten zu Hering und Käse.","Eier 8 bis 9 Minuten kochen und sofort abschrecken.","Knäckebrot erst kurz vor dem Essen belegen, damit es knusprig bleibt.","Frischer Dill ist das typische Kraut der Region.","Hering in verschiedenen Marinaden anbieten (Senf, Curry, Zwiebel)."],"varianten":["Mit Räucherlachs und Frischkäse.","Dänisches Smørrebrød als offener Belag mit Remoulade.","Schwedisch mit Kalles Kaviar auf Ei.","Mit Skyr, Müsli und Beeren als süßer Teil."],"beilagen":["Skyr oder Joghurt","Obst","Müsli","Kaffee"],"getraenk":"Starker Filterkaffee, Tee oder Milch","koeche":[],"quellen":[{"titel":"Wikipedia: Nordic cuisine","url":"https://en.wikipedia.org/wiki/Nordic_cuisine"},{"titel":"Wikipedia: Smørrebrød","url":"https://en.wikipedia.org/wiki/Sm%C3%B8rrebr%C3%B8d"}],"bild":"sandwich","farben":["#7a5a3a","#e8d9b0","#4f7a5a"],"schlagworte":["Skandinavien","Frühstück","Hering","Knäckebrot","Buffet"],"vegetarisch_moeglich":false},{"id":"skandinavien-faerikaal","name":"Fårikål","originalname":"Fårikål","kueche":"skandinavien","region":"Norwegen","beliebtheit":62,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Lammfleisch am Knochen und Weißkohl in Schichten, mit ganzem Pfeffer stundenlang sanft geschmort – Norwegens Herbst-Nationalgericht in seiner einfachsten Form.","hintergrund":"Fårikål bedeutet Schaf im Kohl und besteht aus Hammel oder Lamm am Knochen, Weißkohl, ganzen schwarzen Pfefferkörnern und gelegentlich etwas Weizenmehl. Das Gericht wird in Schichten im Topf mehrere Stunden gegart und traditionell mit in der Schale gekochten Kartoffeln gegessen. Es wird vor allem im frühen Herbst gekocht: Über 70 Prozent der Norweger essen es in dieser Zeit mindestens einmal. In den 1970er-Jahren wählte die Radiosendung Nitimen es zum norwegischen Nationalgericht, 2014 wurde es nach einer von Minister Sylvi Listhaug angestoßenen Abstimmung erneut bestätigt. Am letzten Donnerstag im September feiert man den Fårikålens festdag. Der Name ist aus dem dänischen gaas i hvidkaal (Gans in Weißkohl) abgeleitet.","portionen":6,"zeit":{"vorbereitung":25,"garen":170,"ruhen":20},"schwierigkeit":1,"zutaten":[{"gruppe":"Fårikål","liste":[{"menge":1.5,"einheit":"kg","name":"Lamm- oder Hammelfleisch mit Knochen","hinweis":"Schulter, Brust, Hals oder Haxe, in 6 bis 8 cm große Stücke gehackt; Metzger bitten"},{"menge":1.5,"einheit":"kg","name":"Weißkohl","hinweis":"1 mittelgroßer Kopf, in 5 cm große Spalten oder Stücke geschnitten, Strunk teilweise belassen"},{"menge":1,"einheit":"EL","name":"ganze schwarze Pfefferkörner","hinweis":"nicht mahlen; sie geben langsam Schärfe ab"},{"menge":1.5,"einheit":"EL","name":"grobes Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Weizenmehl","hinweis":"optional, zum leichten Binden der Brühe"},{"menge":300,"einheit":"ml","name":"Wasser","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":1.2,"einheit":"kg","name":"kleine, festkochende Kartoffeln","hinweis":"in der Schale gekocht"},{"menge":100,"einheit":"g","name":"Preiselbeeren","hinweis":"optional"}]}],"ausruestung":["großer, schwerer Schmortopf mit gut schließendem Deckel (5–6 l)","Schaumlöffel","scharfes Messer","Topf für die Kartoffeln"],"schritte":[{"titel":"Fleisch und Kohl vorbereiten","aktion":"schneiden","text":"Lasse das Fleisch vom Metzger in 6 bis 8 cm große Stücke mit Knochen hacken; Knochen und Fett geben der Brühe Körper und Geschmack. Spüle es kurz ab und tupfe es trocken. Entferne vom Kohlkopf die äußeren welken Blätter, halbiere ihn, viertele die Hälften und schneide sie in etwa 5 cm große Spalten. Lass einen Teil des Strunks dran, damit die Stücke zusammenhalten. Alles bereit stellen: Das Gericht erfordert nur Schichten und Geduld.","dauer":0,"tipp":""},{"titel":"Fleisch kurz blanchieren","aktion":"blanchieren","text":"Gib das Fleisch in einen großen Topf, bedecke es mit kaltem Wasser und bringe es langsam zum Kochen. Lasse es 3 bis 5 Minuten sieden, bis grauer Schaum aufsteigt, und gieße alles in ein Sieb ab. Spüle das Fleisch kalt ab und wasche den Topf aus. Dieser Schritt ist nicht traditionell vorgeschrieben, macht aber die Brühe klarer und milder und entfernt Blutreste.","dauer":8,"tipp":"Wer das rustikale Original bevorzugt, kann diesen Schritt weglassen."},{"titel":"Im Wechsel schichten","aktion":"schichten","text":"Lege den Boden des Topfes mit einer Schicht Kohlspalten aus, setze Fleischstücke darauf, streue eine Prise Salz, einige Pfefferkörner und etwas Mehl darüber. Wiederhole die Schichten, bis alles verbraucht ist, und schließe mit Kohl oben ab. Kohl und Fleisch sollten sich abwechseln, damit der Kohlsaft das Fleisch beim Garen durchzieht. Drücke nicht fest, es bleibt Luft zwischen den Schichten.","dauer":10,"tipp":""},{"titel":"Wasser angießen und aufkochen","aktion":"kochen","text":"Gieße etwa 300 ml Wasser in den Topf. Das ist wenig, denn der Kohl gibt beim Garen viel Flüssigkeit ab und der Eintopf soll nicht schwimmen. Setze den Deckel auf und bringe alles bei mittlerer Hitze zum Kochen. Sobald es dampft und leise blubbert, reduziere die Hitze auf die niedrigste Stufe. Rühre nicht um, sonst zerfallen Fleisch und Kohl und die Schichten vermischen sich.","dauer":10,"tipp":""},{"titel":"Langsam schmoren","aktion":"schmoren","text":"Lasse den Fårikål 2 bis 2,5 Stunden bei kleinster Hitze zugedeckt garen. Der Kohl wird weich, süßlich und fast transparent, das Fleisch löst sich vom Knochen, und die Brühe wird würzig und leicht scharf vom Pfeffer. Hebe den Deckel höchstens einmal, um die Flüssigkeit zu prüfen: Wenn der Boden trocken wird, gib einen Schuss Wasser dazu. Schütteln des Topfes statt Rühren verteilt die Wärme.","dauer":140,"tipp":"Lange und sanft ist das Prinzip: je älter das Fleisch, desto länger die Garzeit."},{"titel":"Kartoffeln in der Schale kochen","aktion":"kochen","text":"Wasche die Kartoffeln und koche sie in der Schale in Salzwasser etwa 20 bis 25 Minuten, bis sie weich sind und sich mühelos anstechen lassen. Gieße sie ab und lasse sie kurz ausdampfen. In Norwegen schält man sie am Tisch. Starte etwa 30 Minuten vor Ende der Garzeit des Fårikål, damit alles zur selben Zeit fertig ist.","dauer":22,"tipp":""},{"titel":"Abschmecken und Fett abschöpfen","aktion":"abschmecken","text":"Hebe den Deckel ab und prüfe mit einer Gabel, ob das Fleisch zart ist und sich vom Knochen löst. Schöpfe überschüssiges Fett mit einem Löffel von der Oberfläche der Brühe ab. Probiere die Brühe und salze bei Bedarf nach. Die ganzen Pfefferkörner brennen leicht im Mund, wenn du darauf beißt, sie sind aber Teil des Gerichts und werden einfach am Tellerrand abgelegt.","dauer":5,"tipp":""},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse ihn mit aufgelegtem Deckel 15 bis 20 Minuten ruhen. Die Brühe verbindet sich, der Kohl zieht weiter durch, und das Gericht kühlt auf Essenstemperatur ab. Wie bei vielen Eintöpfen schmeckt Fårikål am nächsten Tag aufgewärmt noch besser, weil sich die Aromen vollständig verbunden haben.","dauer":20,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schöpfe Fleisch, Kohl und Brühe in tiefe, vorgewärmte Teller und reiche die heißen Kartoffeln separat dazu. Die Tischgäste schälen und zerdrücken sie in der Brühe. Dazu passen Preiselbeeren und Flatbrød. Serviere traditionell mit einem kräftigen Pils oder Rotwein, und zelebriere damit den norwegischen Fårikål-Festtag Ende September.","dauer":0,"tipp":""}],"profitipps":["Fleisch am Knochen verwenden; ohne Knochen fehlt Körper und Geschmack.","Ganze Pfefferkörner statt gemahlenem Pfeffer geben langsam Schärfe ab und trüben die Brühe nicht.","Nicht rühren und auf kleinster Stufe garen: So bleiben die Schichten intakt.","Wenig Wasser genügt, der Kohl gibt viel Saft ab.","Am nächsten Tag aufgewärmt schmeckt Fårikål meist noch besser."],"varianten":["Mit Hammel statt Lamm für kräftigeren Geschmack","Mit Möhren oder Steckrüben als Ergänzung","Mit Rindfleisch statt Lamm","Fårikål mit Flatbrød und Preiselbeeren als Festtagsgericht"],"beilagen":["Kartoffeln in der Schale","Flatbrød","Preiselbeeren"],"getraenk":"Norwegisches Pils, Rotwein oder Aquavit.","koeche":[{"name":"Magnus Nilsson","bezug":"The Nordic Cookbook (Phaidon, 2015) dokumentiert die traditionelle Alltagsküche aller nordischen Länder und umfasst damit auch norwegische Klassiker.","quelle":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"quellen":[{"titel":"Fårikål – Wikipedia","url":"https://en.wikipedia.org/wiki/F%C3%A5rik%C3%A5l"},{"titel":"Magnus Nilsson – Wikipedia","url":"https://en.wikipedia.org/wiki/Magnus_Nilsson_(chef)"}],"bild":"eintopf","farben":["#c7b57a","#e9e2c0","#6b7a3a"],"schlagworte":["Norwegen","Nationalgericht","Herbst","Eintopf"],"vegetarisch_moeglich":false},{"id":"skandinavien-roedgroed-med-floede","name":"Rødgrød med fløde","originalname":"Rødgrød med fløde","kueche":"skandinavien","region":"Dänemark","beliebtheit":60,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Leuchtend rote Beerengrütze, mit Stärke gebunden, kalt mit kühler Sahne serviert – und eine Aussprache-Prüfung für jeden Dänemark-Besucher.","hintergrund":"Rødgrød bedeutet roter Brei oder rote Grütze. Das Dessert ist in Dänemark und Norddeutschland als rote Grütze verbreitet. Ursprünglich wurde es mit Grütze oder Grieß gebunden, heute ist Kartoffelstärke das Standardbindemittel. Die Beeren bestimmen den Geschmack: Rote Johannisbeeren sind unverzichtbar, schwarze Johannisbeeren, Himbeeren, Erdbeeren und entsteinte Kirschen kommen gern dazu. Serviert wird es warm oder kalt mit Milch, Vanillesahne, Schlagsahne oder Eis. Berühmt ist das Wortspiel rødgrød med fløde: Seit den frühen 1900er-Jahren gilt der Satz als Aussprache-Test, an dem Nicht-Dänen scheitern.","portionen":6,"zeit":{"vorbereitung":20,"garen":15,"ruhen":180},"schwierigkeit":1,"zutaten":[{"gruppe":"Rødgrød","liste":[{"menge":300,"einheit":"g","name":"rote Johannisbeeren","hinweis":"frisch oder tiefgekühlt; Stiele entfernt"},{"menge":300,"einheit":"g","name":"Himbeeren","hinweis":"frisch oder tiefgekühlt"},{"menge":300,"einheit":"g","name":"Erdbeeren","hinweis":"geputzt und halbiert; oder entsteinte Kirschen"},{"menge":300,"einheit":"ml","name":"Wasser","hinweis":"oder halb Wasser, halb Beerensaft"},{"menge":120,"einheit":"g","name":"Zucker","hinweis":"je nach Süße der Früchte 100 bis 150 g"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":1,"einheit":"Stück","name":"Vanilleschote","hinweis":"optional, Mark ausgekratzt"},{"menge":40,"einheit":"g","name":"Kartoffelstärke","hinweis":"in 80 ml kaltem Wasser angerührt"}]},{"gruppe":"Zum Servieren","liste":[{"menge":300,"einheit":"ml","name":"kalte Sahne (fløde)","hinweis":"flüssig oder leicht aufgeschlagen"},{"menge":1,"einheit":"EL","name":"Mandelblättchen","hinweis":"optional, geröstet"}]}],"ausruestung":["mittelgroßer Topf","Schneebesen","Sieb","Gläser oder Schalen","Frischhaltefolie"],"schritte":[{"titel":"Beeren putzen und bereitstellen","aktion":"vorbereiten","text":"Befreie die Johannisbeeren von den Rispen, am einfachsten streifst du sie mit einer Gabel von den Stielen. Putze Erdbeeren und Himbeeren, halbiere größere Früchte und lege tiefgekühlte Beeren ungetaut bereit. Wiege Zucker und Stärke ab. Rühre die Stärke mit 80 ml kaltem Wasser glatt und stelle sie neben den Herd; Stärke löst sich nur in kaltem Wasser ohne Klümpchen auf.","dauer":0,"tipp":""},{"titel":"Beeren aufkochen","aktion":"kochen","text":"Gib alle Beeren mit dem Wasser, dem Zucker, dem Zitronensaft und dem Vanillemark in einen Topf und bringe sie bei mittlerer Hitze zum Kochen. Lasse sie 5 bis 8 Minuten leise köcheln, bis die Früchte aufplatzen, viel Saft abgeben und die Johannisbeeren glasig werden. Rühre vorsichtig um. Die Beeren sollen weich, aber nicht zu Mus zerkocht sein, denn die Struktur gehört zur Rødgrød.","dauer":8,"tipp":""},{"titel":"Fruchtsaft abschmecken","aktion":"abschmecken","text":"Probiere die Fruchtmasse: Sie soll fruchtig, süß und leicht säuerlich schmecken. Sind die Beeren sehr sauer, gib einen weiteren Esslöffel Zucker dazu; ist sie zu süß, hilft ein Spritzer Zitronensaft. Die Süße gleicht später die kalte, ungesüßte Sahne aus. Entferne die Vanilleschote. Wer eine glatte Grütze möchte, kann die Masse jetzt durch ein Sieb streichen, doch die Stücke sind traditionell.","dauer":2,"tipp":""},{"titel":"Mit Stärke binden","aktion":"binden","text":"Rühre die angerührte Stärke noch einmal durch, da sie sich am Boden absetzt, und gieße sie unter ständigem Rühren in die heiße Fruchtmasse. Lasse alles unter Rühren 1 bis 2 Minuten aufkochen, bis die Masse dick, glänzend und durchscheinend wird. Sie soll nicht zu lange kochen, sonst verliert die Stärke ihre Bindekraft. Nimm den Topf sofort vom Herd. Beim Abkühlen wird die Grütze noch fester.","dauer":3,"tipp":"Stärke immer in die heiße Flüssigkeit rühren, nie umgekehrt: so entstehen keine Klumpen."},{"titel":"Abfüllen und abdecken","aktion":"kuehlen","text":"Fülle die heiße Grütze in eine große Schüssel oder in einzelne Gläser. Bestreue die Oberfläche mit etwas Zucker oder lege Frischhaltefolie direkt darauf, damit sich keine Haut bildet. Lass sie bei Zimmertemperatur 30 Minuten abkühlen. Die Farbe soll leuchtend rot und das Aroma intensiv nach frischen Beeren duften.","dauer":30,"tipp":""},{"titel":"Kühl stellen","aktion":"kuehlen","text":"Stelle die Rødgrød mindestens 3 Stunden in den Kühlschrank, bis sie vollständig kalt und fest ist. In dieser Zeit verbinden sich die Aromen, und die Stärke gibt der Grütze ihre endgültige, weich-geleeartige Konsistenz. Du kannst sie bis zu 3 Tage im Voraus zubereiten; sie schmeckt am zweiten Tag oft noch besser.","dauer":180,"tipp":""},{"titel":"Mit kalter Sahne servieren","aktion":"anrichten","text":"Verteile die kalte Rødgrød in Schalen oder Gläser und gieße kalte, flüssige Sahne darüber oder reiche sie in einem Kännchen separat. In Dänemark isst man sie traditionell mit flüssiger Sahne, aber auch Vanillesauce, Schlagsahne oder Vanilleeis passen. Streue optional geröstete Mandelblättchen darüber. Wer sich traut, sagt dazu den dänischen Zungenbrecher rødgrød med fløde.","dauer":0,"tipp":""}],"profitipps":["Rote Johannisbeeren sind unverzichtbar, sie geben Säure und Farbe.","Stärke immer kalt anrühren und unter Rühren in die heiße Fruchtmasse geben.","Nach dem Binden nur ein bis zwei Minuten kochen, danach sofort vom Herd nehmen.","Frischhaltefolie direkt auf die Oberfläche legen, sonst bildet sich eine Haut.","Gut gekühlt und mit eiskalter Sahne serviert schmeckt sie am besten."],"varianten":["Deutsche Rote Grütze mit Vanillesauce","Mit Kirschen und schwarzen Johannisbeeren","Mit Vanilleeis statt Sahne","Als Rhabarber-Grütze im Frühling (Rabarbergrød)"],"beilagen":["kalte Sahne","Vanillesauce","Vanilleeis","Mandelblättchen"],"getraenk":"Kaffee oder ein süßer Dessertwein.","koeche":[],"quellen":[{"titel":"Rødgrød – Wikipedia","url":"https://en.wikipedia.org/wiki/R%C3%B8dgr%C3%B8d"}],"bild":"dessert","farben":["#b0182f","#e84a5f","#f6efe0"],"schlagworte":["Dänemark","Beeren","Sommer","Dessert"],"vegetarisch_moeglich":true},{"id":"skandinavien-dill-lachs-samuelsson","name":"Dill-gewürzter Lachs nach Art von Marcus Samuelsson","originalname":"Dill-Spiced Salmon","kueche":"skandinavien","region":"Schweden (Kindheitsgericht)","beliebtheit":58,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Lachsfilets mit Dill, Koriander, Kreuzkümmel und Senfpaste, in Butter und Zitrone gebraten – cremig-zart im Kern, knusprig auf der Haut.","hintergrund":"Samuelsson beschreibt dieses Gericht in „Marcus Off Duty: The Recipes I Cook at Home“ (2014) als das schwedische Gegenstück zum amerikanischen Hackbraten: ein Alltagsessen aus seiner Kindheit. Die schwedische Seite erkennt man an Dill und Senf, die Würze aus Koriander und Kreuzkümmel zeigt seine Neugier auf andere Küchen. Der Lachs wird in einer Pfanne mit Butter und Zitrone gebraten, indem man ständig mit dem Bratfett übergießt. Laut Samuelsson wird das Fleisch dadurch cremig und fast puddingartig. Dies ist eine Heimküchen-Fassung der veröffentlichten Rezeptur in metrischen Einheiten.","portionen":4,"zeit":{"vorbereitung":15,"garen":10,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Gewürzmischung und Paste","liste":[{"menge":2,"einheit":"EL","name":"Dill","hinweis":"frisch, gehackt, plus mehr zum Garnieren"},{"menge":1.5,"einheit":"EL","name":"mildes Chilipulver","hinweis":"„chile powder“ ist in den USA eine milde Mischung; ersatzweise geräuchertes Paprikapulver mit einer Messerspitze Cayenne"},{"menge":1,"einheit":"EL","name":"Koriandersamen","hinweis":"fein gemahlen"},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":"fein gemahlen"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"},{"menge":2,"einheit":"EL","name":"Dijon-Senf"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"}]},{"gruppe":"Lachs","liste":[{"menge":4,"einheit":"Stück","name":"Lachsfilets mit Haut, je etwa 170 g","hinweis":"möglichst Sushi-Qualität, jedes Filet quer halbiert"},{"menge":4,"einheit":"EL","name":"Butter","hinweis":"ca. 60 g, aufgeteilt"},{"menge":2,"einheit":"EL","name":"Olivenöl"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"in Spalten, plus mehr zum Servieren"}]}],"ausruestung":["große Pfanne","Löffel zum Übergießen","kleine Schüssel","Pfannenwender"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Hacke den Dill fein, mahle Koriander- und Kreuzkümmelsamen in einem Mörser oder einer Gewürzmühle fein und halbiere die Lachsfilets quer, sodass 8 kleinere Stücke entstehen. Tupfe die Filets auf beiden Seiten trocken, damit die Haut später knusprig wird, und prüfe mit den Fingern, ob noch Gräten in der Mitte sitzen; ziehe sie mit einer Pinzette heraus. Schneide die Zitrone in Spalten und stelle alles bereit.","dauer":0,"tipp":"Lass den Lachs 15 Minuten bei Zimmertemperatur liegen, dann gart er gleichmäßiger."},{"titel":"Gewürzmischung anrühren","aktion":"mischen","text":"Vermische in einer Schüssel Dill, Chilipulver, Koriander, Kreuzkümmel, eine großzügige Prise Salz und Pfeffer. Teile die Mischung in zwei Hälften: Eine bleibt trocken zum Würzen des Lachses, die andere wird gleich mit dem Senf zur Paste. Die Mischung duftet nach Dill, Zitrus und Wärme; Koriander sollte frisch gemahlen sein, weil er sonst fade schmeckt.","dauer":0,"tipp":""},{"titel":"Senfpaste herstellen","aktion":"mischen","text":"Gib den Senf zur halben Gewürzmischung und rühre alles zu einer Paste. Erhitze einen Esslöffel Butter in einer großen Pfanne und röste den Knoblauch ein bis zwei Minuten, bis er duftet und leicht gebräunt ist, nicht verbrannt. Rühre ihn in die Senfpaste. Die Paste kommt später auf die Hautseite des Lachses und bildet eine würzige Kruste.","dauer":3,"tipp":""},{"titel":"Lachs würzen","aktion":"vorbereiten","text":"Würze die Lachsstücke auf beiden Seiten mit Salz und der trockenen Hälfte der Gewürzmischung. Drücke sie leicht an, damit sie haftet. Wische die Pfanne aus, damit nichts anbrennt; der Knoblauch ist ja schon in der Paste. Die Gewürze sollen eine dünne, gleichmäßige Hülle bilden, auch an den Schnittkanten; lass die gewürzten Stücke aber nicht länger als ein paar Minuten liegen, weil das Salz sonst Wasser aus dem Fisch zieht und die Haut weich wird.","dauer":0,"tipp":""},{"titel":"Pfanne vorbereiten","aktion":"anbraten","text":"Schmelze einen Esslöffel Butter zusammen mit dem Olivenöl in der Pfanne bei mittlerer bis hoher Hitze. Das Fett ist heiß genug, wenn es schimmert und leicht zu schäumen beginnt. Die Butter soll nicht braun werden; das Öl erhöht die Hitzestabilität. Halte die Zitronenspalten und einen breiten Pfannenwender bereit, denn der Lachs soll später ohne Zögern in die Pfanne wandern. Ist das Fett zu kalt, klebt die Haut an, ist es zu heiß, raucht und verbrennt die Butter; reguliere die Hitze, bis sie sanft brutzelt.","dauer":1,"tipp":""},{"titel":"Auf der Hautseite braten","aktion":"braten","text":"Lege die Filets mit der Hautseite nach unten in die Pfanne, gib einen weiteren Esslöffel Butter und die Hälfte der Zitronenspalten dazu und löffle das Fett ständig über die Fische. Brate etwa vier Minuten, bis die Haut knusprig ist. Du erkennst den Gargrad an der Farbe: Sie wandert von unten an der Seite des Filets nach oben, dort wird das Fleisch hell. Hitze notfalls reduzieren, damit die Haut goldbraun, nicht schwarz wird.","dauer":4,"tipp":"Das ständige Übergießen gart das Fleisch von oben mit und macht es cremig."},{"titel":"Wenden und glasieren","aktion":"braten","text":"Wende die Filets vorsichtig, gib den letzten Esslöffel Butter in die Pfanne und streiche die Senfpaste auf die knusprige Hautseite. Löffle weiter Bratfett darüber und brate zwei bis drei Minuten, bis der Lachs gerade durchgegart ist. Er sollte in der Mitte noch leicht glasig und sehr saftig sein. Wer ihn durchgegart mag, gibt einige Minuten dazu. Drücke die restlichen Zitronenspalten über den Fisch.","dauer":3,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Nimm den Lachs aus der Pfanne und gib ihn auf eine Platte; löffle die Bratbutter mit Zitronensaft darüber. Lass ihn zwei Minuten ruhen, so verteilt sich der Saft. Streue frischen Dill darüber und reiche Zitronenspalten dazu. Samuelsson empfiehlt einen Salat aus rohem Grünkohl und Wurzelgemüse dazu, der mit seiner Frische und Bitterkeit gut gegen die Butter und die Würze wirkt. Richte alles zügig an, denn gebratener Lachs verliert, wenn er stehen bleibt, schnell seine Zartheit.","dauer":2,"tipp":"Mit gekochten Kartoffeln mit Dill und Butter ergibt es ein schwedisch geprägtes Alltagsgericht."}],"profitipps":["Haut trocken tupfen, Pfanne richtig heiß: nur so wird die Haut knusprig.","Ständig mit dem Bratfett übergießen: Das gart den Lachs von oben und macht ihn zart.","Senfpaste erst nach dem Wenden aufstreichen, damit sie nicht anbrennt.","Gewürze frisch mahlen: Koriander und Kreuzkümmel aus der Mühle haben ein völlig anderes Aroma als Pulver aus der Dose."],"varianten":["Mit mehr Chilipulver für Schärfe, wie Samuelsson es empfiehlt.","Mit Forelle oder Saibling statt Lachs.","Als kalter Lachs mit Gurkensalat am nächsten Tag."],"beilagen":["Salat aus rohem Grünkohl und Wurzelgemüse","Dillkartoffeln","Gurkensalat"],"getraenk":"Trockener Weißwein (Riesling, Grüner Veltliner) oder helles Bier","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson nennt das Gericht das schwedische Gegenstück zu Hackbraten und ein Alltagsessen seiner Kindheit; das Rezept erschien in „Marcus Off Duty“ (2014).","quelle":"https://www.foodnetwork.com/fnk/recipes/dill-spiced-salmon-8882831"}],"quellen":[{"titel":"Food Network – Dill-Spiced Salmon (Marcus Samuelsson)","url":"https://www.foodnetwork.com/fnk/recipes/dill-spiced-salmon-8882831"},{"titel":"Modern Mrs. Darcy – Marcus Off Duty: The Recipes I Cook at Home","url":"https://modernmrsdarcy.com/books/marcus-off-duty-the-recipes-i-cook-at-home/"}],"bild":"fisch","farben":["#d9784a","#f0b890","#5a7a3a"],"schlagworte":["Lachs","Dill","Schweden","Alltag"],"vegetarisch_moeglich":false},{"id":"skandinavien-eingelegter-hering-senfsauce-samuelsson","name":"Eingelegter Hering mit Senfsauce nach Art von Marcus Samuelsson","originalname":"Inlagd sill","kueche":"skandinavien","region":"Schweden","beliebtheit":56,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"vorspeise","kurz":"Gesalzener Hering wird gewässert, in süßsaurer Lake mit Möhre, Zwiebel und Lauch eingelegt und mit einer Senf-Dill-Sauce aus Kaffee und Rapsöl serviert.","hintergrund":"Eingelegter Hering gehört auf jeden schwedischen Smörgåsbord. Samuelsson nennt Hering mit Kartoffelsalat, brauner Butter, Meerrettich, Roggenbrot und hartem Käse einen Geschmack, der ihn ohne Reise zurück nach Schweden bringt. Sein Rezept, das Food Network veröffentlicht hat, legt entsalzene Heringsfilets in eine süße Lake und serviert sie mit einer Senfsauce, die ungewöhnlicherweise mit kaltem Kaffee abgerundet wird. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept in metrischen Einheiten; die Quelle nennt keine Säurestärke des Essigs und keine Menge der Portionen, ich habe 5 %igen Branntweinessig angenommen und gebe die Portionszahl als Schätzung an.","portionen":6,"zeit":{"vorbereitung":45,"garen":10,"ruhen":2880},"schwierigkeit":2,"zutaten":[{"gruppe":"Lake","liste":[{"menge":720,"einheit":"ml","name":"kaltes Wasser"},{"menge":240,"einheit":"ml","name":"Branntweinessig","hinweis":"5 %; Quelle nennt nur „vinegar“"},{"menge":400,"einheit":"g","name":"Zucker"},{"menge":1,"einheit":"Stück","name":"Möhre","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"gehackt"},{"menge":0.5,"einheit":"Stange","name":"Lauch","hinweis":"nur das Weiße"},{"menge":1,"einheit":"Blatt","name":"Lorbeerblatt"},{"menge":4,"einheit":"Stück","name":"schwarze Pfefferkörner"},{"menge":4,"einheit":"Stück","name":"weiße Pfefferkörner"}]},{"gruppe":"Fisch","liste":[{"menge":12,"einheit":"Stück","name":"gesalzene Heringsfilets","hinweis":"Salzhering vom Fischhändler oder aus dem Fass; nicht Matjes im Glas"}]},{"gruppe":"Senfsauce","liste":[{"menge":1,"einheit":"EL","name":"süßer Senf","hinweis":"z. B. Hausmachersenf"},{"menge":1,"einheit":"TL","name":"Dijon-Senf"},{"menge":2,"einheit":"TL","name":"Zucker"},{"menge":1.5,"einheit":"EL","name":"Branntweinessig","hinweis":"in Schweden „ättika“"},{"menge":1.5,"einheit":"EL","name":"kalter Kaffee"},{"menge":1,"einheit":"Prise","name":"Salz"},{"menge":1,"einheit":"Prise","name":"weißer Pfeffer"},{"menge":180,"einheit":"ml","name":"Rapsöl"},{"menge":20,"einheit":"g","name":"Dill","hinweis":"gehackt"}]}],"ausruestung":["Topf","große Schüssel zum Wässern","flache Form","Küchenmaschine oder Schneebesen","Schraubglas"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und würfle Möhre, Zwiebel und das Weiße der Lauchstange fein. Besorge den Salzhering möglichst bei einem Fischhändler; er ist stark gesalzen und braucht eine lange Wässerung. Die Zubereitung dauert insgesamt zwei Tage, mit 45 Minuten reiner Arbeitszeit. Stelle Schüssel, Form und Lakebehälter bereit und prüfe, dass im Kühlschrank genug Platz ist.","dauer":0,"tipp":""},{"titel":"Lake aufkochen","aktion":"kochen","text":"Gib Wasser, Essig, Zucker, Möhre, Zwiebel, Lauch, Lorbeer und beide Pfefferarten in einen Topf und bringe alles zum Kochen. Rühre gelegentlich um, bis sich der Zucker vollständig aufgelöst hat. Die Lake riecht jetzt süßsauer, würzig und leicht nach Zwiebel. Nimm den Topf vom Herd, decke ihn ab und lass die Lake vollständig auskühlen.","dauer":15,"tipp":"Die Lake muss ganz kalt sein, bevor sie über den Fisch kommt, sonst gart die Hitze die Heringe."},{"titel":"Hering wässern","aktion":"einlegen","text":"Lege die Heringsfilets in eine große Schüssel mit kaltem Wasser und lass sie über Nacht im Kühlschrank wässern. So geht das Salz heraus; ohne diesen Schritt wäre der Fisch ungenießbar salzig. Wechsle das Wasser, wenn du magst, einmal. Nach der Wässerung schmecken die Filets mild und die Fleischfarbe ist heller.","dauer":720,"tipp":"Probiere einen kleinen Bissen: Schmeckt er noch deutlich salzig, wässere weiter."},{"titel":"Hering einlegen","aktion":"einlegen","text":"Hole die gewässerten Filets aus dem Wasser und tupfe sie gründlich trocken. Lege sie in eine flache Form und bedecke sie vollständig mit der kalten Lake samt Gemüse. Stelle die Form abgedeckt über Nacht in den Kühlschrank. Der Hering nimmt Säure und Süße auf, das Fleisch wird fester und milder im Geschmack.","dauer":720,"tipp":"Alle Filets müssen vollständig von Lake bedeckt sein, sonst werden sie unansehnlich und können verderben."},{"titel":"Hering schneiden","aktion":"schneiden","text":"Hole den Hering am nächsten Tag aus der Lake und schneide die Filets in etwa 2 cm große Stücke. Die Filets sollen fest, aber nicht zäh sein, die Schnittfläche glänzt hell. Gräten, die du findest, ziehst du mit der Pinzette heraus. Die Lake kannst du wegwerfen oder abgedeckt aufheben. Arbeite mit einem scharfen Messer und schneide quer zur Faser, damit die Stücke nicht zerfasern; die Möhren- und Zwiebelstückchen in der Lake kannst du als Beilage mitservieren.","dauer":5,"tipp":""},{"titel":"Senfsauce herstellen","aktion":"mischen","text":"Gib süßen Senf, Dijon, Zucker, Essig, Kaffee, Salz und weißen Pfeffer in eine Küchenmaschine oder Schüssel. Lasse die Maschine laufen und gieße das Öl in dünnem Strahl hinein, bis die Sauce dick und glänzend wird wie Mayonnaise. Mit dem Schneebesen geht das auch, dauert aber länger; das Öl muss tröpfchenweise zugegeben werden, damit die Sauce bindet.","dauer":5,"tipp":"Läuft die Sauce auseinander, rühre einen weiteren Teelöffel Senf in eine frische Schüssel und gib die gerinnende Sauce tropfenweise zu."},{"titel":"Dill unterheben und ruhen lassen","aktion":"ruhen","text":"Hebe den gehackten Dill unter die Senfsauce. Die Quelle nennt Dill in der Zutatenliste, ohne zu sagen, wann; das Unterheben am Ende erhält die frische Farbe und das Aroma. Stelle die Sauce abgedeckt über Nacht in den Kühlschrank, damit sich die Aromen verbinden und die Sauce richtig fest wird. Sie sollte hellgelb mit grünen Dillflecken aussehen, dickcremig sein und süß-säuerlich nach Senf riechen; ist sie zu fest, verdünne sie mit einem Schluck kaltem Wasser.","dauer":0,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Richte die Heringsstücke auf einer Platte an und serviere die Senfsauce dazu. Traditionell isst man eingelegten Hering mit lauwarmen Kartoffeln oder Kartoffelsalat, brauner Butter, frisch geriebenem Meerrettich, Roggenbrot und hartem Käse, ähnlich wie Samuelsson ihn aus Schweden kennt. Auch zu Knäckebrot und einem Gläschen Aquavit schmeckt er hervorragend.","dauer":0,"tipp":"Zimmerwarm serviert schmeckt Hering am besten; hole ihn 15 Minuten vor dem Essen aus dem Kühlschrank."}],"profitipps":["Salzhering lange genug wässern: zu kurz ist ein Fehler, den man nicht mehr korrigieren kann.","Lake vollständig abkühlen lassen, bevor sie den Fisch berührt.","Die Senfsauce lebt vom Kaffee: Er gibt eine tiefe, leicht röstige Note statt Säure.","Die Sauce hält sich im Kühlschrank einige Tage."],"varianten":["Mit Zwiebelringen und Dillzweigen im Glas eingelegt.","Mit Matjes statt Salzhering: kürzer wässern.","Als Heringsbrot auf Roggenbrot mit Kartoffelscheiben."],"beilagen":["Lauwarme Kartoffeln","Kartoffelsalat mit brauner Butter","Roggenbrot","Meerrettich","Harter Käse"],"getraenk":"Aquavit und kaltes Pils","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson nennt eingelegten Hering mit Kartoffelsalat, brauner Butter und Roggenbrot einen der Geschmäcke, die ihn zurück nach Schweden bringen; sein Rezept für eingelegten Hering mit Senfsauce hat Food Network veröffentlicht.","quelle":"https://www.foodnetwork.com/recipes/marcus-samuelsson/pickled-herring-recipe-1965148"}],"quellen":[{"titel":"Food Network – Pickled Herring (Marcus Samuelsson)","url":"https://www.foodnetwork.com/recipes/marcus-samuelsson/pickled-herring-recipe-1965148"},{"titel":"First We Feast – The 10 Dishes That Made My Career: Marcus Samuelsson","url":"https://amp.firstwefeast.com/features/marcus-samuelsson-career-changing-dishes"},{"titel":"Wikipedia – Marcus Samuelsson","url":"https://en.wikipedia.org/wiki/Marcus_Samuelsson"}],"bild":"fisch","farben":["#6a7a8a","#c2cdd6","#d9a64a"],"schlagworte":["Hering","Smörgåsbord","Schweden","Einlegen"],"vegetarisch_moeglich":false},{"id":"skandinavien-svensk-limpa","name":"Svensk Limpa (schwedisches Würzbrot)","originalname":"Vörtbröd / Vörtlimpa","kueche":"skandinavien","region":"Schweden","beliebtheit":50,"hauptkategorie":"vegetarisch","kurz":"Leicht süßes, dunkles Roggenbrot mit Orangenschale, Fenchel, Anis und Sirup: weich, würzig und duftend – das klassische Weihnachtsbrot zum schwedischen Julbord.","hintergrund":"Limpa ist ein süßliches, hefegetriebenes schwedisches Roggenbrot; der schwedische Name vörtbröd bzw. vörtlimpa verweist auf die Bierwürze (vört), mit der es früher aufgehen sollte. Als Heimat gilt Nordschweden, später verbreitete sich das Würzbrot in den Süden. Die Zutaten sind Roggenmehl, oft gemischt mit Weizenmehl, Sirup oder Melasse und Zucker, Würze oder dunkles Bier, Butter sowie Gewürze wie Kümmel, Anis, Fenchel und Bitterorange bzw. Orangenschale. Limpa wird vor allem zur Weihnachtszeit gebacken und gehört zum Julbord, dem Weihnachtsbuffet. Dazu passen Marmelade, Frischkäse und kräftiger Käse.","portionen":12,"zeit":{"vorbereitung":35,"garen":50,"ruhen":150},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig (2 kleine Laibe oder 1 großer)","liste":[{"menge":300,"einheit":"g","name":"Roggenmehl Type 1150","hinweis":""},{"menge":300,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"oder Type 812"},{"menge":200,"einheit":"ml","name":"dunkles Bier oder Malzbier","hinweis":"lauwarm"},{"menge":150,"einheit":"ml","name":"Wasser","hinweis":"lauwarm, ca. 30 °C"},{"menge":80,"einheit":"g","name":"Zuckerrübensirup oder Melasse","hinweis":"oder dunkler Sirup"},{"menge":20,"einheit":"g","name":"frische Hefe","hinweis":"entspricht ca. 7 g Trockenhefe"},{"menge":10,"einheit":"g","name":"Salz","hinweis":""},{"menge":30,"einheit":"g","name":"Butter","hinweis":"weich"},{"menge":1,"einheit":"Stück","name":"Bio-Orange","hinweis":"nur die abgeriebene Schale"}]},{"gruppe":"Gewürze","liste":[{"menge":1,"einheit":"TL","name":"Fenchelsamen","hinweis":"gemahlen"},{"menge":1,"einheit":"TL","name":"Anis","hinweis":"gemahlen"},{"menge":1,"einheit":"TL","name":"Kümmel","hinweis":"gemahlen"}]},{"gruppe":"Zum Bestreichen","liste":[{"menge":1,"einheit":"EL","name":"Sirup","hinweis":"mit 1 EL warmem Wasser verrührt"}]}],"ausruestung":["Küchenmaschine oder Schüssel","Mörser oder Gewürzmühle","Backblech oder Kastenformen","Backpinsel","Küchenthermometer","Abkühlgitter"],"schritte":[{"titel":"Gewürze vorbereiten","aktion":"vorbereiten","text":"Zerstoße Fenchel, Anis und Kümmel im Mörser oder in der Gewürzmühle fein – frisch gemahlen sind die ätherischen Öle viel aromatischer. Reibe die Orangenschale von einer unbehandelten Orange ab, ohne die weiße, bittere Haut mitzuerwischen. Erwärme das Bier und das Wasser auf etwa 30 °C und rühre den Sirup unter, bis er sich gelöst hat. Zerbröckele die Hefe dazu und lasse alles 5 Minuten stehen, bis ein leichter Schaum entsteht.","dauer":10,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib beide Mehle, Salz, Gewürze und Orangenschale in die Schüssel und gieße die Bier-Hefe-Mischung dazu. Knete 3 Minuten, gib dann die weiche Butter dazu und knete weitere 6–8 Minuten. Der Teig ist durch den Roggen weich, klebrig und glänzend. Er soll glatt zusammenhalten; die Fensterprobe ist nur eingeschränkt möglich. Die Teigtemperatur sollte bei 26 °C liegen.","dauer":12,"tipp":"Wenn der Teig sehr klebt, mit nassen Händen arbeiten – nicht mit zu viel Mehl."},{"titel":"Stockgare","aktion":"gehen","text":"Decke den Teig ab und lasse ihn bei 24–26 °C 60–75 Minuten gehen, bis er sich um etwa die Hälfte vergrößert hat. Der Duft nach Orange und Gewürzen wird mit der Gare intensiver; die Oberfläche zeigt feine Bläschen. Falte den Teig nach 30 Minuten einmal. Roggenteige gehen nicht so hoch wie Weizenteige; lass dich nicht zu langem Warten verleiten.","dauer":70,"tipp":""},{"titel":"Formen","aktion":"formen","text":"Teile den Teig in zwei gleich große Stücke (je ca. 700 g) und forme jedes zu einem runden oder länglichen Laib. Ziehe die Ränder zur Mitte, drehe den Teig um und rolle ihn mit den Händen straff. Lege die Laibe mit Abstand auf ein mit Backpapier belegtes Blech oder in gefettete Kastenformen. Bemehle die Hände leicht, da der Teig klebt.","dauer":10,"tipp":""},{"titel":"Stückgare mit Fingerprobe","aktion":"gehen","text":"Decke die Laibe ab und lasse sie 40–50 Minuten bei Zimmertemperatur gehen, bis sie sichtbar aufgegangen sind. Die Fingerprobe zeigt, ob sie bereit sind: Eine 1 cm tiefe Delle soll sich langsam zur Hälfte zurückbilden. Heize währenddessen den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor und stelle eine Schale mit Wasser auf den Boden.","dauer":45,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Schneide die Laibe mit einer scharfen Klinge einmal längs ein und schiebe sie in den Ofen. Backe 15 Minuten bei 200 °C, dann senkst du auf 180 °C Ober-/Unterhitze (160 °C Umluft) und backst weitere 30–35 Minuten. Die Kruste soll tiefbraun sein, der Duft nach Orange und Fenchel erfüllt die Küche. Das Brot ist gar bei einer Kerntemperatur von 96–98 °C und hohlem Klang beim Klopfen.","dauer":50,"tipp":""},{"titel":"Glasieren und Auskühlen","aktion":"ruhen","text":"Bestreiche die heißen Brote sofort mit dem Sirup-Wasser-Gemisch, sodass die Kruste glänzt und die Aromen eingeschlossen werden. Lege sie auf ein Gitter und lasse sie mindestens 2 Stunden vollständig auskühlen. Das Aroma entfaltet sich am zweiten Tag richtig, wenn die Gewürze durchgezogen sind. In Leinen oder im Brotkasten bleibt Limpa 4–5 Tage frisch; eingefroren 3 Monate.","dauer":120,"tipp":""}],"profitipps":["Gewürze frisch mahlen – sie machen den Geschmack aus.","Nur die Orangenschale (ohne weiße Haut) verwenden, sonst wird das Brot bitter.","Der Sirup-Glanz nach dem Backen gibt Aroma und Optik.","Bier und Sirup nicht zu heiß – 30 °C reichen.","Ein dunkles Malzbier macht das Brot weicher und süßer.","Lagere es einen Tag, bevor du es anschneidest."],"varianten":["Mit Rosinen oder Pflaumen (südschwedische Art).","Ohne Kümmel, dafür mit Kardamom.","Mit Stout statt Malzbier.","Mit Dinkelmehl statt Weizen."],"beilagen":["Butter und kräftiger Käse","Marmelade oder Frischkäse","Zum Julbord mit Hering und Schinken","Als Frühstücksbrot"],"getraenk":"Glögg, Malzbier oder Kaffee.","koeche":[],"quellen":[{"titel":"Limpa bread – Wikipedia","url":"https://en.wikipedia.org/wiki/Limpa_bread"}],"bild":"brot","farben":["#5e3d1c","#a06c36","#e0b97a"],"schlagworte":["Weihnachten","Schweden","Roggen","Gewürzbrot"],"themen":["fest"],"fleischsorte":"","gang":"brot","vegetarisch_moeglich":true},{"id":"skandinavien-gingersnaps-aquavit-samuelsson","name":"Aquavit-Gingersnaps mit kandierter Orangenschale nach Art von Marcus Samuelsson","originalname":"Aquavit’s Gingersnap Cookies","kueche":"skandinavien","region":"Schweden / New York","beliebtheit":48,"hauptkategorie":"suess","fleischsorte":"","gang":"gebaeck","kurz":"Würzige Ingwerplätzchen mit Melasse, Kardamom, Nelken, einer Prise weißem Pfeffer und kandierter Orangenschale, außen in Zucker gewälzt.","hintergrund":"Samuelsson war Küchenchef im New Yorker Restaurant Aquavit, das Skandinavische Küche in Manhattan bekannt machte; die Gingersnaps stehen für die schwedische Plätzchenkultur, wie sie vor allem in der Adventszeit gebacken wird. Das Rezept hat Samuelsson in der Food-Network-Sendung „Sweet Dreams“ in der Folge „Scandinavian Sweets“ vorgestellt. Die Kombination aus Melasse, Ingwer, Kardamom, Nelken, einem Hauch weißem Pfeffer und Orangenschale macht den Teig aromatisch und dunkel. Dies ist eine Heimküchen-Fassung nach dem veröffentlichten Rezept in metrischen Einheiten; die Quelle nennt keine genaue Kühlzeit, ich habe mindestens eine Stunde angesetzt.","portionen":18,"zeit":{"vorbereitung":30,"garen":7,"ruhen":120},"schwierigkeit":1,"zutaten":[{"gruppe":"Teig","liste":[{"menge":100,"einheit":"g","name":"brauner Zucker","hinweis":"hell"},{"menge":100,"einheit":"g","name":"Zucker","hinweis":"für den Teig"},{"menge":225,"einheit":"g","name":"Butter","hinweis":"weich"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M"},{"menge":110,"einheit":"ml","name":"Melasse","hinweis":"ersatzweise dunkler Zuckerrübensirup"},{"menge":2,"einheit":"TL","name":"Ingwerpulver"},{"menge":0.5,"einheit":"TL","name":"Kardamom, gemahlen"},{"menge":0.5,"einheit":"TL","name":"Gewürznelken, gemahlen"},{"menge":2,"einheit":"TL","name":"Natron"},{"menge":0.5,"einheit":"TL","name":"Salz"},{"menge":0.5,"einheit":"TL","name":"weißer Pfeffer"},{"menge":280,"einheit":"g","name":"Weizenmehl Type 405"},{"menge":150,"einheit":"g","name":"kandierte Orangenschale","hinweis":"grob gehackt"}]},{"gruppe":"Zum Wälzen","liste":[{"menge":100,"einheit":"g","name":"Zucker"}]}],"ausruestung":["Rührschüssel und Handrührgerät","Backblech","Backpapier oder Fett","Kuchengitter","Sieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und lass die Butter weich werden, sie soll sich leicht eindrücken lassen, ohne zu schmelzen. Hacke die kandierte Orangenschale grob, damit in jedem Plätzchen Stücke zu spüren sind. Heize den Ofen auf 175 °C Ober-/Unterhitze (155 °C Umluft) vor und fette das Blech oder lege es mit Backpapier aus. Siebe Mehl, Natron, Salz und alle Gewürze zusammen in eine Schüssel; so verteilen sie sich gleichmäßig.","dauer":0,"tipp":""},{"titel":"Zucker und Butter schaumig schlagen","aktion":"aufschlagen","text":"Schlage Butter, braunen Zucker und 100 g Zucker mit dem Handrührgerät etwa drei bis fünf Minuten cremig, bis die Masse hell und luftig ist. Der Zucker soll sich kaum noch knirschend anfühlen. Dieser Schritt bringt Luft in den Teig und macht die Plätzchen später mürbe-knusprig statt hart. Schabe zwischendurch den Rand der Schüssel mit einem Teigschaber ab, damit keine Butterklumpen übrig bleiben, und höre auf, sobald die Masse hell, cremig und etwa um die Hälfte im Volumen gewachsen ist.","dauer":4,"tipp":""},{"titel":"Ei und Melasse zugeben","aktion":"mischen","text":"Rühre das Ei und die Melasse ein, bis eine gleichmäßige braune Creme entsteht. Die Melasse gibt Farbe, Feuchtigkeit und ein bittersüßes Aroma, das die Gewürze trägt. Wenn die Masse gerinnt, weil die Zutaten zu kalt sind, rühre einen Esslöffel von der Mehlmischung ein; sie bindet sich wieder. Die Masse sieht nach dem Einrühren dunkelbraun und glänzend aus und riecht herb-süß nach Melasse, ähnlich wie Lebkuchenteig. Rühre nur so lange, bis keine Streifen mehr sichtbar sind.","dauer":2,"tipp":"Misst du die Melasse ab, benetze den Löffel vorher mit etwas Öl, dann rutscht sie sauber heraus."},{"titel":"Trockene Zutaten einarbeiten","aktion":"mischen","text":"Gib die gesiebte Mehlmischung in zwei bis drei Portionen zur Buttermasse und rühre auf niedriger Stufe, bis ein weicher, dunkler Teig entsteht, an dem kein Mehl mehr zu sehen ist. Rühre nicht zu lange, damit der Teig nicht zäh wird. Er duftet jetzt deutlich nach Ingwer, Nelken und Kardamom. Schabe den Schüsselrand noch einmal ab und prüfe, dass am Boden kein Mehl liegt. Der Teig sollte sich etwa wie weiche Knete anfühlen; ist er sehr klebrig, wird er im Kühlschrank fester.","dauer":3,"tipp":""},{"titel":"Orangenschale unterheben","aktion":"mischen","text":"Hebe die gehackte kandierte Orangenschale mit einem Spatel unter den Teig. Sie soll gleichmäßig verteilt sein; ihre Süße und Säure setzt Akzente gegen die Wärme der Gewürze. Der Teig ist jetzt weich und klebrig, das ist normal. Die Orangenstücke dürfen nicht zu groß sein, sonst zerreißen sie beim Formen der Kugeln den Teig. Kostest du ein winziges Stück Teig, schmeckst du würzige Wärme und die fruchtige Süße der Schale; schmeckt es dir zu scharf, hilft etwas mehr Orangenschale.","dauer":1,"tipp":""},{"titel":"Teig kühlen","aktion":"kuehlen","text":"Decke die Schüssel ab oder wickle den Teig in Folie und stelle ihn in den Kühlschrank, bis er fest und formbar ist, mindestens eine Stunde. Er lässt sich dann leichter zu Kugeln rollen, und die Butter bleibt beim Backen länger fest, sodass die Plätzchen nicht zerlaufen. Wer es eilig hat, kann ihn 30 Minuten ins Gefrierfach legen.","dauer":120,"tipp":""},{"titel":"Kugeln formen und wälzen","aktion":"formen","text":"Forme aus dem Teig mit leicht angefeuchteten Händen etwa 2,5 cm große Kugeln. Wälze die obere Hälfte jeder Kugel in dem Zucker; der Zucker bildet beim Backen eine knusprige, glitzernde Kruste. Lege die Kugeln mit etwa 5 cm Abstand auf das vorbereitete Blech; sie laufen beim Backen auseinander und werden dabei flach und rissig. Backe notfalls in mehreren Durchgängen und lasse den restlichen Teig im Kühlschrank, bis er dran ist.","dauer":10,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Backe die Plätzchen etwa 7 Minuten im vorgeheizten Ofen, bis sie goldbraun sind und die Oberfläche feine Risse zeigt. Sie sind in der Mitte noch weich und werden beim Abkühlen fest; backe sie nicht länger, sonst werden sie hart und bitter. Der Duft nach Ingwer, Nelken und Orange füllt die Küche. Beginne nach fünf Minuten, das Blech zu beobachten, denn die dünnen Ränder bräunen schneller als die Mitte. Drehe das Blech notfalls einmal, wenn dein Ofen ungleichmäßig heizt.","dauer":7,"tipp":"Backe jeweils ein Blech nach dem anderen, damit sie gleichmäßig bräunen."},{"titel":"Auskühlen","aktion":"kuehlen","text":"Hebe die Plätzchen vorsichtig mit einem Pfannenwender auf ein Kuchengitter und lasse sie vollständig abkühlen; erst dann sind sie knusprig. Bewahre sie in einer gut schließenden Dose auf, sie halten sich etwa eine Woche. Mit einer Tasse Tee oder Kaffee oder zu Eiscreme schmecken sie besonders gut. Frisch gebacken sind sie noch leicht zäh, nach einem Tag in der Dose werden sie knuspriger und das Gewürz entwickelt sich weiter; so bleiben sie auch für Geschenke schön.","dauer":15,"tipp":"Wer sie weicher mag, legt ein Stück Apfelschale in die Dose."}],"profitipps":["Gewürze vorher mit dem Mehl sieben: So gibt es keine scharfen Nester aus Nelkenpulver.","Teig gut kühlen: Zu weicher Teig läuft auseinander.","Nicht zu lange backen: Sie härten beim Abkühlen nach.","Weißer Pfeffer gibt eine feine Schärfe, ohne sichtbar zu sein."],"varianten":["Mit gehacktem kandiertem Ingwer statt Orangenschale.","Zu Sandwich-Plätzchen mit Frischkäsecreme gefüllt.","Als Gewürzbasis für einen Käsekuchenboden."],"beilagen":["Tee","Glögg","Eiscreme"],"getraenk":"Kaffee, schwarzer Tee oder Glögg","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson hat die Aquavit-Gingersnaps in der Food-Network-Sendung „Sweet Dreams“ (Folge „Scandinavian Sweets“) vorgestellt; Aquavit war sein New Yorker Restaurant.","quelle":"https://www.foodnetwork.com/recipes/marcus-samuelsson/aquavits-gingersnap-cookies-recipe-1938331"}],"quellen":[{"titel":"Food Network – Aquavit’s Gingersnap Cookies (Marcus Samuelsson)","url":"https://www.foodnetwork.com/recipes/marcus-samuelsson/aquavits-gingersnap-cookies-recipe-1938331"},{"titel":"Wikipedia – Marcus Samuelsson","url":"https://en.wikipedia.org/wiki/Marcus_Samuelsson"}],"bild":"gebaeck","farben":["#8a4a1e","#c98a4a","#e8c89a"],"schlagworte":["Plätzchen","Weihnachten","Ingwer","Aquavit"],"vegetarisch_moeglich":true},{"id":"skandinavien-ingwer-birne-preiselbeersud-samuelsson","name":"Ingwer-Birne im Filoteig mit Preiselbeersud nach Art von Marcus Samuelsson","originalname":"Ginger Poached Pear in Lingonberry Broth","kueche":"skandinavien","region":"Schweden / New York","beliebtheit":38,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"In Ingwer-Zimt-Wein pochierte Birnen, in Filoteig gewickelt, mit einer Vanilleschote zusammengebunden und im Ofen goldbraun gebacken – auf warmem Preiselbeersud.","hintergrund":"Preiselbeeren gehören zu Schwedens wichtigsten Beeren: Man isst sie zu Köttbullar, zu Wild und in Desserts. Samuelsson, der in Göteborg aufwuchs und später das Aquavit in New York leitete, hat dieses Dessert veröffentlicht, das die klassische pochierte Birne mit Filoteig zu einem eleganten Päckchen macht und mit einer Vanilleschote als Bändchen zusammenbindet. Dies ist eine Heimküchen-Fassung nach dem bei Food Network veröffentlichten Rezept in metrischen Einheiten; die Quelle nennt keine Zeiten für Vorbereitung und gibt als einzige Angabe 10–15 Minuten Pochieren und 10–12 Minuten Backen bei 200 °C.","portionen":4,"zeit":{"vorbereitung":30,"garen":35,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Pochierte Birnen","liste":[{"menge":4,"einheit":"Stück","name":"kleine, feste Birnen","hinweis":"geschält, Stiel dranlassen"},{"menge":60,"einheit":"g","name":"Zucker"},{"menge":1,"einheit":"Stück","name":"Zitrone, Saft"},{"menge":1.9,"einheit":"l","name":"kaltes Wasser"},{"menge":1,"einheit":"Stange","name":"Zimtstange"},{"menge":1.5,"einheit":"EL","name":"frischer Ingwer","hinweis":"gehackt"},{"menge":120,"einheit":"ml","name":"Weißwein"},{"menge":3,"einheit":"Blatt","name":"Filoteig","hinweis":"aufgetaut"},{"menge":2,"einheit":"EL","name":"Butter","hinweis":"geschmolzen"},{"menge":4,"einheit":"Stück","name":"Vanilleschoten","hinweis":"in kaltem Wasser eingeweicht, zum Binden"}]},{"gruppe":"Preiselbeersud","liste":[{"menge":250,"einheit":"g","name":"Preiselbeeren","hinweis":"frisch oder tiefgekühlt"},{"menge":1,"einheit":"Stange","name":"Zimtstange"},{"menge":2,"einheit":"Stück","name":"Gewürznelken"},{"menge":0.5,"einheit":"TL","name":"Ingwerpulver"},{"menge":0.5,"einheit":"TL","name":"Kardamom, gemahlen"},{"menge":100,"einheit":"g","name":"brauner Zucker"},{"menge":1,"einheit":"Stück","name":"Orange, Schale","hinweis":"unbehandelt, fein abgerieben"},{"menge":480,"einheit":"ml","name":"Wasser"}]}],"ausruestung":["großer Topf","Backblech oder Auflaufform","Alufolie","Pinsel","kleiner Topf"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle die Birnen, lasse die Stiele dran und schneide unten eine kleine Standfläche ab, damit sie später aufrecht stehen. Hacke den Ingwer, presse die Zitrone und reibe die Orangenschale ab. Lege die Vanilleschoten in kaltes Wasser, bis sie biegsam sind; sie sollen später als Band um den Filoteig dienen, deshalb sind frische, weiche Schoten wichtig. Heize den Ofen noch nicht vor, das kommt später.","dauer":0,"tipp":""},{"titel":"Pochiersud ansetzen","aktion":"kochen","text":"Gib Zucker, Zitronensaft, Wasser, Zimtstange, Ingwer und Weißwein in einen großen Topf und bringe alles auf mittlerer bis hoher Hitze zum Kochen. Der Sud duftet nach Zimt und Ingwer. Lege die geschälten Birnen hinein, damit sie nicht braun werden, und reduziere die Hitze, sodass die Flüssigkeit nur leicht wallt.","dauer":5,"tipp":""},{"titel":"Birnen pochieren","aktion":"koecheln","text":"Lass die Birnen 10 bis 15 Minuten sanft im Sud ziehen, bis sie weich sind. Prüfe mit einem Holzspieß: Er soll ohne Widerstand hineingleiten, die Birne darf aber nicht zerfallen. Hebe sie vorsichtig mit einem Löffel heraus und lege sie auf einen Teller. Die Birnen sollen eine hellgelbe, leicht durchscheinende Farbe haben und nach Zimt und Ingwer duften. Der Sud kann weggegossen werden; er hat seine Dienste getan.","dauer":15,"tipp":"Kleine, feste Birnen wie Williams Christ oder Abate Fetel garen gleichmäßiger als sehr reife."},{"titel":"Birnen trocknen","aktion":"ruhen","text":"Tupfe die Birnen mit einem Küchentuch gründlich trocken. Feuchte Birnen weichen den Filoteig durch und lassen ihn im Ofen nicht knusprig werden. Stelle sie 10 bis 15 Minuten zur Seite und heize währenddessen den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor. Die Haut der Birnen fühlt sich dann leicht klebrig-trocken an, das ist gut, weil der Teig daran haftet. Schneide bei Bedarf unten einen weiteren Streifen ab, damit die Birnen in der Form stabil stehen.","dauer":15,"tipp":""},{"titel":"Filoteig zuschneiden","aktion":"schneiden","text":"Stapele die Filoteigblätter auf einem Brett und schneide sie mit einem scharfen Messer in vier gleich große Quadrate. Bestreiche jedes Quadrat dünn mit geschmolzener Butter, bis es gleichmäßig glänzt, ohne dass die Butter in Pfützen steht. Der Teig trocknet schnell aus: Decke ungenutzte Blätter mit einem feuchten Tuch ab. Lege auf jedes Quadrat eine Birne.","dauer":5,"tipp":"Filo reißt leicht: Zügig, aber ohne Druck arbeiten."},{"titel":"Einwickeln und binden","aktion":"formen","text":"Ziehe den Teig rund um jede Birne nach oben und rafft ihn oberhalb wie einen kleinen Beutel zusammen. Binde ihn etwa 2,5 cm unter dem Rand mit einer eingeweichten Vanilleschote zu. Die Vanilleschote sollte biegsam sein; reißt sie, nimm eine zweite. Der Teig darf an den Rändern wie ein Röckchen stehen.","dauer":5,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Setze die Birnen in eine Auflaufform, decke sie mit Alufolie ab und backe sie 10 bis 12 Minuten, bis der Teig goldbraun ist. Entferne die Folie für die letzten Minuten, wenn der Teig noch blass wirkt. Du erkennst den Gargrad an der Farbe: ein tiefes, sattes Goldbraun. Der Duft nach Butter und Vanille zieht durch die Küche.","dauer":12,"tipp":""},{"titel":"Preiselbeersud kochen","aktion":"koecheln","text":"Gib alle Zutaten für den Sud in einen Topf und erwärme sie bei niedriger Hitze, ohne zu kochen, bis alles gut vermischt und durchgewärmt ist. Die Beeren sollen weich werden, aber nicht komplett zerfallen. Der Sud ist tiefrot, leicht säuerlich und duftet nach Orange und Gewürzen. Schmecke mit etwas Zucker ab, falls er zu herb ist.","dauer":10,"tipp":"Nicht kochen: Die Beeren würden sonst bitter und der Sud trüb."},{"titel":"Anrichten","aktion":"anrichten","text":"Gib die gebackenen Birnen in tiefe Teller oder eine große Schale und gieße den warmen Preiselbeersud rundherum. Wer mag, serviert dazu zwei Kugeln Vanilleeis. Der Kontrast aus knusprigem Teig, warmer Birne und säuerlicher Beere macht das Dessert besonders. Löse den Teig mit dem Löffel Stück für Stück vom Birnenhals, damit der Sud dazwischenläuft; die Vanilleschote ist übrigens nicht zum Essen gedacht, du kannst sie nach dem Servieren abziehen und zum Aromatisieren von Zucker aufheben.","dauer":0,"tipp":"Das Dessert wird warm serviert; der Filoteig bleibt nur kurz knusprig."}],"profitipps":["Birnen gut trocken tupfen, bevor sie in den Teig kommen.","Filoteig immer abdecken, sonst bricht er.","Preiselbeersud nicht kochen, nur durchwärmen.","Die Birnen lassen sich vorab pochieren, das Einwickeln und Backen erst kurz vor dem Servieren."],"varianten":["Mit Apfel statt Birne.","Mit Cranberrys, wenn keine Preiselbeeren zu bekommen sind.","Ohne Teig als einfache pochierte Birne."],"beilagen":["Vanilleeis","Schlagsahne"],"getraenk":"Süßer Weißwein, Dessertwein oder Tee","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson hat das Dessert aus pochierter Birne im Filoteig mit Preiselbeersud bei Food Network veröffentlicht; es verbindet schwedische Zutaten mit klassischer Dessertküche.","quelle":"https://www.foodnetwork.com/recipes/ginger-poached-pear-in-lingonberry-broth-recipe-2011058"}],"quellen":[{"titel":"Food Network – Ginger Poached Pear in Lingonberry Broth (Marcus Samuelsson)","url":"https://www.foodnetwork.com/recipes/ginger-poached-pear-in-lingonberry-broth-recipe-2011058"},{"titel":"Wikipedia – Marcus Samuelsson","url":"https://en.wikipedia.org/wiki/Marcus_Samuelsson"}],"bild":"dessert","farben":["#b03a2a","#e0a860","#f0e0b0"],"schlagworte":["Dessert","Birne","Preiselbeere","Schweden"],"vegetarisch_moeglich":true},{"id":"skandinavien-brombeersuppe-sauerrahm-sorbet-samuelsson","name":"Brombeersuppe mit Sauerrahm-Sorbet und Champagner nach Art von Marcus Samuelsson","originalname":"Champagne-Infused Blackberry Soup with Sour Cream Sorbet","kueche":"skandinavien","region":"Schweden / New York","beliebtheit":34,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Kalte, tiefviolette Beerensuppe mit einer Kugel säuerlichem Sauerrahm-Sorbet und einem Schuss Champagner – leicht, frisch und schnell gemacht.","hintergrund":"Fruchtsuppen sind in Skandinavien ein Klassiker: Kalte oder warme Beerensuppen kommen als Dessert oder zum Frühstück auf den Tisch. Samuelsson hat diese Brombeersuppe mit einer Kugel Sauerrahm-Sorbet in der Food-Network-Reihe veröffentlicht; die säuerliche Kugel bringt Frische zur süßen Beere, der Champagner einen festlichen Hauch. Die Quelle sagt, das Gericht sei einfacher als gedacht und komme schnell zusammen. Dies ist eine Heimküchen-Fassung in metrischen Einheiten; die Quelle nennt keine Zeiten, daher sind sie geschätzt, und der Zucker im Sorbet ist sehr knapp bemessen – er wird deshalb nach Geschmack angepasst.","portionen":4,"zeit":{"vorbereitung":15,"garen":15,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Brombeersuppe","liste":[{"menge":480,"einheit":"ml","name":"Wasser"},{"menge":100,"einheit":"g","name":"Zucker"},{"menge":1,"einheit":"Stück","name":"Zitrone, halber Saft","hinweis":"Saft einer halben Zitrone"},{"menge":430,"einheit":"g","name":"Brombeeren","hinweis":"frisch oder tiefgekühlt"},{"menge":3,"einheit":"Blatt","name":"Minzblätter"},{"menge":60,"einheit":"ml","name":"Champagner oder Sekt","hinweis":"zum Servieren"}]},{"gruppe":"Sauerrahm-Sorbet","liste":[{"menge":1,"einheit":"EL","name":"Zucker"},{"menge":240,"einheit":"ml","name":"Wasser"},{"menge":0.5,"einheit":"EL","name":"Glukosesirup","hinweis":"„corn syrup“ der Quelle; ersatzweise Maissirup oder Honig"},{"menge":1,"einheit":"Stück","name":"Limette, Saft"},{"menge":120,"einheit":"g","name":"Sauerrahm","hinweis":"saure Sahne oder Crème fraîche"}]}],"ausruestung":["Topf","Mixer oder Stabmixer","feines Sieb","Eismaschine (oder Gefrierdose und Gabel)"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und wasche die Brombeeren kurz. Stelle die Eismaschine bereit, bzw. lege die Gefrierschale vorab ins Gefrierfach, falls dein Gerät das braucht. Presse Zitrone und Limette aus. Wenn du tiefgekühlte Brombeeren verwendest, taue sie nicht auf, sie können direkt in den Topf. Plane genug Zeit zum Abkühlen und Gefrieren ein.","dauer":0,"tipp":""},{"titel":"Sirup für das Sorbet","aktion":"kochen","text":"Koche für das Sorbet einen Esslöffel Zucker, 240 ml Wasser und den Glukosesirup in einem Topf auf mittlerer bis hoher Hitze einmal auf. Lass den Sirup danach vollständig abkühlen, am besten im Kühlschrank. Die Mischung ist klar und dünnflüssig; sie dient als Basis, die die Konsistenz des Sorbets geschmeidig hält.","dauer":10,"tipp":"Kaltstellen im Eiswasserbad geht schneller."},{"titel":"Sorbetbasis anrühren","aktion":"mischen","text":"Rühre den abgekühlten Sirup mit Limettensaft und Sauerrahm glatt. Probiere die Masse: Sie schmeckt frisch und säuerlich. Die Quelle nennt sehr wenig Zucker; magst du es weniger herb, süße die Mischung vor dem Gefrieren nach, denn Kälte dämpft den Geschmack von Süße. Stelle sie dann kalt, bis du sie gefrierst.","dauer":3,"tipp":"Eigene Anmerkung: Süße vorher abschmecken, nicht erst nach dem Gefrieren."},{"titel":"Brombeersuppe kochen","aktion":"koecheln","text":"Gib Wasser, Zucker, Brombeeren und Zitronensaft in einen Topf und bringe alles bei mittlerer bis hoher Hitze zum Kochen. Reduziere dann die Hitze und lass alles etwa 10 Minuten simmern, bis die Beeren zerfallen und das Wasser tief violett gefärbt ist. Es duftet nach reifer Beere. Gib die Minzblätter hinein, nimm den Topf vom Herd und lass die Mischung abkühlen.","dauer":15,"tipp":""},{"titel":"Pürieren und sieben","aktion":"puerieren","text":"Püriere die abgekühlte Suppe im Mixer, bis sie ganz glatt ist, und streiche sie durch ein feines Sieb, damit die Kerne zurückbleiben. Drücke mit einem Löffel nach, damit möglichst viel Fruchtfleisch hindurchgeht. Die Suppe ist nun seidig und tiefviolett. Schmecke ab und stelle sie kalt, mindestens eine Stunde.","dauer":5,"tipp":"Wer es leichter mag, verdünnt die Suppe mit etwas kaltem Wasser."},{"titel":"Sorbet gefrieren","aktion":"kuehlen","text":"Gib die Sorbetbasis in die Eismaschine und lass sie laufen, bis sie eine cremige, formbare Konsistenz hat, ähnlich weichem Eis. Ohne Maschine füllst du die Mischung in eine flache Dose und rührst sie während der ersten drei Stunden alle 30 Minuten mit einer Gabel durch, damit keine großen Eiskristalle entstehen. Das Sorbet soll schneeweiß, glatt und leicht säuerlich sein.","dauer":180,"tipp":"Sorbet nach dem Gefrieren 10 Minuten bei Zimmertemperatur anwärmen, dann lässt es sich besser portionieren."},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile die kalte Brombeersuppe auf vier tiefe Teller oder Schalen. Setze in die Mitte jeweils eine Kugel Sauerrahm-Sorbet und gieße einen Schuss Champagner darüber, kurz vor dem Servieren, damit er noch sprudelt. Garniere mit einem Minzblatt. Der Kontrast aus warmer Beerenwürze, Kälte und Prickeln macht den Reiz dieses Desserts aus.","dauer":0,"tipp":"Ohne Alkohol: Statt Champagner Tonic oder Sprudelwasser verwenden."}],"profitipps":["Gut durchsieben: Brombeerkerne ergeben sonst ein sandiges Mundgefühl.","Suppe und Sorbet unabhängig vorbereiten und erst am Tisch kombinieren.","Alkoholfreie Variante mit Sprudelwasser oder Holunderblütenschorle.","Frische Minze nur kurz ziehen lassen, sonst wird die Suppe grasig."],"varianten":["Mit Heidelbeeren oder Himbeeren statt Brombeeren.","Mit Joghurt-Eis statt Sauerrahm-Sorbet.","Warm serviert zu Pfannkuchen."],"beilagen":["Mürbe Plätzchen (zum Beispiel die Gingersnaps)"],"getraenk":"Champagner, Sekt oder Holunderblütenschorle","koeche":[{"name":"Marcus Samuelsson","bezug":"Samuelsson hat die Brombeersuppe mit Sauerrahm-Sorbet und Champagner als Dessert veröffentlicht; Food Network nennt sie einfacher, als sie klingt.","quelle":"https://www.foodnetwork.com/recipes/marcus-samuelsson/champagne-infused-blackberry-soup-with-sour-cream-sorbet-recipe-1965161"}],"quellen":[{"titel":"Food Network – Champagne-Infused Blackberry Soup with Sour Cream Sorbet (Marcus Samuelsson)","url":"https://www.foodnetwork.com/recipes/marcus-samuelsson/champagne-infused-blackberry-soup-with-sour-cream-sorbet-recipe-1965161"}],"bild":"dessert","farben":["#4a1a4a","#7a2a6a","#e8d0e0"],"schlagworte":["Fruchtsuppe","Beeren","Sorbet","Festlich"],"vegetarisch_moeglich":true}]);
